/* Evolvlings: path conversations of era 2, La Calma (the ten eras plan, https://claude.ai/artifact/RFy6uGdhz9DJeW7e9ZfdkE).
   Same format as the zone files (see rpg/events-aurora.js). These events only come up while the Glade lives in era 2:
   need.era says so (lore.js needOk), and need.layer counts the guardians beaten since the era began.
   The nine peoples you bring together in this era set the u2_* flags; with all nine, the final dilemma offers
   the Línea Cerrada (rpg/data-eras.js derives e2_nueve). The m2_* flags are the marks this era leaves on the next.
   Loaded after the zone files (it adds to them). English text: rpg/events-era2.en.js. */
window.EVEVENTS = window.EVEVENTS || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ---------- Prado Aurora: la Ley del Regreso, el Coro de Cosecha y la Velada Negra ---------- */
  add("aurora", {
    "e2-ley": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { cirio: "Cirio, guarda del tablón", umbria: "Umbría" }, start: "a", nodes: {
      a: { say: [[null, "El tablón del Vado tiene un papel nuevo, clavado con cuatro clavos en vez de uno. Un guarda joven lo vigila con los brazos cruzados. Arriba, en letras grandes: LEY DEL REGRESO."],
                 ["cirio", "Léelo en voz alta si quieres, que hoy nadie más se acerca. Me llamo Cirio y me toca cuidarlo hasta que se seque la tinta."],
                 [null, "Detrás de ti, una mujer de la Sombra con dos niños de la mano espera a que te apartes para leerlo ella."]],
           opts: [{ t: "Leer el decreto", go: "leer", once: true },
                  { t: "«¿Qué pasa si alguien no vuelve?»", go: "si", once: true },
                  { t: "Hablar con la mujer de los niños", go: "madre", once: true },
                  { t: "Firmar como testigo, como pide el pie del papel", go: "firmar" },
                  { t: "Arrancar el decreto del tablón", go: "arrancar" },
                  { t: "Irte sin decir nada", go: "irte" }] },
      leer: { say: [[null, "«El Envés está curado. Las familias de la Noche volverán a sus tierras antes de la primera helada. Las Siete Casas pagarán el viaje. Quien no vuelva perderá el permiso del Umbral.»"],
                    [null, "Al pie, una línea para testigos. Ya hay cuarenta firmas. Casi todas son de gente del Prado."],
                    ["cirio", "Dicen que allá abajo ya no hay savia. Que está todo limpio. Yo no he bajado nunca, pero lo dicen las Casas."]], back: "a" },
      si: { say: [["cirio", "Pierde el permiso. Sin permiso no se cruza el Umbral, y sin cruzar el Umbral no se trabaja en el Prado."],
                  ["cirio", "No es crueldad, Cuidador. Es que aquí ya no cabemos. Mi hermana duerme en la cocina desde que le dieron el cuarto a una familia de la Hondonada."],
                  [null, "Lo dice sin mirar a la mujer de los niños, que lo escucha todo."]], back: "a" },
      madre: { say: [["umbria", "Me llamo Umbría. No le hagas caso al guarda, no es mala persona. Solo repite."],
                     ["umbria", "Mi marido bajó a ver la Hondonada la semana pasada. Dice que está limpia, sí. Y que la niebla no respira. Que las casas no hacen sombra. Que tocó la pared de la nuestra y estaba tibia, como un animal muerto hace poco."],
                     ["umbria", "Los niños nacieron aquí arriba. Para ellos el Envés es un cuento. ¿Cómo se vuelve a un cuento?"]],
               opts: [{ t: "«Pueden quedarse en mi casa del Vado.»", go: "esconder", fx: { cost: 30 } },
                      { t: "«¿Qué necesitan para el viaje?»", go: "viaje", once: true },
                      { t: "Volver al tablón", back: "a" }] },
      viaje: { say: [["umbria", "Nada que tú tengas. Las Casas pagan el carro, la manta y el pan de tres días. Muy generosas."],
                     ["umbria", "Lo que no pagan es la vuelta, si allá abajo no se puede vivir. Eso no está en el papel."]], back: "madre" },
      firmar: { say: [[null, "Firmas debajo de las otras cuarenta. Cirio sopla la tinta con mucho cuidado, como si fuera importante que no se corriera."],
                      ["cirio", "Gracias. Si firma un Cuidador, la gente se lo cree más."],
                      [null, "Cuando te das la vuelta, Umbría ya se ha ido con los niños. En el barro quedan las huellas de los tres, hacia la verja."]], end: { coins: 25, xp: 6, flag: "m2_leyFirma" } },
      arrancar: { say: [[null, "Tiras del papel. Los cuatro clavos aguantan y el decreto se rompe por la mitad, con un ruido que se oye en toda la plaza."],
                        ["cirio", "¿Qué haces? ¡Eso lo firmó la matriarca!"],
                        [null, "Cirio llama a los guardas. Mañana habrá otro papel, con ocho clavos. Pero hoy, en el tablón, solo queda la mitad de abajo: las cuarenta firmas sin nada encima."]], end: { fight: true, xp: 12, flag: "m2_leyArranca" } },
      esconder: { say: [[null, "Umbría te mira mucho rato. Luego le dice algo a los niños en la lengua de la Corte, y el más chico se esconde detrás de ella."],
                        ["umbria", "No te lo voy a agradecer todavía. Primero veamos si las Casas vienen a buscarnos."],
                        ["umbria", "Pero si no vienen, el Barrio se va a enterar de que en el Vado hay una puerta que se abre. Y eso, Cuidador, vale más que tu casa."]], end: { xp: 14, flag: ["m2_leyEsconde", "u2_barrio"] } },
      irte: { say: [[null, "Al rato, desde lejos, ves a Umbría leyendo el papel con un dedo, palabra por palabra, mientras el más chico le tira de la falda."]], end: { xp: 3 } },
    } },

    "e2-coro": { kind: "encuentro", need: { era: 2, layer: 1 }, who: { nim: "Nim", tila: "Tila", capataz: "Maestra de coro" }, start: "a", nodes: {
      a: { say: [[null, "En el Barrio Apagado han puesto una tarima bajo el último farol. Sobre ella, por parejas, chicos de Luz y chicos de Sombra cantan por turnos. Una maestra de coro marca el ritmo con una vara. Cada vez que una pareja termina, el farol brilla un poco más."],
                 ["capataz", "¡Juntos! ¡Las dos nanas a la vez, como en el Vado! La matriarca quiere luz para todo el Barrio antes del invierno."],
                 [null, "En la tercera pareja, cantando con una niña de Luz que no conoce, está Nim. Canta bien. No mira a nadie."]],
           opts: [{ t: "Escuchar cómo suena", go: "suena", once: true },
                  { t: "Buscar a Tila entre la gente", go: "tila", once: true },
                  { t: "Subir a la tarima y cantar con ellos", go: "cantar" },
                  { t: "Desafinar a propósito, muy fuerte", go: "sabotear" },
                  { t: "Esperar a que Nim baje y sacarlo de ahí", go: "sacar" }] },
      suena: { say: [[null, "Suena bonito y no suena a nada. Las dos nanas van juntas, nota con nota, pero cada chico mira hacia otro lado. La savia no retrocede ni un palmo."],
                     [null, "Al pie de la tarima, sobre un trapo, hay tres cositas brillantes del tamaño de un puño. Son Estrellas. No hacen ruido. Una ya se ha apagado del todo."],
                     ["capataz", "Salen solas, a veces. No sirven para nada. Se apagan en dos o tres días."]], back: "a" },
      tila: { say: [["tila", "Aquí estoy, mirando cómo me copian. Cuando lo hicimos Nim y yo, fue porque quisimos. Esto es una fila de chicos a los que les pagan media ración por cantar."],
                    ["tila", "Se lo dije a la matriarca. Me contestó que yo era la prueba de que funcionaba. Que gracias a mí el Barrio iba a tener luz. Y lo peor es que lo dijo de verdad."],
                    ["tila", "Mira esas Estrellas. Así es como suena una promesa que nadie quiso hacer."]], back: "a" },
      cantar: { say: [[null, "La maestra te pone al lado de un chico de Sombra que tiembla un poco. Cantan. El farol brilla. Todos aplauden."],
                      [null, "A tus pies cae una Estrella nueva, del tamaño de una nuez. Te mira sin boca. Brilla tres segundos más que las otras y se queda quieta."],
                      ["capataz", "¡Ven mañana! Con un Cuidador en la tarima, el Barrio canta el doble."]], end: { coins: 30, xp: 8, flag: "m2_coroCanta" } },
      sabotear: { say: [[null, "Te metes entre las parejas y cantas fuerte y mal. Una pareja se ríe, otra se para. La maestra golpea la tarima con la vara."],
                        ["capataz", "¡Fuera! ¡Guardas!"],
                        [null, "Nim aprovecha el desorden para bajarse de la tarima. Al pasar a tu lado, sin mirarte, dice muy bajito: «Gracias. Mañana vuelvo, igual. Pagan»."]], end: { fight: true, xp: 10, flag: "m2_coroSabotea" } },
      sacar: { say: [[null, "Cuando la pareja de Nim termina, lo esperas al pie de la tarima. Está pálido, como si hubiera cantado con la garganta de otro."],
                     ["nim", "No me saques de aquí como a un niño, que no lo soy. Canto porque mi madre come de lo que me pagan."],
                     ["nim", "Pero si de verdad quieres ayudar, llévate eso."],
                     [null, "Señala la Estrella más chica del trapo, la que todavía brilla un poco. Unísona la mira y canta una sola nota. La Estrella se mueve."]],
               opts: [{ t: "Llevarte la Estrella", go: "estrella" }, { t: "Llevarte a Nim, aunque proteste", go: "nimlejos" }] },
      estrella: { say: [[null, "La envuelves en tu bufanda. No pesa nada. Unísona camina a tu lado todo el regreso, mirándola, como se mira a un hermano chico enfermo."],
                        ["nim", "Ponle nombre. A las que tienen nombre les cuesta más apagarse. Eso decía mi madre de los niños, y creo que vale para todo."]], end: { xp: 12, flag: ["m2_coroNim", "e2_mudo"] } },
      nimlejos: { say: [["nim", "Si me llevas, mañana ponen a otro. A uno más chico, que canta peor y le pagan menos."],
                        [null, "Pero baja contigo. En la puerta del Barrio se para, mira la tarima y canta solo, bajito, su nana entera. Nadie le paga. El farol no brilla más."],
                        ["nim", "Esa era para mí."]], end: { xp: 10, flag: ["m2_coroNim", "e2_nimLejos"] } },
    } },

    "e2-velada": { kind: "dialogo", need: { era: 2, layer: 2 }, who: { destello: "Lucerna Destello", alvar: "Alvar" }, start: "a", nodes: {
      a: { say: [[null, "Es la noche más larga del año. Todas las Casas del Prado encienden a la vez todos sus faroles. El cielo se pone blanco. Hay música, pan dulce y gente bailando en las plazas."],
                 [null, "En el balcón de la Torre del Alba, una mujer joven con el pelo atado y el vestido sencillo saluda a la multitud. No lleva joyas. Los del Barrio la aplauden más fuerte que nadie."],
                 ["alvar", "Esa es la matriarca nueva. Lucerna Destello. Nació en el Barrio Apagado, ¿sabías? La primera que no es de una Casa vieja."],
                 [null, "Alvar ha crecido. Lleva las botas sucias de barro y no parece importarle."]],
           opts: [{ t: "«¿Y tu abuela?»", go: "abuela", once: true },
                  { t: "Mirar el suelo de la plaza", go: "suelo", once: true },
                  { t: "Subir al balcón a hablar con la matriarca", go: "balcon" },
                  { t: "Romper el farol grande de la plaza", go: "romper" },
                  { t: "Bailar con la gente", go: "bailar" }] },
      abuela: { say: [["alvar", "La apartaron. Dicen que por lo de los tubos. Ella dice que se lo merece, y luego se pasa la tarde dando órdenes a las macetas."],
                      ["alvar", "Hoy no vino. Dijo que una Velada con todos los faroles prendidos le daba miedo. Que su abuela le contó algo de una deuda que no se paga al sol. Yo no le entendí."]], back: "a" },
      suelo: { say: [[null, "Entre las piedras de la plaza, en las juntas, hay algo oscuro. Al principio parece sombra. Luego ves que se mueve, despacio, como agua que sube."],
                     [null, "Te agachas. Huele a tierra mojada y a algo dulce y podrido. Bajo los pies de los que bailan, la savia clara se está volviendo negra."]], fx: { flag: "e2_vistoSuelo" }, back: "a" },
      balcon: { say: [["destello", "El Cuidador. Pasa, pasa, que hoy la Torre es de todos."],
                      ["destello", "¿Ves eso? Hace un año, en mi calle, se encendía un farol de cada tres. Hoy no queda una puerta del Barrio a oscuras. Eso lo hicimos nosotros, no Albor."]],
                opts: [{ t: "«La savia está subiendo por la plaza.»", go: "aviso", cNeed: "e2_vistoSuelo" },
                       { t: "«¿De dónde sale tanta luz?»", go: "donde", once: true },
                       { t: "«Felicidades.»", go: "felicidades" }] },
      donde: { say: [["destello", "De abajo, como siempre. La diferencia es que ahora llega a todos."],
                     ["destello", "Sé lo que me vas a decir, Cuidador. Que Albor bebía de la Raíz. Ya lo sé. Por eso cavamos más hondo, donde no molesta a nadie. Lo comprobaron mis ingenieros."]], back: "balcon" },
      aviso: { say: [[null, "Destello baja la vista hacia la plaza. Por un momento se le borra la sonrisa. Luego vuelve."],
                     ["destello", "Es la sombra de tanta gente bailando. Esta noche no, Cuidador. Esta noche el Barrio tiene luz. Mañana miramos el suelo, te lo prometo."],
                     ["alvar", "Yo lo vi también. Si quieres, mañana se lo cuento a las Casas viejas. A mí todavía me abren la puerta."]],
               opts: [{ t: "«Hazlo, Alvar. Que lo sepan todas las Casas.»", go: "alvarsi" }, { t: "Dejarlo para mañana", go: "manana" }] },
      alvarsi: { say: [["alvar", "Mañana temprano. Aunque me echen. Ya me echaron de cosas peores."],
                       [null, "Abajo, sin que nadie más lo note, la última junta de la plaza se pone negra."]], end: { xp: 16, flag: ["e2_avisaste", "u2_luz"] } },
      manana: { say: [[null, "A la mañana siguiente, el Prado amanece con manchas negras en todas las plazas. Las Casas dicen que fue sabotaje de la Sombra."]], end: { xp: 8, flag: "e2_avisaste" } },
      felicidades: { say: [["destello", "Gracias. De verdad. Eres de los pocos que lo dicen sin pedirme nada a cambio."],
                           [null, "Desde el balcón, la plaza se ve preciosa. Desde aquí arriba no se ve el suelo."]], end: { coins: 20, xp: 6 } },
      romper: { say: [[null, "Le tiras una piedra al farol grande. El cristal se raja y la luz parpadea. La música se para. Alguien grita «¡sombras!» y la gente se aparta de los del Barrio."],
                      [null, "No era lo que querías. Pero en la oscuridad del farol roto, bajo tus pies, el suelo deja de oscurecerse. Un palmo. Solo un palmo."]], end: { fight: true, xp: 12, flag: "e2_rompiste" } },
      bailar: { say: [[null, "Bailas hasta que te duelen los pies. Tus criaturas también. Es la mejor fiesta en años. Nadie mira al suelo, y tú tampoco."]], end: { xp: 6, heal: 0.2 } },
    } },
  });

  /* ---------- Cráter Tibio: tubos más largos y la capataz ---------- */
  add("crater", {
    "e2-tubos": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { tizon: "Maese Tizón", fogarin: "Fogarín" }, start: "a", nodes: {
      a: { say: [[null, "En la forja grande hay tubos de cristal por todas partes, apoyados en las paredes como lanzas. Son tres veces más largos que los que salían de aquí el año pasado."],
                 ["tizon", "No los toques, que todavía están tibios. Encargo de la matriarca nueva. Doscientos. Paga por adelantado, ¿te das cuenta? Por adelantado. Albor nunca pagó por adelantado."],
                 [null, "Al fondo, un muchacho con quemaduras viejas en los brazos sopla el fuelle sin decir nada. Es Fogarín, el aprendiz. Ya no es tan aprendiz."]],
           opts: [{ t: "«¿Para qué son tan largos?»", go: "para", once: true },
                  { t: "Hablar con Fogarín", go: "fogarin", once: true },
                  { t: "«Maese, estos tubos beben de la Raíz.»", go: "decir" },
                  { t: "Romper uno «sin querer»", go: "romper" },
                  { t: "Ayudar a cargar el pedido", go: "cargar" }] },
      para: { say: [["tizon", "Para llegar más hondo, dice. Donde no molesten. No pregunté más. En el Consejo de las Casas tengo silla desde hace un mes, y un Fuego con silla aprende rápido qué preguntas no se hacen."],
                    ["tizon", "Antes no me dejaban entrar por la puerta de delante. Ahora me sirven primero. No me pidas que lo eche a perder por una corazonada."]], back: "a" },
      fogarin: { say: [["fogarin", "Yo soplo, no opino. Eso me enseñó el maestro."],
                       ["fogarin", "Pero te digo una cosa. Cuando una muchacha del Agua trabajaba aquí, me dijo que el cristal largo canta cuando lo enfrías. Este no canta. Este suena como alguien que traga."]], back: "a" },
      decir: { say: [["tizon", "¿Y eso quién lo dice? ¿Una vidente del lago? ¿Una sombra?"],
                     [null, "Pero deja el martillo en el yunque. Mucho rato."],
                     ["tizon", "Mi padre hacía la Noche de Ascuas. Apagaba todos los fuegos del Cráter y encendía uno solo, una noche al año. Decía que era para que la tierra descansara. Nosotros nos reíamos de él."]],
              opts: [{ t: "«Haga la Noche de Ascuas este año.»", go: "ascuas" },
                     { t: "«Venga al Corazón cuando lo llame.»", go: "corazon", cNeed: "tizonFriend" },
                     { t: "No insistir", back: "a" }] },
      ascuas: { say: [["tizon", "¿Apagar el Cráter una noche, con doscientos tubos por entregar? Me echan del Consejo antes del amanecer."],
                      ["tizon", "Pero, mira, puedo entregar ciento noventa. Diez se rompen. Pasa en todas las forjas. Nadie cuenta los vidrios rotos."]], end: { xp: 14, flag: "e2_tizonSabe" } },
      corazon: { say: [["tizon", "Tú me pagaste entero cuando nadie lo hacía. Eso no se me olvida."],
                       ["tizon", "Si un día suena algo en el Corazón y el Fuego tiene que estar, el Fuego va a estar. Aunque sea yo solo, con el martillo y las rodillas malas."]], end: { xp: 18, flag: ["e2_tizonSabe", "u2_fuego"] } },
      romper: { say: [[null, "Te apoyas donde no debes. Un tubo cae y se hace añicos. Tizón te mira con la cara roja."],
                      ["tizon", "Eso te lo descuento de lo que nunca te voy a pagar. Fuera de mi forja."],
                      [null, "Al salir, Fogarín te alcanza y te pone en la mano un trozo de cristal. Por dentro tiene una veta negra, fina como un pelo."]], end: { xp: 10, flag: "e2_cristalNegro", hurt: 0.05 } },
      cargar: { say: [[null, "Cargas tubos toda la tarde. Tizón te paga con monedas nuevas, con el sello de Destello. Pesan más que las de Albor."]], end: { coins: 40, xp: 5 } },
    } },

    "e2-brida": { kind: "dialogo", need: { era: 2, layer: 2 }, who: { brida: "Brida, capataz" }, start: "a", nodes: {
      a: { say: [[null, "En la plaza de las termas, una mujer de la Sombra con un casco de minero apunta nombres en una tabla. Una fila de obreros del Cráter espera turno. En la tabla dice: SE BUSCAN CAVADORES. PAGO DOBLE. NO SE PREGUNTA DE DÓNDE VIENES."],
                 ["brida", "¿Vienes a trabajar? Tienes manos de trabajar. Aquí todo el mundo tiene nombre, Cuidador. Yo me llamo Brida. Me lo gané."]],
           opts: [{ t: "«¿Cómo se gana un nombre?»", go: "nombre", once: true },
                  { t: "«¿Dónde se cava?»", go: "donde", once: true },
                  { t: "Apuntarte en la tabla", go: "apuntar" },
                  { t: "Avisar a los de la fila de lo que hay abajo", go: "avisar" },
                  { t: "«Te ofrezco otro trabajo, en el Vado.»", go: "otro", cNeed: "m2_leyEsconde" }] },
      nombre: { say: [["brida", "Trabajando. Cuando llegamos de la Hondonada, a los de la Corte nos llamaban «la del polvo», «el de la tercera fila». En los Pozos de Albor nadie decía nuestros nombres, y nosotros tampoco: el Rey lo prohibía."],
                      ["brida", "La matriarca nueva me preguntó cómo me llamaba. La primera persona de arriba que me lo preguntó. Le dije uno que me inventé esa misma mañana. Lo apuntó como si fuera de verdad."],
                      ["brida", "Por esa mujer yo cavo hasta el fondo del mundo."]], back: "a" },
      donde: { say: [["brida", "Bajo el Prado, más hondo que Albor. Pozos nuevos. Los llaman ciegos porque no tienen boca arriba: se entra por túneles desde lejos, para que no los vea nadie."],
                     ["brida", "¿Por qué tan escondidos? Para que no nos los sabotee nadie. Ya hubo quien rompió faroles en la Velada."]], back: "a" },
      apuntar: { say: [["brida", "Bien. Mañana a la hora de la ceniza, en la boca del túnel sur. Trae agua. Allá abajo hace un calor raro, como de animal."],
                       [null, "Te da una ficha de madera con un número. El tuyo es el 312."]], end: { coins: 35, xp: 6, flag: "e2_ficha" } },
      avisar: { say: [[null, "Te subes al borde de una fuente y dices lo que sabes de los Pozos y la Raíz. Algunos de la fila se van. La mayoría se queda: el pago es doble."],
                      ["brida", "Muy bonito. Ahora explícales a sus hijos por qué esta semana no comen."],
                      [null, "No grita. Te mira con el casco en la mano, como se mira a alguien que no entendió nada."]], end: { fight: true, xp: 12, flag: "e2_avisoFila" } },
      otro: { say: [["brida", "¿En el Vado? ¿Cuidando qué, criaturas? ¿Cuánto paga eso?"],
                    ["brida", "Me contaron que escondes a una familia de la Corte. Umbría. La conozco: éramos vecinas en los Pozos. Ella se negó a ponerse un nombre falso."],
                    [null, "Brida se queda callada. Tacha algo en la tabla. No se ve qué."],
                    ["brida", "No me voy a ir de los Pozos. Pero si un día abajo pasa algo, te aviso a ti antes que a la matriarca. Eso puedo hacerlo."]], end: { xp: 16, flag: "e2_bridaAvisa" } },
    } },
  });

  /* ---------- Bosque Hondo: demasiada fruta y el Largo Silencio ---------- */
  add("forest", {
    "e2-fruta": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { liquen: "Abuelo Liquen", llovizna: "Llovizna" }, start: "a", nodes: {
      a: { say: [[null, "Las ramas del Bosque Hondo se doblan de tanta fruta. Manzanas, bellotas, moras, todo a la vez y fuera de estación. Hay tanta en el suelo que el camino huele a vino."],
                 ["llovizna", "¡Cuidador! ¡Mira cuántas! El Concejo dice que es la Savia Clara, que la Raíz nos devuelve lo que le quitamos."],
                 [null, "Un poco más allá, sentado en una raíz, el Abuelo Liquen mira un manzano muy cargado. No come."]],
           opts: [{ t: "Ayudar a Llovizna a juntar fruta", go: "juntar" },
                  { t: "Sentarte con el anciano", go: "liquen", once: true },
                  { t: "Cortar una rama para ver qué tiene dentro", go: "rama", once: true },
                  { t: "«Abuelo, hay que llamar al Largo Silencio.»", go: "silencio", cNeed: "e2_venas" }] },
      juntar: { say: [[null, "Llenan dos canastas. Las manzanas son enormes y dulces, demasiado dulces. Tus criaturas comen hasta quedarse dormidas."],
                      ["llovizna", "¡Este año nadie pasa hambre en el Bosque!"]], end: { xp: 6, heal: 0.25 } },
      liquen: { say: [["liquen", "Este año el bosque dio más fruta que nunca. Eso es lo que me asusta."],
                      ["liquen", "Cuando yo era un niño, en el Bosque de donde vine, pasó lo mismo. Un otoño de fruta como este. El invierno siguiente no quedó nada. Los árboles se habían comido la tierra para dar fruta, como una madre que se quita el pan."],
                      ["liquen", "Y el Seto se marchita a destiempo. Mira. Las espinas que planté para cerrar el paso se caen solas, con flores negras en la punta."]], back: "a" },
      rama: { say: [[null, "Cortas una rama del manzano. Por fuera está verde. Por dentro, en el corazón de la madera, corre una vena fina y negra, como tinta."],
                    [null, "Llovizna se tapa la boca. Liquen asiente despacio, como si ya lo supiera."]], fx: { flag: "e2_venas" }, back: "a" },
      silencio: { say: [["liquen", "¿Ahora? ¿En otoño? El Largo Silencio es en invierno. Si lo llamo antes, el Concejo va a decir que el viejo de afuera ya no sabe ni en qué estación vive."],
                        ["liquen", "Hace años, en un Largo Silencio, la oí toser. No se lo conté a nadie. Por miedo a que abrieran la Cripta. Me lo guardé, y mira dónde estamos."]],
                  opts: [{ t: "«Esta vez no se lo guarde.»", go: "llama" }, { t: "«Entonces escúchela usted solo.»", go: "solo" }] },
      llama: { say: [["liquen", "Bien. Mañana toco el tronco hueco. Que se rían. El Bosque va a callar tres días, aunque haya fruta pudriéndose en el suelo."],
                     ["liquen", "Y si un día alguien canta en el Corazón y hace falta el Bosque, ahí va a estar el Bosque. Esa promesa sí la cumplo."]], end: { xp: 16, flag: ["e2_silencioLlamado", "u2_planta"] } },
      solo: { say: [[null, "Liquen pega la oreja al manzano. Tú también. Durante un largo rato no se oye nada."],
                    ["liquen", "No tose. Respira hondo, muy hondo, como quien duerme con hambre."]], end: { xp: 10, flag: "e2_respira" } },
    } },

    "e2-seto": { kind: "encuentro", need: { era: 2, layer: 2 }, who: { abrojo: "Abrojo, guarda del Seto" }, start: "a", nodes: {
      a: { say: [[null, "Donde antes estaba el Seto de espinas, ahora hay un muro marrón y seco. Al otro lado, en el camino al Envés, una fila de carros de la Ley del Regreso espera que la dejen pasar."],
                 ["abrojo", "El Concejo me mandó a abrir un hueco. Las Casas pagan para que los desplazados vuelvan por aquí, que es más corto."],
                 ["abrojo", "Lo raro es que el Seto no se deja. Le corto una rama y le salen dos. Secas, pero salen. Como si no quisiera que nadie volviera por aquí."]],
           opts: [{ t: "Ayudar a Abrojo a abrir el paso", go: "abrir" },
                  { t: "Hablar con la gente de los carros", go: "carros", once: true },
                  { t: "Tocar el Seto", go: "tocar", once: true },
                  { t: "Dejar el Seto cerrado", go: "cerrado" }] },
      carros: { say: [[null, "En el primer carro va un abuelo de las Mareas con una barca vieja atada encima. No hay agua en el camino, pero no quiso dejarla."],
                      [null, "«Dicen que el lago está curado», te dice. «Yo lo que quiero saber es si el lago me va a reconocer.»"]], back: "a" },
      tocar: { say: [[null, "Pones la mano en el muro seco. Está tibio. Por dentro, muy despacio, algo late. Las raíces del Seto bajaron hondo, mucho más de lo que Liquen quiso, y ahí abajo encontraron algo que beber."],
                     [null, "El Seto no es un muro. Es un abrazo que no quiere soltar."]], fx: { flag: "e2_setoBebe" }, back: "a" },
      abrir: { say: [[null, "Entre los dos cortan durante horas. Por fin se abre un hueco del ancho de un carro. El abuelo de la barca pasa primero. No da las gracias. Llora."],
                     ["abrojo", "Ya está. El Concejo va a estar contento. Las Casas también."]], end: { coins: 25, xp: 8, flag: "m2_setoAbierto" } },
      cerrado: { say: [["abrojo", "Si no abro, las Casas mandan a sus guardas con hachas, y ellos no van a tener cuidado con el Seto."],
                       [null, "Pero guarda la tijera. Los carros dan la vuelta, hacia el camino largo. Tardarán tres días más en llegar a un sitio que quizá no los quiere."]], end: { xp: 8, flag: "m2_setoCerrado" } },
    } },
  });

  /* ---------- Los Altos: los que bajan y el silencio de Céfira ---------- */
  add("heights", {
    "e2-bajan": { kind: "encuentro", need: { era: 2, layer: 1 }, who: { tormo: "Tormo, guarda del paso" }, start: "a", nodes: {
      a: { say: [[null, "Por el camino de los Altos baja una fila de gente con mantas al hombro. Familias enteras, con las cometas plegadas en la espalda como alas rotas."],
                 ["tormo", "Ya van cuarenta familias esta semana. Sin los tratos de la Dama del Coro, en los Altos no se come este invierno. Bajan al Prado a pedir."],
                 ["tormo", "Hace dos inviernos, yo cerraba este paso para que no subieran los de abajo. Ahora lo abro para que bajen los de arriba. Con la misma manta."]],
           opts: [{ t: "Repartir comida entre las familias", go: "comida", fx: { cost: 25 } },
                  { t: "«¿Por qué se rompieron los tratos?»", go: "tratos", once: true },
                  { t: "Indicarles el camino al Vado", go: "vado" },
                  { t: "Seguir subiendo sin parar", go: "seguir" }] },
      tratos: { say: [["tormo", "Porque alguien cantó en la plaza que la tormenta del éxodo nunca existió. Que la Dama mintió para cerrar los pasos."],
                      ["tormo", "Era verdad. Yo estaba en el paso esa semana. Cielo limpio. Pero ahora nadie confía en el Coro, nadie le vende nada a los Altos, y los que pagan son estos."]], back: "a" },
      comida: { say: [[null, "Reparten pan y fruta del Bosque entre los niños. Una niña con una cometa roja te da a cambio una pluma azul."],
                      [null, "«Para que el viento te encuentre», dice. Es lo que se dice en los Altos cuando no hay nada más que dar."]], end: { xp: 12, flag: "e2_plumaAzul" } },
      vado: { say: [[null, "Les explicas cómo llegar al Vado. Algunos se miran, inseguros. «¿Ahí no hay Ley del Regreso?», pregunta un hombre."],
                    [null, "No sabes qué contestarle."]], end: { xp: 6 } },
      seguir: { say: [[null, "Subes contra la corriente de gente. Nadie te pide nada. En los Altos no se pide; se espera."]], end: { xp: 3 } },
    } },

    "e2-cefira": { kind: "dialogo", need: { era: 2, layer: 2 }, who: { cefira: "Céfira", arpegio: "Arpegio" }, start: "a", nodes: {
      a: { say: [[null, "En la sala del Coro hay tres sillas. Una está vacía. En otra, un anciano descalzo mira la boca de una mujer para leerle los labios. La mujer, sentada en la tercera, no dice nada. Hace un año que no dice nada en público."],
                 ["arpegio", "Habla tú, que a ti te contesta. A mí ya solo me mira. Desde el juicio todo el mundo sabe que no oigo, y ella no soporta que yo sepa que ella sabe."]],
           opts: [{ t: "«Céfira, tu pueblo está bajando a pedir.»", go: "pueblo" },
                  { t: "«¿Por qué mintió con la tormenta?»", go: "mintio", once: true },
                  { t: "Hablarle con las manos, como hace Arpegio", go: "manos", cNeed: "arpegioSordo" },
                  { t: "Dejarla en paz", go: "paz" }] },
      mintio: { say: [["cefira", "Porque no había comida para todos. Si dejaba subir a la segunda ola, los Altos comían la mitad un invierno, y el siguiente no comía nadie."],
                      ["cefira", "Cerré los pasos y dije «tormenta», que es más fácil de perdonar que «no caben». Murió gente abajo. Lo sé. Lo cuento cada noche."],
                      [null, "Es lo primero que dice en un año. Arpegio se inclina hacia delante para leerlo."]], back: "a" },
      pueblo: { say: [["cefira", "Ya lo sé. Los veo desde la ventana. Mi silencio es lo único que les queda: si hablo, el Prado oye a la mentirosa del éxodo, y les cierran la puerta a ellos también."]],
                opts: [{ t: "«Hable en la plaza. Diga la verdad, y pida.»", go: "plaza" }, { t: "«Entonces siga callada.»", go: "callada" }] },
      manos: { say: [[null, "Haces con las manos lo poco que aprendiste de Arpegio: «yo», «escucho», «tú». Céfira se ríe por primera vez, una risa corta y rota."],
                     ["arpegio", "Le dijiste «yo te escucho a ti». Hace cuarenta años que nadie del Coro le dice eso."]], fx: { flag: "e2_manosCefira" }, back: "a" },
      plaza: { say: [["cefira", "¿Pedir? Los Altos nunca piden. Repartimos versos, llevamos mensajes. No pedimos."],
                     ["arpegio", "Yo puedo pedir. A mí ya me perdieron el respeto. No hay nada que perder."],
                     [null, "Céfira mira al anciano mucho rato. Luego se levanta."],
                     ["cefira", "Bajaré al Prado. Diré la verdad y pediré, los dos juntos. Y si alguna vez el Corazón llama a los nueve pueblos, los Altos irán. Por esta vez, sin vender nada."]], end: { xp: 18, flag: ["e2_cefiraHabla", "u2_altos"] } },
      callada: { say: [[null, "Céfira vuelve a mirar por la ventana. Arpegio suspira y te acompaña a la puerta."],
                       ["arpegio", "Callar también es una forma de mentir. Yo lo sé mejor que nadie."]], end: { xp: 6 } },
      paz: { say: [[null, "Al salir, oyes a Arpegio tararear una canción sin sonido. Sabe la melodía de memoria. Nunca la oyó."]], end: { xp: 3 } },
    } },
  });

  /* ---------- Hondonada Umbría: la niebla que no respira y los tres nombres ---------- */
  add("hollow", {
    "e2-vuelta": { kind: "encuentro", need: { era: 2, layer: 1 }, who: { calina: "Calina, tejedora de niebla" }, start: "a", nodes: {
      a: { say: [[null, "La Hondonada está limpia. No hay savia en las grietas ni olor a fiebre. Tampoco hay niebla. Las casas de la Corte, hechas para vivir en la penumbra, se ven desnudas bajo un cielo gris, como animales esquilados."],
                 ["calina", "Volvimos por la Ley. Veinte familias. Llevo tres días intentando tejer niebla y no sale. La Hondonada no respira."],
                 [null, "Calina tiene las manos llenas de hilos grises que se deshacen al tocarlos."]],
           opts: [{ t: "«¿Qué necesita la niebla para salir?»", go: "niebla", once: true },
                  { t: "Ayudarla a tejer", go: "tejer" },
                  { t: "Cantar la nana de la Sombra en el centro del valle", go: "cantar", cNeed: "nanaIgual" },
                  { t: "«Vuelvan al Prado. Esto no es vida.»", go: "volver" }] },
      niebla: { say: [["calina", "Antes salía sola, del suelo. La Raíz respiraba debajo y la Hondonada se llenaba de su aliento. Nosotros solo la peinábamos."],
                      ["calina", "Ahora la Raíz duerme tan hondo que no respira. Nos dijeron que el Envés estaba curado. Está curado como está curado un muerto: ya no le duele nada."]], back: "a" },
      tejer: { say: [[null, "Pasan la tarde con los hilos. No sale niebla, pero al anochecer Calina consigue un velo pequeño, del tamaño de un pañuelo, para la cuna de su nieta."],
                     ["calina", "Es poco. Pero es lo primero que hacemos aquí desde que volvimos."]], end: { xp: 10, heal: 0.1 } },
      cantar: { say: [[null, "Cantas en el centro del valle la nana que te enseñó Nim. Unísona canta contigo la otra mitad, la de la Luz."],
                      [null, "Del suelo sale una hebra de niebla, una sola, fina como un suspiro. Las veinte familias salen de sus casas a verla. Nadie habla hasta que se deshace."],
                      ["calina", "Respira. Poco, pero respira. Si un día se canta en el Corazón, la Corte tiene que estar. Yo me encargo de que estemos."]], end: { xp: 18, flag: ["e2_hebra", "u2_sombra"] } },
      volver: { say: [["calina", "¿Al Prado? ¿Sin permiso del Umbral? Allá ya no tenemos puerta, Cuidador. La Ley nos dejó sin sitio en los dos lados."]], end: { xp: 5 } },
    } },

    "e2-nombres": { kind: "dialogo", need: { era: 2, layer: 2 }, who: { ceniza: "Ceniza", lobrego: "Rey Lóbrego" }, start: "a", nodes: {
      a: { say: [[null, "En una casa vacía de la Hondonada, detrás de una cortina, se esconde una muchacha de la Sombra con la capucha muy calada. Al verte, se encoge."],
                 ["ceniza", "No digas mi nombre. Ya lo dijeron en la plaza del Prado. La matriarca nueva lo gritó, el mío y otros dos, delante de todos."],
                 ["ceniza", "Me llamo Ceniza. Eso lo puedes saber. El otro, el de verdad, ya lo sabe todo el Prado. Para la Corte, una sombra con el nombre dicho es una sombra muerta."]],
           opts: [{ t: "«¿Por qué lo hizo la matriarca?»", go: "porque", once: true },
                  { t: "«¿Qué le pasa a una sombra nombrada?»", go: "pasa", once: true },
                  { t: "Esconderla en el Vado", go: "vado" },
                  { t: "Llevarla ante el rey", go: "rey" },
                  { t: "Irte y dejarla tranquila", go: "irte" }] },
      porque: { say: [["ceniza", "Porque el rey confesó el pacto de los Pozos en la Noche Sin Luna. Las sombras recuperamos los nombres, y el barrio prestado se acabó."],
                      ["ceniza", "La matriarca se enojó. Dijo que si la Corte rompía el trato, ella también. Y leyó tres nombres de una caja que guardaba Albor."]], back: "a" },
      pasa: { say: [["ceniza", "Que cualquiera puede llamarla. Y la que es llamada por su nombre de verdad tiene que ir. No es ley, es lo que somos."],
                    ["ceniza", "Anoche alguien gritó mi nombre debajo de la ventana. Por suerte era un borracho y se equivocó de letra."]], back: "a" },
      vado: { say: [[null, "Ceniza te sigue hasta el Vado sin hablar. En la puerta, se quita la capucha. Tiene la cara muy joven y muy cansada."],
                    ["ceniza", "Aquí nadie sabe mi nombre de verdad. Por ahora. Gracias, aunque no sirva para siempre."]], end: { xp: 14, flag: "m2_cenizaVado" } },
      rey: { say: [[null, "En la tienda más grande, el Rey Lóbrego te recibe sin velo. Es la primera vez que le ves la cara: un hombre viejo, con las mejillas hundidas, que ya no parece rey."],
                   ["lobrego", "Ceniza. Te dije que no salieras."],
                   ["lobrego", "Confesé para que mi pueblo recuperara sus nombres, Cuidador, y lo único que conseguí fue que tres de ellos los perdieran del todo. Así son los arreglos. Uno paga y otro cobra."]],
             opts: [{ t: "«¿Qué necesita la Corte?»", go: "necesita" }, { t: "«Usted tuvo la culpa.»", go: "culpa" }] },
      necesita: { say: [["lobrego", "Un sitio donde un nombre no se pueda gritar. Y que alguien de arriba nos vea como algo más que una deuda."],
                        ["lobrego", "Si llamas a los pueblos al Corazón, la Corte irá. Con velo o sin velo. Ya no tengo nada que esconder."]], end: { xp: 18, flag: ["e2_lobregoViene", "u2_sombra"] } },
      culpa: { say: [["lobrego", "La tuve. Y tú también, y la matriarca, y la vieja Albor, y todos los que bebimos de esa luz."],
                     [null, "Ceniza se queda con él. El rey le pone una mano en el hombro, torpe, como alguien que nunca lo hizo."]], end: { xp: 10, flag: "e2_culpaRey" } },
      irte: { say: [[null, "Al salir oyes a alguien, a lo lejos, gritar un nombre que no conoces. La cortina se mueve."]], end: { xp: 3 } },
    } },
  });

  /* ---------- Lago Espejo: el lago ciego y la Estrella Muda ---------- */
  add("lake", {
    "e2-ciego": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { marejada: "Madre Marejada", orilla: "Orilla" }, start: "a", nodes: {
      a: { say: [[null, "El Lago Espejo ya no refleja. El agua está limpia y quieta, pero al asomarte no ves tu cara, ni el cielo, ni nada. Solo un gris liso, como un ojo con catarata."],
                 ["marejada", "Volvimos porque nos dijeron que el lago estaba curado. Y lo está. No tiene savia. No tiene nada. Llevo una semana mirándolo y no me enseña ni el mañana ni el ayer."],
                 [null, "A su lado, Orilla lee su cuaderno de hule en voz baja, pasando páginas viejas."]],
           opts: [{ t: "«¿Qué le pasó al lago?»", go: "paso", once: true },
                  { t: "Hablar con Orilla", go: "orilla", once: true },
                  { t: "Meter la mano en el agua", go: "mano", once: true },
                  { t: "«Madre, cuente a su gente lo que vio hace treinta años.»", go: "contar", cNeed: "orillaContara" },
                  { t: "Dejarles algo de comer", go: "comer", fx: { cost: 20 } }] },
      paso: { say: [["marejada", "La Raíz duerme. El lago es el ojo de la Raíz: cuando ella ve, el lago ve. Ahora tiene los ojos cerrados."],
                    ["marejada", "Lo que nadie dice es que una madre que duerme así no despierta para dar de comer a sus hijos."]], back: "a" },
      orilla: { say: [["orilla", "Estoy buscando en el cuaderno de mi madre si esto ya pasó antes. Una vez. Hace mucho. La letra es muy vieja, no es de ella."],
                      ["orilla", "Dice: «El lago no reflejó en tres generaciones, hasta que la Cantora lloró en él». No dice por qué lloró."]], back: "a" },
      mano: { say: [[null, "El agua está tibia. Al sacar la mano, en tu palma queda por un segundo un reflejo que no es tuyo: una mujer con la boca abierta, de piedra. Luego se borra."]], fx: { flag: "e2_reflejoCantora" }, back: "a" },
      contar: { say: [["marejada", "Ya lo saben. Orilla lo contó. Y desde entonces la mitad me mira como a una mentirosa y la otra mitad como a una cobarde."],
                      ["marejada", "Pero tienes razón en una cosa. Lo que no cuente yo, lo va a contar la orilla del lago cuando se seque."],
                      [null, "Esa noche, en la orilla, Marejada habla ante todas las Mareas. No dice mucho. Termina pidiendo perdón. Algunos se van. La mayoría se queda."],
                      ["orilla", "Si un día hay que cantar en el Corazón, las Mareas van a ir. Juntas, por primera vez en treinta años."]], end: { xp: 18, flag: ["e2_marejadaHabla", "u2_agua"] } },
      comer: { say: [[null, "Les dejas pan y fruta. Marejada lo acepta sin mirarte. «No es orgullo», dice Orilla. «Es que le cuesta aceptar cosas que no vio venir.»"]], end: { xp: 8 } },
    } },

    "e2-mudo": { kind: "encuentro", need: { era: 2, layer: 2 }, who: { nasa: "Abuela Nasa" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla, entre las barcas varadas, una anciana tiene algo envuelto en una red de pesca. Brilla un poco. Es una Estrella del tamaño de un puño, sin boca, quieta."],
                 ["nasa", "La trajo el agua esta mañana. Del Prado, digo yo, que es de donde viene todo lo que sobra. No hace ruido. No come. Mira."],
                 [null, "Unísona se acerca sola. La Estrella sin boca levanta un poco la luz, como quien levanta la cabeza."]],
           opts: [{ t: "Dejar que Unísona le cante", go: "unisona" },
                  { t: "«¿Cuántas como esta llegan?»", go: "cuantas", once: true },
                  { t: "Llevarla con la curandera del Fondo Blanco", go: "curandera" },
                  { t: "Dejarla en el agua", go: "agua" }] },
      cuantas: { say: [["nasa", "Esta semana, tres. Las otras dos llegaron apagadas. Los chicos las usan de piedras para tirar al agua. No rebotan."],
                       ["nasa", "En mis tiempos una Estrella era una vez en la vida, y había fiesta. Ahora flotan en la orilla como peces muertos."]], back: "a" },
      unisona: { say: [[null, "Unísona canta una nota larga y luego se calla, esperando. La Estrella Muda no tiene boca para contestar. Pero brilla al compás, una vez, dos veces."],
                       [null, "Cuando Unísona se calla, la Estrella sigue brillando. Más fuerte que antes."],
                       ["nasa", "Ahí tienes. Ya tiene a alguien que la escucha. Llévatela. Ponle nombre."]], end: { xp: 16, flag: "e2_mudo" } },
      curandera: { say: [[null, "La llevas en la mochila hasta el camino del Fondo Blanco. Cuando la sacas, ya no brilla."],
                         [null, "Unísona no canta en todo el regreso."]], end: { xp: 6, flag: "e2_mudaApagada" } },
      agua: { say: [[null, "La dejas en el agua. Se hunde despacio, brillando cada vez menos. El lago, que no refleja nada, refleja eso: una luz que se apaga."]], end: { xp: 4, flag: "e2_mudaApagada" } },
    } },
  });

  /* ---------- Cuevas del Eco: la Noche del Eco y el Pozo Ciego ---------- */
  add("caves", {
    "e2-noche": { kind: "encuentro", need: { era: 2, layer: 1 }, who: { basalto: "Primer Picador Basalto", pirita: "Pirita, picadora" }, start: "a", nodes: {
      a: { say: [[null, "Es la Noche del Eco. Las familias de la Hondura golpean dos piedras en la entrada de la Sala, como manda el rito, y dicen en voz alta el nombre de sus muertos. La cueva siempre contestaba con su voz."],
                 [null, "Esta noche la cueva no contesta. Golpe, nombre, silencio. Golpe, nombre, silencio."],
                 ["pirita", "Desde que se llevaron el verso de la Guardiana, no contesta nadie. Mi padre murió el año pasado y no le he oído ni una vez."]],
           opts: [{ t: "Golpear tú también dos piedras", go: "golpear" },
                  { t: "Hablar con el Primer Picador", go: "basalto", once: true },
                  { t: "Cantar lo que Grava te enseñó", go: "grava", cNeed: "gravaSang" },
                  { t: "Irte en silencio", go: "irte" }] },
      golpear: { say: [[null, "Golpeas dos piedras. Suena seco, sin eco. Un niño de la Hondura te imita, más fuerte, como si fuera culpa de la fuerza."]], end: { xp: 5 } },
      basalto: { say: [["basalto", "No me mires así. Ya sé lo que piensas. Yo vendí los mapas. Tú te llevaste el verso. Entre los dos dejamos a la Hondura sin muertos."],
                       ["basalto", "Lo dice la piedra, que es la única que no miente: los que cavan con mis mapas bajo el Prado ya pasaron la Línea. Lo siento en las manos, como un temblor."]],
                 opts: [{ t: "«Venga al Corazón cuando llame. Hay que arreglarlo juntos.»", go: "juntos", cNeed: "basaltoConfiesa" }, { t: "Volver a la entrada", back: "a" }] },
      juntos: { say: [["basalto", "La Hondura nunca canta. Golpeamos piedras. Si me llamas, iré con dos piedras y el pueblo detrás."],
                      ["basalto", "Y te voy a decir algo que no le dije a nadie. La Guardiana repetía un verso que no era de ningún pueblo. Lo recuerdo a medias: «mientras nadie beba...». No sé el resto."]], end: { xp: 18, flag: ["e2_basaltoViene", "u2_piedra", "e2_mientras"] } },
      grava: { say: [[null, "Cantas los primeros versos que Grava cantó contigo. Al principio, nada. Luego, desde muy al fondo, débil, la cueva repite una palabra: «...beba...»."],
                     [null, "Las familias se quedan quietas. Pirita llora sin ruido."],
                     ["pirita", "Es ella. Todavía está ahí, en algún sitio. Si un día la Hondura tiene que ir al Corazón, la llevaremos a ella con nosotros."]], end: { xp: 18, flag: ["e2_ecoGrava", "u2_piedra", "e2_mientras"] } },
      irte: { say: [[null, "Detrás de ti siguen los golpes. Golpe, nombre, silencio. Toda la noche."]], end: { xp: 3 } },
    } },

    "e2-pozo": { kind: "encuentro", need: { era: 2, layer: 3 }, who: { brida: "Brida, capataz" }, start: "a", nodes: {
      a: { say: [[null, "Siguiendo un túnel nuevo, que no está en ningún mapa viejo de la Hondura, llegas a una sala enorme bajo el Prado. En el centro baja un tubo de cristal largo, larguísimo, hacia un agujero sin fondo. Es un Pozo Ciego."],
                 [null, "El tubo late. Sube luz por dentro, blanca y espesa, hacia el Prado. Alrededor, la roca suda savia negra."],
                 ["brida", "No deberías estar aquí. Nadie debería estar aquí. Ni yo."]],
           opts: [{ t: "«Brida, esto está matando a la Raíz.»", go: "matando", once: true },
                  { t: "Mirar dentro del agujero", go: "mirar", once: true },
                  { t: "Tapar el pozo con la roca suelta", go: "tapar" },
                  { t: "Llevarte un trozo del tubo para mostrarlo en la plaza", go: "denunciar" },
                  { t: "Dejarlo abierto: es la luz del Barrio", go: "abierto" }] },
      matando: { say: [["brida", "Ya lo sé. Lo sé desde la semana pasada, cuando a mi compañero se le pusieron negras las manos. Lo sabe la mitad de los cavadores."],
                       ["brida", "Pero si cierras esto, mañana el Barrio Apagado vuelve a estar apagado. Y la matriarca cae. Y a mí me quitan el nombre que me dio."]], back: "a" },
      mirar: { say: [[null, "Te asomas. Muy abajo, más abajo de lo que debería existir, algo enorme y oscuro se mueve en sueños. Cada vez que el tubo traga, se encoge, como quien siente frío."],
                     [null, "Unísona se tapa la cara con las patas. Le tiembla todo el cuerpo."]], fx: { flag: "e2_vistoFondo" }, back: "a" },
      tapar: { say: [[null, "Empujas roca suelta contra la boca del pozo. Brida, al principio, te mira. Luego te ayuda. Tardan toda la noche. El tubo se raja, la luz se apaga, el latido sigue."],
                     ["brida", "Arriba, una calle del Barrio se acaba de quedar a oscuras. Mañana me van a preguntar quién fue."],
                     ["brida", "Voy a decir que se derrumbó solo. Una vez en la vida voy a mentirle a ella."]], end: { xp: 22, flag: ["m2_pozoTapa"], hurt: 0.1 } },
      denunciar: { say: [[null, "Arrancas un trozo de tubo, todavía caliente, con savia negra pegada. Brida no te detiene."],
                         ["brida", "Muéstralo. Que lo vean. Pero no digas que lo encontraste aquí, o mañana cuelgan a los cavadores y la matriarca sigue igual."],
                         [null, "Al día siguiente, en la plaza del Prado, la gente mira el trozo de cristal y murmura. Destello sale al balcón y dice que es un sabotaje de la Sombra. Media plaza le cree."]], end: { xp: 18, fight: true, flag: "m2_pozoDenuncia" } },
      abierto: { say: [[null, "Te das la vuelta. A tus espaldas el tubo sigue latiendo, tragando, subiendo luz para mil faroles."],
                       ["brida", "Gracias. No te lo voy a olvidar. Ni yo ni el Barrio."],
                       [null, "Unísona no te sigue enseguida. Se queda mirando el agujero hasta que la llamas tres veces."]], end: { coins: 50, xp: 10, flag: "m2_pozoAbierto" } },
    } },
  });

  /* ---------- El Fondo Blanco: las setas que mueren y Los Que Oyen ---------- */
  add("deep", {
    "e2-setas": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { esporina: "Esporina", yesca: "Yesca, cultivadora" }, start: "a", nodes: {
      a: { say: [[null, "Los campos de setas del Fondo Blanco están grises. Los sombreros se caen solos, deshechos en polvo. Desde que la savia se aclaró, las setas que crecían sobre ella mueren."],
                 ["yesca", "Son las de los remedios. Las que curaban la fiebre de la savia. Sin ellas, los enfermos que se habían curado vuelven a caer."],
                 [null, "Al fondo, una mujer con un sombrero enorme cava un agujero en el hielo con una pala. Ya está metida hasta la cintura."]],
           opts: [{ t: "Hablar con la mujer de la pala", go: "esporina", once: true },
                  { t: "«¿Cuántos enfermos han recaído?»", go: "cuantos", once: true },
                  { t: "Ayudarla a cavar", go: "cavar" },
                  { t: "«Si cava ahí, la despierta. Pare.»", go: "parar" },
                  { t: "«Busquemos otro remedio, sin savia.»", go: "otro", cNeed: "e2_respira" }] },
      cuantos: { say: [["yesca", "Treinta en el Fondo. En el Prado no sé, allá no cuentan a los del Barrio."],
                       ["yesca", "La curandera dice que la cura del Corazón nos curó a todos menos a los que ya estaban curados. No sé si es un chiste."]], back: "a" },
      esporina: { say: [["esporina", "No me mires así, que no estoy loca. Las setas crecen donde la savia es espesa. La más espesa que queda está aquí abajo, debajo del hielo, donde nadie la durmió del todo."],
                        ["esporina", "Defendiste mis remedios, ¿te acuerdas? Me conseguiste permiso para curar de día. Pues este es el precio: para curar, necesito que la Raíz siga enferma un poco."]], back: "a" },
      cavar: { say: [[null, "Cavas con ella hasta que el hielo se pone oscuro. Debajo, una vena de savia negra, espesa como miel. Esporina llora de alivio."],
                     ["esporina", "Con esto curo a treinta. Con un poco más, a todo el Barrio."],
                     [null, "Bajo tus pies, muy hondo, algo se da vuelta en sueños."]], end: { xp: 10, coins: 20, flag: "m2_setaCava" } },
      parar: { say: [["esporina", "¿Y qué les digo a los treinta? ¿Que se aguanten porque el Cuidador tiene miedo de una raíz?"],
                     [null, "Pero deja la pala. Se sienta en el borde del agujero, con los pies colgando."],
                     ["esporina", "Está bien. Paro. Pero cuando se muera el primero, vas a venir tú a decírselo a su madre."]], end: { xp: 12, flag: "m2_setaPara" } },
      otro: { say: [["esporina", "¿Un remedio sin savia? Llevo veinte años buscándolo."],
                    ["esporina", "Aunque... el Abuelo Liquen dice que la Raíz respira. Si respira, sueña. Y si sueña, quizá los soñadores del Turno puedan... no, es una tontería."],
                    [null, "No es una tontería. Lo apunta en el sombrero, por dentro, con carbón."]], end: { xp: 16, flag: ["m2_setaPara", "e2_remedioSueno"] } },
    } },

    "e2-oyen": { kind: "dialogo", need: { era: 2, layer: 2 }, who: { nevisca: "Nevisca, soñadora del Turno", albina: "Regente Albina" }, start: "a", nodes: {
      a: { say: [[null, "En la sala del Turno, donde los soñadores velan la Tumba Helada, hay más gente que nunca. Están sentados en círculo, con los ojos cerrados, y repiten algo en voz baja, todos a la vez."],
                 ["nevisca", "El rey ha vuelto a hablar. Por primera vez en siglos, lo oímos de verdad. No como antes, cuando nos decían qué soñar."],
                 ["nevisca", "Dice que tiene sed. Que quiere despertar. Nos llamamos Los Que Oyen."]],
           opts: [{ t: "Sentarte en el círculo y escuchar", go: "escuchar" },
                  { t: "«¿Quién les decía antes qué soñar?»", go: "antes", once: true },
                  { t: "Ir a ver a la regente", go: "regente" },
                  { t: "Unirte a Los Que Oyen", go: "unirte" }] },
      antes: { say: [["nevisca", "La regencia. Todo el mundo lo sabe y nadie lo dice: los sueños del rey los escribía la Regente y nos los daba a aprender. Yo misma soñé dos años un sueño que ella escribió."],
                     ["nevisca", "Pero este no lo escribió nadie. Este viene de abajo."]], back: "a" },
      escuchar: { say: [[null, "Cierras los ojos. Al rato, en la oscuridad, sientes algo enorme que da vueltas, que tiene la boca seca, que no recuerda por qué prometió dormir."],
                        [null, "Abres los ojos con la garganta seca. Nevisca te sonríe. Tiene los labios agrietados, como todos los del círculo."]], end: { xp: 12, flag: "m2_oyenEscucha" } },
      regente: { say: [["albina", "Los Que Oyen. Qué nombre tan bonito para un montón de soñadores que dejaron de obedecer."],
                       ["albina", "Inventé los sueños del rey durante años. Estos no son míos. Y eso es lo que me da miedo, Cuidador: que por primera vez lo que sueñan es verdad, y la verdad pide algo terrible."]],
                 opts: [{ t: "«Dígales que usted inventó los sueños de antes.»", go: "verdad" }, { t: "«Hay que disolver el círculo.»", go: "disolver" }] },
      verdad: { say: [["albina", "¿Y quedarme sin regencia? ¿Sin nada que mantenga juntas a tres casas que se odian?"],
                      [null, "Pero baja a la sala. Ante el círculo, con la voz quebrada, cuenta cómo escribía los sueños. Muchos lloran. Algunos se van. Nevisca se queda."],
                      ["albina", "Ya está. Ya no soy nada. Si el Corazón llama a los pueblos, el Fondo Blanco irá, pero no detrás de mí: detrás de ustedes, que lo pidieron."]], end: { xp: 18, flag: ["e2_albinaConfiesa", "u2_escarcha"] } },
      disolver: { say: [["albina", "Por fin alguien con sentido común. Guardias."],
                        [null, "La guardia de la Tumba saca a los soñadores uno por uno. Nevisca, al pasar a tu lado, te mira con lástima."],
                        ["nevisca", "Pueden sacarnos de la sala. No pueden sacarnos el sueño."]], end: { xp: 10, fight: true, flag: "m2_oyenEntrega" } },
      unirte: { say: [[null, "Te dan una cinta gris para la muñeca. Desde esa noche, cada vez que duermes, oyes un poco más la sed de algo muy grande."]], end: { xp: 14, flag: "m2_oyenUnido" } },
    } },
  });

  /* ---------- Corazón del Claro: las cuatro estatuas, los coros rivales y la Raíz en Vela ---------- */
  add("heart", {
    "e2-estatuas": { kind: "encuentro", need: { era: 2, layer: 4 }, who: { cincel: "Cincel, escultor" }, start: "a", nodes: {
      a: { say: [[null, "Alrededor del Tocón, la tierra se ha hundido con la Calma. Donde antes había una estatua cubierta de musgo, ahora asoman cuatro, enterradas a distintas alturas, como escalones."],
                 ["cincel", "Llevo cuarenta años limpiando la de la Cantora y nunca supe que tenía hermanas. Mira las bocas. Las cuatro, abiertas a mitad de una nota."]],
           opts: [{ t: "Mirar la estatua más honda", go: "honda", once: true },
                  { t: "Mirar la del medio", go: "medio", once: true },
                  { t: "Limpiar la base de la Cantora", go: "base" }] },
      honda: { say: [[null, "La más honda tiene la cara borrada. No por el tiempo: a golpes. Alguien se tomó mucho trabajo para que nadie supiera quién era."],
                     ["cincel", "Esto es de cincel. De uno muy viejo. Un escultor no borra una cara así. Esto lo hace alguien que tiene vergüenza."]], back: "a" },
      medio: { say: [[null, "Dos de las estatuas del medio son dos figuras de la mano, una con escarcha en el pelo y otra con un sombrero de seta. La otra tiene escoria de forja pegada en la base, como si se hubiera vuelto piedra trabajando."],
                     ["cincel", "El Herrero Sin Nombre. Los de la Brasa le rezan. Creen que es suyo y de nadie más. Mira dónde está: por debajo de la Cantora. Antes que ella."]], back: "a" },
      base: { say: [[null, "Con un cepillo y agua quitas el musgo de la base de la Cantora. Debajo hay letras, gastadas pero legibles. No es un verso de ningún pueblo. Es una frase sola:"],
                    [null, "«Dormiré mientras nadie beba por debajo de mis sueños.»"],
                    ["cincel", "Eso no está en el Canto. Eso no lo canta nadie."],
                    [null, "Unísona lee las letras con la pata, una por una, y se le apaga la luz un instante, como cuando alguien recuerda una promesa que rompió otro."]], end: { xp: 24, flag: "e2_noveno" } },
    } },

    "e2-coros": { kind: "encuentro", need: { era: 2, layer: 4 }, who: { brezo: "Brezo, guarda del Tocón" }, start: "a", nodes: {
      a: { say: [[null, "Al borde del Tocón acampan cuatro coros, cada uno con sus banderas. Las Casas del Farol, el Gremio, el Fondo Blanco y un grupo de los Altos. Cada uno ensaya su verso, más fuerte que el de al lado."],
                 ["brezo", "Llegaron esta semana. Cada uno dice que su verso es el corazón del Canto y que, si lo cantan ellos solos, la Raíz se duerme del todo. Llevan tres días sin dejarse dormir unos a otros."]],
           opts: [{ t: "«¿Qué pasa si cantan los cuatro a la vez?»", go: "vez", once: true },
                  { t: "Pedirles que canten juntos", go: "juntos" },
                  { t: "Contarles lo de la base de la estatua", go: "noveno", cNeed: "e2_noveno" },
                  { t: "Dejarlos ensayar", go: "dejar" }] },
      vez: { say: [["brezo", "Lo hicieron ayer, sin querer. La tierra tembló y salió savia por una grieta nueva. Desde entonces se turnan, y se insultan entre turno y turno."]], back: "a" },
      juntos: { say: [[null, "Hablas con los cuatro. Todos te escuchan con respeto: eres quien calmó a la Raíz. Ninguno acepta. Cada uno quiere cantar primero."],
                      ["brezo", "La Primera Cantora les dijo a todos que su verso era el corazón. Fue para que lo cuidaran. Ahora es para que no se escuchen."]], end: { xp: 8 } },
      noveno: { say: [[null, "Les lees la frase de la base. Se hace un silencio largo, el primero en tres días."],
                      [null, "«Eso es una condición», dice un hombre del Gremio. «No es un verso. Una condición no se canta, se cumple.» «Pues que la cumplan los otros», le contesta una mujer de las Casas."],
                      ["brezo", "Al menos ahora saben qué se rompió. Saber no es arreglar, pero es algo."]], end: { xp: 16, flag: "e2_corosSaben" } },
      dejar: { say: [[null, "Te alejas entre los ensayos. Cuatro versos, cuatro voces, ninguna nana."]], end: { xp: 4 } },
    } },

    "e2-final": { kind: "dialogo", need: { era: 2, eraWin: "heart" }, first: true, once: true, who: { tila: "Tila", nim: "Nim" }, start: "a", nodes: {
      a: { say: [[null, "La Raíz en Vela no se duerme. La venciste, cayó, se levantó, y sigue ahí abajo, con los ojos abiertos en la oscuridad. Cada nana que se le canta la enfurece más. El Tocón tiembla día y noche."],
                 [null, "En el centro, Tila y Nim te esperan. Unísona está entre los dos, apagada a medias, mirando la base de la estatua."],
                 ["tila", "Hay que decidir algo. Ya no podemos esperar a que se calme sola."],
                 ["nim", "Hay tres formas. Ninguna es buena. Elige tú, que a ti te escucha."]],
           opts: [{ t: "«¿Qué pasa si canto yo, más fuerte que nadie?»", go: "q1", once: true },
                  { t: "«¿Y si cerramos todos los pozos?»", go: "q2", once: true },
                  { t: "«¿Y si cantamos solo los que estamos?»", go: "q3", once: true },
                  { t: "Cantar más fuerte que nadie y quedarte en el Corazón", go: "quinta" },
                  { t: "Reunir a los nueve pueblos para cantar la condición como promesa", go: "linea", cNeed: "e2_nueve" },
                  { t: "Cantar con los pueblos que vinieron", go: "ligero" }] },
      q1: { say: [["nim", "La Raíz se duerme otra generación. Habrá fiesta en el Vado y te harán una estatua preciosa. La quinta."],
                  ["tila", "Y te quedas aquí, cantando, hasta que se te ponga la piel de piedra. Como ellas. Y los pozos siguen abiertos, y dentro de cincuenta años, otro Cuidador."]], back: "a" },
      q2: { say: [["tila", "Hay que cantar la frase de la base como promesa, no como nana. Con los nueve pueblos delante, y Unísona de testigo."],
                  ["tila", "La Raíz no se duerme: se queda despierta, bebe lo suyo y se cura de verdad, muy despacio. Y nosotros cerramos todos los pozos. Todos. El Prado se queda a oscuras."],
                  ["nim", "Y las Casas que pierden su última luz pierden su nombre. Así es su ley. Tú lo sabes, Tila."],
                  ["tila", "Lo sé."]], back: "a" },
      q3: { say: [["nim", "Cantamos con los pueblos que trajiste. La Raíz se duerme a medias, con un ojo abierto."],
                  ["nim", "Donde vino su pueblo, la savia se aquieta. Donde no vino nadie, sigue saliendo. Un Claro partido: zonas sanas y zonas negras."]], back: "a" },
      quinta: { say: [[null, "Subes al Tocón y cantas. Los ocho versos, y la nana de Tila y la de Nim, y la frase de la base como si fuera una nana más. Cantas más fuerte que los cuatro coros juntos."],
                      [null, "La Raíz se duerme. El temblor se para. En el Vado empiezan a sonar campanas."],
                      [null, "No puedes bajar. No quieres. Te pesan los pies. Tila te toma de la mano un rato largo, hasta que tu mano ya no está tibia."],
                      ["nim", "Te vamos a hacer una estatua preciosa. Te lo prometo. Y te vamos a cantar, para que nunca te falte compañía."]], end: { xp: 60, flag: "m2_quinta" } },
      linea: { say: [[null, "Llegan los nueve. Las Casas con Alvar delante, el Fuego con su martillo, el Bosque en silencio, los Altos sin vender nada, la Corte sin velo, las Mareas juntas, la Hondura con dos piedras, el Fondo Blanco sin regente, y el Barrio Apagado, que no es de ningún sitio y es de todos."],
                     [null, "No cantan una nana. Dicen la frase de la base, todos a la vez, mirando hacia abajo: «Nadie beberá por debajo de tus sueños». Unísona brilla entre todos, más fuerte que nunca. Es la testigo."],
                     [null, "La Raíz no se duerme. Se queda despierta. Bebe despacio de lo suyo. Y deja de temblar."],
                     ["tila", "Ahora hay que cerrar los pozos. Todos. Empezando por los de mi Casa, que ya no existe."],
                     [null, "Esa noche, por primera vez en treinta años, el Prado está a oscuras. Se ven las estrellas."]], end: { xp: 60, flag: "m2_linea" } },
      ligero: { say: [[null, "Cantan los pueblos que trajiste, cada uno su verso, uno detrás de otro, sin pelear. Tú cantas el final. Unísona canta contigo."],
                      [null, "La Raíz se adormece. No del todo. El temblor baja a un murmullo, como alguien que duerme mal."],
                      ["nim", "Mira el mapa. Donde vino un pueblo, la tierra está quieta. Donde no vino nadie, la savia sigue saliendo."],
                      ["tila", "Un Claro partido en dos. Al menos esta vez sabemos dónde está la grieta."]], end: { xp: 50, flag: "m2_ligero" } },
    } },
  });
  /* ==================== Entrega 2: el Día (Prado Aurora, Cráter Tibio, Bosque Hondo) ==================== */

  /* ---------- Prado Aurora: Aurelia sin cargo, los faroles que no parpadean, las Estrellas Mudas ---------- */
  add("aurora", {
    "e2-aurelia": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { aurelia: "Aurelia Albor", alvar: "Alvar" }, start: "a", nodes: {
      a: { say: [[null, "En el patio de atrás de la Torre del Alba, entre macetas, una señora mayor con un vestido bueno y las manos sucias de tierra le habla a un geranio."],
                 ["aurelia", "Tú, más a la izquierda. Ahí no te da el sol. ¿Cuántas veces te lo tengo que decir?"],
                 [null, "Te ve. No se sorprende. Se limpia las manos en el vestido, que antes valía lo que una casa del Barrio."],
                 ["aurelia", "El Cuidador. Pasa. Ya no tengo guardas que te lo impidan. Soy Aurelia Albor, por si no te acuerdas. Ahora mando en las macetas."]],
           opts: [{ t: "«¿Por qué la apartaron?»", go: "porque", once: true },
                  { t: "«¿Qué piensa de la matriarca nueva?»", go: "destello", once: true },
                  { t: "Preguntar por Alvar", go: "alvar", once: true },
                  { t: "«Usted sabe dónde cavó Albor. ¿Lo tiene escrito?»", go: "libro" },
                  { t: "Ayudarle con las macetas", go: "macetas" }] },
      porque: { say: [["aurelia", "Por los tubos. Alguien tenía que pagar, y yo era la que firmaba. Es justo. No me quejo."],
                      ["aurelia", "Bueno, me quejo un poco. A las macetas. Ellas no votan en el Consejo."],
                      [null, "Mueve el geranio a la izquierda. Luego otra vez a la derecha."]], back: "a" },
      destello: { say: [["aurelia", "Que es lista. Más que yo a su edad. Y que tiene razón en casi todo, que es lo más peligroso que se puede tener."],
                        ["aurelia", "Cuando yo abrí el primer pozo, también tenía razón. El Prado pasaba frío. ¿Sabes lo que es que te den la razón todos los días durante treinta años? Te deja de importar mirar el suelo."]], back: "a" },
      alvar: { say: [["aurelia", "Mi nieto anda con las botas sucias y amigos del Barrio. Me alegra. Lo digo en serio."],
                     ["aurelia", "Lo que no quiero es que cargue con lo mío. En el Prado los apellidos pesan más que las personas. A él le van a cobrar lo que hice yo, igual que a mí me cobraron lo que hizo mi madre."],
                     ["aurelia", "Si alguna vez tiene que elegir entre su apellido y lo que es justo, que no lo piense. Díselo de mi parte. A mí no me escucha."]], back: "a" },
      libro: { say: [["aurelia", "Claro que lo tengo. Albor anotaba todo. Hasta lo que no debía."],
                     [null, "Saca de entre las macetas una caja de lata. Dentro hay un cuaderno de tapas rojas, gastado en las esquinas."],
                     ["aurelia", "Aquí está cada pozo que abrimos, cuánto daba y cuándo empezó a dar negro. Lucerna cree que cava donde no molesta. Yo también lo creía. Mira la página del año treinta y dos."],
                     [null, "En esa página hay un dibujo del subsuelo del Prado. Los pozos de Albor están marcados con cruces. Debajo de todos, con una letra temblorosa, alguien escribió: «Más hondo no hay otra cosa. Hay lo mismo, más cerca»."]],
               opts: [{ t: "«Démelo. Se lo llevo a la matriarca.»", go: "llevar" },
                      { t: "«Hay que leerlo en la plaza, delante de todos.»", go: "plaza" },
                      { t: "«Quémelo. Ya hizo bastante daño.»", go: "quemar" },
                      { t: "Devolverle la caja y no decir nada", back: "a" }] },
      llevar: { say: [["aurelia", "Llévaselo. Pero prométeme una cosa: si te pregunta de dónde lo sacaste, dile que lo encontraste. Que no salga el nombre de Alvar en esto."],
                      [null, "Te lo da con las dos manos, como se da algo que pesa. Antes de soltarlo, lo aprieta un segundo."],
                      ["aurelia", "Treinta años. Y cabe en un bolsillo."]], end: { xp: 16, flag: "e2_libroAlbor", escrito: "e2-libro-albor" } },
      plaza: { say: [["aurelia", "¿En la plaza? Me tirarían piedras. Y harían bien, pero las piedras no tapan pozos."],
                     ["aurelia", "Haz lo que quieras con él. Pero si lo lees en la plaza, la gente no va a oír «la Raíz». Va a oír «Albor». Y Lucerna va a decir que es una venganza de la Casa vieja. Y le van a creer."],
                     [null, "Te lo da igual. Tiene razón, y lo sabe, y eso parece cansarla más que nada."]], end: { xp: 14, flag: ["e2_libroAlbor", "e2_libroPlaza"], escrito: "e2-libro-albor" } },
      quemar: { say: [[null, "Aurelia te mira mucho rato. Luego enciende un fósforo, muy despacio, y lo acerca a la esquina del cuaderno."],
                      [null, "Antes de que prenda, lo apaga de un soplido."],
                      ["aurelia", "No. Quemar papeles es lo que hacía mi madre. Por eso yo no sabía nada cuando me tocó a mí."],
                      ["aurelia", "Me lo quedo. Si un día alguien lo necesita, que venga a buscarlo. Sabrá dónde estoy: dándole órdenes a un geranio."]], end: { xp: 8, flag: "e2_aureliaGuarda" } },
      macetas: { say: [[null, "Trasplantas tres geranios. Ella te corrige cada uno. Al final, sin mirarte, te dice que lo hiciste bien."],
                       [null, "En la tierra de las macetas, cuando metes los dedos, hay hilos negros muy finos. Aurelia los ve. Les echa más tierra encima, con cuidado, como quien tapa a un niño."]], end: { xp: 6, heal: 0.15 } },
    } },

    "e2-pabilo": { kind: "encuentro", need: { era: 2, layer: 1 }, who: { pabilo: "Pabilo", guarda: "Guarda del Farol" }, start: "a", nodes: {
      a: { say: [[null, "Los faroles nuevos del Prado se encienden solos al caer la tarde. Nadie sube escaleras, nadie carga latas. Un tubo de cristal baja de cada uno hasta el suelo."],
                 [null, "Al pie de uno, sentado en su escalera plegada, el farolero viejo mira cómo se enciende sin él. Tiene las latas vacías a los pies y la pértiga apoyada en el hombro, como un fusil de un ejército que ya no existe."],
                 ["pabilo", "Cuarenta años subiendo. Ahora suben solos. Me pagan la mitad por mirar que no se apaguen. No se apagan nunca."]],
           opts: [{ t: "«¿No es mejor así? Ya no tiene que subir.»", go: "mejor", once: true },
                  { t: "Mirar el farol de cerca", go: "mirar", once: true },
                  { t: "«Usted me habló de la luz fría, el año pasado.»", go: "fria", cNeed: "luzFria", once: true },
                  { t: "«Prenda uno de aceite. Uno solo, en el Barrio.»", go: "aceite" },
                  { t: "Comprarle la pértiga vieja", go: "pertiga", fx: { cost: 15 } },
                  { t: "Dejarlo mirando", go: "irte" }] },
      mejor: { say: [["pabilo", "Mejor para las rodillas, sí. Las rodillas no opinan del resto."],
                     ["pabilo", "Un farol de aceite parpadea. Respira. Si el viento cambia, se agacha. Estos no se agachan con nada. Una luz que no se agacha con nada no está viva, muchacho. Perdón: Cuidador."]], back: "a" },
      mirar: { say: [[null, "La llama no se mueve. Ni un poco. Es como una pintura de una llama."],
                     [null, "Al pie del tubo, donde entra en la tierra, el pasto está amarillo en un círculo perfecto. Como si alguien le hubiera chupado el verde con una pajita."]], back: "a" },
      fria: { say: [["pabilo", "Te acuerdas. Nadie se acuerda de lo que dice un farolero."],
                    ["pabilo", "Esta es más fría todavía. Pon la mano. ¿Ves? Ilumina y no calienta. Le saca la luz a algo y no le devuelve nada."]], back: "a" },
      aceite: { say: [["pabilo", "¿Uno de aceite? Los guardas de la matriarca los están quitando. Dicen que afean."],
                      ["guarda", "Ese señor ya sabe que no puede prender nada sin permiso."],
                      [null, "Pabilo te mira. Tú miras al guarda. El guarda mira hacia otro lado, porque es del Barrio y su abuela tenía un farol de aceite en la ventana."]],
              opts: [{ t: "Prenderlo igual, en la esquina de Penumbra", go: "prender" },
                     { t: "Convencer al guarda", go: "guarda" },
                     { t: "Dejarlo para otro día", back: "a" }] },
      prender: { say: [[null, "Pabilo sube su escalera, despacio, con las rodillas crujiendo. Llena la lata. Prende la mecha. La llama se agacha con el viento y vuelve a levantarse."],
                       ["pabilo", "Ahí está. Esa sí respira."],
                       [null, "Al rato, la vecina de enfrente saca una silla a la puerta y se sienta bajo el farol de aceite, aunque el nuevo da más luz. Después otra. A medianoche hay seis sillas."]], end: { xp: 14, flag: "e2_pabiloAceite" } },
      guarda: { say: [["guarda", "Mira, Cuidador, yo no quiero problemas. Si mañana pregunta la capitana, el farol ya estaba así."],
                      [null, "Pabilo prende su farol. El guarda se pone de espaldas, muy firme, mirando exactamente al lado contrario."]], end: { xp: 12, flag: "e2_pabiloAceite" } },
      pertiga: { say: [["pabilo", "¿Mi pértiga? ¿Para qué la quieres? No hay nada que prender."],
                       ["pabilo", "Bueno. Llévatela. Mejor que esté con alguien que todavía camina de noche."],
                       [null, "Pesa más de lo que parece. En la punta tiene grabadas cuarenta muescas: una por cada año."]], end: { xp: 8, card: true } },
      irte: { say: [[null, "Cuando te alejas, Pabilo sigue ahí, sentado, mirando una llama que no se mueve. Él tampoco."]], end: { xp: 3 } },
    } },

    "e2-brizna": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { brizna: "Brizna", recolector: "Recolector de la Torre" }, start: "a", nodes: {
      a: { say: [[null, "En el callejón de siempre, la niña que dibujaba con tiza está agachada junto a un frasco de vidrio. Ha crecido. Dentro del frasco hay doce Estrellas chiquitas, apagadas, grises como piedras de río."],
                 ["brizna", "No las toques, que se rompen. Las junto del pie de la tarima del coro. Nadie las quiere. Las barren con la basura."],
                 [null, "En la pared, con tiza, ha dibujado doce caras. Cada una tiene un nombre debajo."]],
           opts: [{ t: "«¿Por qué les pusiste nombre?»", go: "nombres", once: true },
                  { t: "«¿Qué son, para ti?»", go: "que", once: true },
                  { t: "Enseñarle la Estrella que salvaste del coro", go: "tuya", cNeed: "e2_mudo", once: true },
                  { t: "«Vamos a enterrarlas como se debe.»", go: "enterrar" },
                  { t: "«Deja que Unísona las vea.»", go: "unisona" },
                  { t: "Preguntar quién más las busca", go: "busca" }] },
      nombres: { say: [["brizna", "Porque nacieron de una canción y nadie las esperaba. Como yo. A mí me puso nombre la vecina, porque mi mamá estaba muy cansada."],
                       ["brizna", "Esta es Mota. Esta es Pica. Esta no tiene nombre todavía porque llegó ayer y ya estaba apagada cuando la encontré."]], back: "a" },
      que: { say: [["brizna", "Promesas. Lo dijo la chica del tejado. Que cuando cantas la nana de otro sin querer, sale una promesa sin dueño, y se apaga porque nadie la cumple."],
                   ["brizna", "Yo creo que tienen frío. Por eso las tengo juntas."]], back: "a" },
      tuya: { say: [[null, "Sacas la Estrella envuelta en la bufanda. Todavía brilla, poquito, como una vela vista desde lejos."],
                    [null, "Cuando la acercas al frasco, las doce Estrellas grises se iluminan un instante. Todas a la vez. Luego se apagan otra vez."],
                    ["brizna", "¡Viste! ¡Viste! Se acordaron. Están vivas por dentro, solo que muy cansadas."]], back: "a" },
      enterrar: { say: [[null, "Las entierran juntas bajo el último farol de aceite del callejón, en una caja de galletas. Brizna dice un nombre por cada una. Tus criaturas cavan con las patas."],
                        ["brizna", "Así, si alguien canta bonito aquí arriba, ellas lo oyen."],
                        [null, "Esa noche, en la tierra removida, hay un brillo muy débil. Al amanecer ya no está."]], end: { xp: 12, flag: "e2_estrellasEnterradas" } },
      unisona: { say: [[null, "Unísona se acerca al frasco. Las mira largo rato. Luego canta una sola nota, la más baja que le has oído."],
                       [null, "No pasa nada. Las Estrellas siguen grises. Pero Unísona no se mueve de ahí hasta que se hace de noche, y Brizna se sienta a su lado."],
                       ["brizna", "Está triste. Las criaturas también se ponen tristes, ¿sabías? Las que cantan, más."]], end: { xp: 10, flag: "e2_unisonaLlora", heal: 0.1 } },
      busca: { say: [["brizna", "Un señor de la Torre. Viene los jueves con una caja forrada de terciopelo. Paga una moneda por cada una."],
                     [null, "Como si lo hubiera llamado, aparece al fondo del callejón un hombre con guantes blancos y una caja."],
                     ["recolector", "Ah, la niña de las piedras. La matriarca quiere estudiarlas. Si las Estrellas salen del coro, quiere saber de qué están hechas. Para hacer mejores coros."]],
             opts: [{ t: "Vendérselas tú, por el doble", go: "vender" },
                    { t: "Ponerte entre el hombre y el frasco", go: "defender" },
                    { t: "«¿Qué hace la matriarca con ellas?»", go: "estudio", once: true }] },
      estudio: { say: [["recolector", "Las abren. Por dentro tienen como una nota escrita, dicen. La misma nota en todas, una que nadie sabe cantar."],
                       ["recolector", "Yo no sé de esas cosas. Yo cobro por caja."]], back: "busca" },
      vender: { say: [[null, "El hombre paga el doble sin pestañear. Brizna no dice nada. Mete las manos en los bolsillos y mira la pared con las doce caras."],
                      [null, "Esa noche, cuando vuelves a pasar, las caras de tiza están borradas. Menos una, la que no tenía nombre."]], end: { coins: 40, xp: 4, flag: "e2_estrellasVendidas" } },
      defender: { say: [["recolector", "Como quieras. Son piedras. Hay más en la tarima."],
                        [null, "Se va. Pero en la esquina le hace una seña a un guarda, y el guarda te sigue con la mirada hasta que sales del Barrio."]], end: { xp: 12, fight: true, flag: "e2_estrellasEnterradas" } },
    } },

    "e2-penumbra": { kind: "encuentro", need: { era: 2, layer: 2 }, who: { penumbra: "Penumbra", cirio: "Cirio, guarda del tablón" }, start: "a", nodes: {
      a: { say: [[null, "En el taller de la costurera de la Sombra hay más trabajo que nunca. Sobre la mesa, cientos de cintas de tela gris. En cada una, bordado con hilo blanco, un nombre y un destino."],
                 ["penumbra", "La Ley del Regreso pide que cada familia lleve su cinta cosida en el abrigo. Nombre, Casa que paga y lugar al que vuelve. Así los guardas del Umbral saben a quién dejar pasar y a quién no."],
                 ["penumbra", "Me pagan bien. Bordo cuarenta al día. Antes bordaba forros para que el polvo no entrara en los pulmones. Ahora bordo esto."]],
           opts: [{ t: "Leer algunas cintas", go: "leer", once: true },
                  { t: "«¿Usted también tiene que volver?»", go: "ella", once: true },
                  { t: "«¿Y si algunas cintas dijeran «Vado» en vez de «Envés»?»", go: "cambiar" },
                  { t: "Ayudarla a bordar, sin más", go: "ayudar" },
                  { t: "Llevar las cintas al tablón para que las sellen", go: "sellar" }] },
      leer: { say: [[null, "«Familia Ceniza. Casa Albor. Hondonada, casa del puente.» «Familia Rocío. Casa Destello. Lago, orilla sur.» «Familia sin nombre. Casa Alba. Cuevas, galería nueve.»"],
                    ["penumbra", "Esa última no tiene nombre porque no quisieron ponérselo. Les pusieron «sin nombre» y listo. Es lo que se hacía en los Pozos. Algunas cosas no cambian, solo se bordan más bonito."]], back: "a" },
      ella: { say: [["penumbra", "Mi cinta dice «Hondonada, calle del telar». Esa calle ya no existe. La niebla se la comió hace veinte años. Pero el papel dice que está curada, así que debe estar ahí."],
                    ["penumbra", "Me la bordé yo misma. Con mi mejor hilo. Si me van a echar, por lo menos que se vea bien hecho."]], back: "a" },
      cambiar: { say: [[null, "Penumbra deja la aguja. Te mira por encima de los anteojos."],
                       ["penumbra", "¿Sabes lo que me pasa si me descubren? Me quitan el permiso. A mí, que tengo cinta. Y luego a los que tienen la cinta cambiada."],
                       ["penumbra", "Pero los guardas del Umbral no saben leer bien. Ninguno. Miran el sello y la forma de las letras. Si la palabra es corta y redonda…"],
                       [null, "Coge una cinta. En vez de «Envés» borda, muy despacio, «Vado». Las dos palabras se parecen si no las miras mucho."]],
                 opts: [{ t: "«Hágalo con todas las que pueda.»", go: "todas" },
                        { t: "«Solo con las familias con niños chicos.»", go: "ninos" },
                        { t: "«Mejor no. Es demasiado peligroso para usted.»", go: "nocambiar" }] },
      todas: { say: [[null, "Bordan hasta el amanecer. Ciento doce cintas dicen «Vado». Tus dedos sangran un poco. Los de ella no: tiene callos de cuarenta años."],
                     ["penumbra", "Ahora el Vado va a tener que hacerles lugar, Cuidador. Ciento doce personas con frío. ¿Lo pensaste?"],
                     [null, "No lo pensaste del todo. Pero ya está bordado."]], end: { xp: 18, flag: ["e2_cintasVado", "u2_barrio"], hurt: 0.05 } },
      ninos: { say: [[null, "Treinta cintas. Las de las familias con niños que nacieron arriba, como los de Umbría."],
                     ["penumbra", "Es una elección fea. Elegir a quién sí. Pero es mejor que no elegir a nadie."],
                     [null, "Mientras bordas, ella canta muy bajito. No es la nana. Es una canción de taller, para no perder el ritmo de la aguja."]], end: { xp: 16, flag: ["e2_cintasVado", "u2_barrio"] } },
      nocambiar: { say: [["penumbra", "Gracias por pensar en mí. Casi nadie lo hace."],
                         [null, "Vuelve a la aguja. «Envés». «Envés». «Envés». Bordado perfecto, cada una."]], end: { xp: 6 } },
      ayudar: { say: [[null, "Bordas toda la tarde. No es difícil. Lo difícil es leer cada nombre antes de bordarlo."],
                      ["penumbra", "Tienes buena mano. Lástima que sea para esto."]], end: { coins: 20, xp: 6 } },
      sellar: { say: [[null, "Llevas la canasta de cintas al tablón del Vado. Cirio las sella una por una con un sello de cera roja."],
                      ["cirio", "Casi nadie ayuda. La gente pasa y mira mal, como si yo hubiera escrito la ley."],
                      [null, "Cuando vuelves al taller con la canasta vacía, Penumbra no levanta la vista de la aguja."]], end: { coins: 30, xp: 5, flag: "e2_cintasSelladas" } },
    } },

    "e2-romero": { kind: "dialogo", need: { era: 2, layer: 2 }, who: { romero: "Romero, jardinero", alvar: "Alvar" }, start: "a", nodes: {
      a: { say: [[null, "Al amanecer, en los jardines de la Torre, el jardinero arranca flores. Montones. Las mete en sacos negros y los ata con doble nudo."],
                 ["romero", "No mires. Son órdenes. Cada noche salen así y cada mañana las arranco antes de que se despierte el Prado."],
                 [null, "Una se le cae del saco. Es una rosa perfecta, roja por fuera. El centro, donde deberían estar los pistilos, es negro y brillante como aceite."]],
           opts: [{ t: "«¿Desde cuándo salen así?»", go: "cuando", once: true },
                  { t: "«¿Quién lo ordena?»", go: "quien", once: true },
                  { t: "«Las flores grises del año pasado… ¿se acuerda?»", go: "grises", cNeed: "floresGrises", once: true },
                  { t: "«Deme un saco. Lo llevo al Consejo.»", go: "consejo" },
                  { t: "Plantar una en el Vado, para ver qué pasa", go: "vado" },
                  { t: "Ayudarle a arrancarlas", go: "arrancar" }] },
      cuando: { say: [["romero", "Desde la Velada. La noche de todos los faroles. Al día siguiente salieron las primeras. Ahora son la mitad del jardín."],
                      ["romero", "Lo raro es que crecen mejor que las otras. Más grandes, más rojas. Si no fuera por el centro, serían las flores más bonitas que he cultivado."]], back: "a" },
      quien: { say: [["romero", "La matriarca. Me lo dijo ella misma, con mucha educación. Que la gente se asusta fácil, que es una plaga pasajera, que sus ingenieros lo están viendo."],
                     ["romero", "Me subió el sueldo. Nunca nadie me había subido el sueldo. Así que arranco."]], back: "a" },
      grises: { say: [["romero", "Las grises eran tristes. Se morían despacio. Estas no se mueren. Estas comen."],
                      [null, "Abre la mano. En la palma, donde tocó los tallos, tiene una mancha oscura que no se va con agua."]], back: "a" },
      consejo: { say: [["romero", "¿Al Consejo? Hoy se reúnen en la sala grande. Te van a sacar a patadas."],
                       ["romero", "Pero toma. Si te sacan, que te saquen con el saco."]],
                 opts: [{ t: "Entrar por la puerta grande y vaciar el saco en la mesa", go: "mesa" },
                        { t: "Dárselo a Alvar, que todavía entra por la puerta de las Casas", go: "alvar" }] },
      mesa: { say: [[null, "Los guardas tardan en reaccionar. Vacías el saco sobre la mesa del Consejo. Cuarenta rosas rojas con el corazón negro caen sobre los papeles de la Ley del Regreso."],
                    [null, "Un silencio largo. Luego, alguien de una Casa vieja empieza a gritar que es una provocación de la Sombra. Otro grita que es culpa de Albor. Nadie mira las flores."],
                    [null, "Solo una persona se acerca a tocarlas: Lucerna Destello. Las mira mucho rato. Luego ordena que te saquen."]], end: { xp: 18, fight: true, flag: "e2_florConsejo" } },
      alvar: { say: [["alvar", "¿Que yo las lleve? Si las llevo yo, van a decir que es cosa de mi abuela."],
                     ["alvar", "Bueno. Que lo digan. Mi abuela me dijo una vez que, si tenía que elegir entre el apellido y lo justo, no lo pensara."],
                     [null, "Se echa el saco al hombro y entra por la puerta de las Casas. Los guardas lo saludan. Desde afuera oyes cómo se hace un silencio enorme."]], end: { xp: 16, flag: ["e2_florConsejo", "e2_alvarHabla", "u2_luz"] } },
      vado: { say: [[null, "Plantas una rosa en una maceta, en la puerta de tu casa del Vado. A los tres días la maceta está rajada. Las raíces salieron por abajo y se metieron en la tierra, buscando hacia el Corazón."],
                    [null, "Unísona no se acerca a la maceta. Tus criaturas tampoco. Al quinto día la quemas."]], end: { xp: 10, flag: "e2_florVado" } },
      arrancar: { say: [[null, "Arrancan hasta el mediodía. Los sacos se apilan junto al muro del jardín. A la tarde pasa un carro y se los lleva. Nadie dice a dónde."],
                        ["romero", "Gracias. Es más fácil con alguien. Uno se siente menos cómplice."]], end: { coins: 18, xp: 5, hurt: 0.05 } },
    } },

    "e2-cira": { kind: "encuentro", need: { era: 2, layer: 3 }, who: { cira: "Ama Cira", nim: "Nim" }, start: "a", nodes: {
      a: { say: [[null, "La anciana del banco ya no está en el banco. Está en su cama, en un cuarto chico del Barrio, con la ventana abierta hacia la tarima del coro. Nim está sentado en el suelo, junto a ella, pelando una naranja."],
                 ["nim", "Ama Cira no quiere que cierre la ventana. Dice que quiere oír cómo le destrozan las canciones."],
                 ["cira", "No las destrozan, hijo. Las cantan sin ganas. Es peor."]],
           opts: [{ t: "Sentarte con ellos", go: "sentar", once: true },
                  { t: "«Usted sabía que las dos nanas eran iguales.»", go: "iguales", cNeed: "nanaIgual", once: true },
                  { t: "«¿Hay algún verso que nadie cante ya?»", go: "verso" },
                  { t: "Cerrar la ventana", go: "ventana" }] },
      sentar: { say: [[null, "Nim te da un gajo de naranja. Ama Cira respira despacio. Afuera, el coro empieza otra vez."],
                      ["cira", "Mi abuela cantaba para que lloviera. Mi madre, para que mis hermanos se durmieran. Yo canté para enterrar a mi marido. Estos chicos cantan para que les paguen. No es malo. Pero la canción se da cuenta."]], back: "a" },
      iguales: { say: [["cira", "Iguales no. Hermanas. Como dos niñas que se parecen tanto que la gente las confunde, y ellas se dejan confundir porque les conviene."],
                       ["cira", "Pero falta algo en las dos. Siempre faltó. Mi abuela decía que la nana entera tenía un verso más, y que se perdió el día que se repartieron el Claro."]], back: "a" },
      verso: { say: [["cira", "Hay uno. Mi abuela lo cantaba solo al final, cuando creía que yo ya dormía. No era para dormir. Era otra cosa."],
                     ["cira", "No me acuerdo de la música. Solo de las palabras, y no de todas. Decía algo así: «Y si despiertas, no estarás sin nadie; lo que tomamos lo vamos a devolver»."],
                     ["nim", "Eso no es una nana. Es una promesa."],
                     ["cira", "Por eso nadie la canta, hijo. Las nanas son fáciles. Las promesas hay que cumplirlas."]],
             opts: [{ t: "Pedirle que lo repita para escribirlo", go: "escribir" },
                    { t: "«En la base de una estatua del Corazón hay una frase.»", go: "estatuas", cNeed: "e2_noveno" },
                    { t: "Dejarla descansar", go: "descansa" }] },
      escribir: { say: [[null, "Lo repite tres veces. Cada vez cambia una palabra, como si buscara la correcta entre muchas que se parecen."],
                        [null, "Lo escribes en el reverso de tu mapa. Nim lo lee por encima de tu hombro, moviendo los labios."],
                        ["cira", "Ahora tú también lo sabes. Ya no se muere conmigo. Qué alivio, ¿sabes? Es un peso, un verso que solo sabe uno."]], end: { xp: 20, flag: "e2_versoCira", escrito: "e2-verso-cira" } },
      estatuas: { say: [[null, "Le dices la frase de la base de la Cantora: «Dormiré mientras nadie beba por debajo de mis sueños»."],
                        ["cira", "Eso es lo que pide ella. Lo de mi abuela es lo que le contestábamos. Una nana con pregunta y respuesta, hijo. Se partió en dos, y cada pueblo se quedó con la mitad que no lo compromete a nada."],
                        [null, "Te aprieta la mano con una fuerza que no esperabas. Luego te suelta y cierra los ojos."]], end: { xp: 24, flag: ["e2_versoCira", "e2_corosSaben"], escrito: "e2-verso-cira" } },
      descansa: { say: [[null, "Ama Cira se duerme con la boca un poco abierta. Nim termina la naranja. Afuera, el coro desafina en la misma nota de siempre."],
                        ["nim", "Mañana vengo otra vez. Si quieres, vienes tú también. Le gusta tener gente cerca, aunque diga que no."]], end: { xp: 8, heal: 0.2 } },
      ventana: { say: [["cira", "Ábrela."],
                       [null, "La vuelves a abrir. Ella sonríe sin abrir los ojos."],
                       ["cira", "Una canción mal cantada sigue siendo una canción. Algún día alguno de esos chicos la va a cantar con ganas, y yo quiero estar oyendo."]], end: { xp: 6 } },
    } },

    "e2-destello": { kind: "dialogo", need: { era: 2, layer: 3, anyFlag: ["e2_avisaste", "e2_libroAlbor", "e2_florConsejo", "e2_rompiste"] }, who: { destello: "Lucerna Destello" }, start: "a", nodes: {
      a: { say: [[null, "Te citan en la Torre de noche. No en el salón, sino en un cuarto chico del último piso, con una mesa llena de papeles y una ventana que da al Barrio Apagado."],
                 [null, "Desde aquí arriba, el Barrio no está apagado. Cada ventana tiene luz. En algunas se ven chicos leyendo."],
                 ["destello", "Siéntate. No te voy a ofrecer vino, porque no tengo. Tengo té del Barrio, el de siempre."],
                 ["destello", "Sé lo que has estado haciendo. No estoy enojada. Quiero saber qué quieres, porque yo también quiero cosas, y a lo mejor queremos las mismas."]],
           opts: [{ t: "«Que cierre los Pozos Ciegos.»", go: "cerrar" },
                  { t: "Poner el cuaderno de Albor sobre la mesa", go: "libro", cNeed: "e2_libroAlbor" },
                  { t: "«¿Qué quiere usted?»", go: "ella", once: true },
                  { t: "Mirar por la ventana, sin contestar", go: "ventana", once: true }] },
      ella: { say: [["destello", "Que ningún chico del Barrio vuelva a leer con una vela de sebo que le arruina los ojos. Que mi madre no se muera tosiendo en un cuarto sin ventana, como la de Nim. Que nadie de arriba nos vuelva a decir dónde podemos vivir."],
                    ["destello", "Y sé de dónde sale la luz, Cuidador. No soy tonta. Pero Albor sacó luz cuarenta años para siete Casas. Yo llevo uno sacándola para todos. Si la Raíz tiene que cobrarse algo, que se cobre lo de ellos primero."]], back: "a" },
      ventana: { say: [[null, "En la ventana de enfrente, una niña con un libro abierto se ha quedado dormida sobre las páginas. La luz le da en la cara. No se despierta."],
                       ["destello", "Esa es Candela. Hace un año no sabía leer. Mira lo que me pides que le apague."]], back: "a" },
      cerrar: { say: [["destello", "¿Todos? ¿Esta noche? Entonces mañana el Barrio vuelve a estar a oscuras, y las Casas viejas vuelven a mandar, porque son las únicas con aceite guardado."],
                      ["destello", "No. Pero te ofrezco algo: una silla en el Consejo. Un Cuidador con voz. Si me demuestras que un pozo hace daño, ese pozo se cierra. Uno por uno. Con pruebas, no con miedo."]],
              opts: [{ t: "Aceptar la silla", go: "silla" },
                     { t: "«No voy a sentarme a contar pozos mientras la Raíz despierta.»", go: "negar" }] },
      libro: { say: [[null, "Destello abre el cuaderno rojo. Lee la página del año treinta y dos. La lee dos veces. La tercera, con el dedo."],
                     ["destello", "«Más hondo no hay otra cosa. Hay lo mismo, más cerca.»"],
                     [null, "Se queda callada mucho rato. Afuera, en el Barrio, se apaga una ventana. Es la de la niña dormida: alguien le apagó la luz para que descanse."],
                     ["destello", "Mis ingenieros me dijeron lo contrario. Les pagué para que me dijeran lo contrario, ¿no? No lo pensé así, pero es lo que hice."]],
             opts: [{ t: "«Cierre uno al mes. Empiece por el más hondo.»", go: "cede" },
                    { t: "«Ciérrelos todos y dígale al Barrio la verdad.»", go: "verdad" },
                    { t: "«Quédese con el cuaderno. Usted sabrá qué hacer.»", go: "deja" }] },
      silla: { say: [["destello", "Bien. Los martes, a la hora del té. Trae pruebas. Y trae paciencia: las Casas viejas hablan mucho."],
                     [null, "Te da una insignia de cobre con una lámpara grabada. Te queda pesada en el pecho."]], end: { coins: 40, xp: 10, flag: "e2_sillaConsejo" } },
      negar: { say: [["destello", "Entonces somos enemigos educados. Está bien. Los prefiero a los amigos que mienten."],
                     [null, "Te acompaña ella misma hasta la puerta. Antes de cerrar, te dice: «Si encuentras otra forma de dar luz, aquí estoy. Te lo digo en serio»."]], end: { xp: 12, flag: "e2_destelloEnemiga" } },
      cede: { say: [["destello", "Uno al mes. El más hondo primero. Las Casas me van a decir que cedo ante el Vado, y el Barrio va a decir que lo traiciono."],
                    ["destello", "Está bien. Para eso me eligieron: para que alguien del Barrio tome las decisiones feas, en vez de que las tomen por nosotros."],
                    [null, "Se queda con el cuaderno. Esa noche, en el Barrio, una de cada diez ventanas tarda un poco más en encenderse."]], end: { xp: 22, flag: ["e2_destelloCede", "u2_luz"] } },
      verdad: { say: [["destello", "¿Todos? ¿Y decirle al Barrio que la luz que tanto les costó es veneno? ¿Que la mujer que eligieron se equivocó?"],
                      ["destello", "Me van a tirar de la Torre. Y van a poner a alguien de Albor, que va a abrir los pozos otra vez, pero solo para siete Casas."],
                      [null, "Cierra el cuaderno. Lo guarda en un cajón con llave."],
                      ["destello", "Dame tiempo. No mucho. Pero no me pidas que me corte la cabeza para demostrar que tienes razón."]], end: { xp: 16, flag: "e2_destelloDuda" } },
      deja: { say: [[null, "Destello pone la mano sobre el cuaderno, como sobre algo que todavía está tibio."],
                    ["destello", "Eso es lo más cruel que me han hecho en un año. Darme la verdad y dejarme sola con ella."],
                    ["destello", "Gracias. Creo."]], end: { xp: 14, flag: "e2_destelloDuda" } },
    } },
  });

  /* ---------- Cráter Tibio: el suelo con fiebre, el Gremio que vende a dos manos, la Noche de Ascuas ---------- */
  add("crater", {
    "e2-termas": { kind: "encuentro", need: { era: 2, layer: 1 }, who: { ascua: "La vieja Ascua", junco: "Junco, enfriadora" }, start: "a", nodes: {
      a: { say: [[null, "Las termas del Cráter echan tanto vapor que no se ven las caras. Hay gente riéndose en el agua y gente cocinando huevos en el borde, metidos en una red."],
                 ["ascua", "¡Qué lindo, eh! Cuarenta años pidiendo que el agua volviera caliente, y ahora hierve. Ya no se puede meter más que los pies."],
                 [null, "Lo dice riéndose. Pero tiene los pies fuera del agua, rojos, y una toalla mojada en la nuca."]],
           opts: [{ t: "Meter la mano en el agua", go: "mano", once: true },
                  { t: "«¿Desde cuándo hierve así?»", go: "cuando", once: true },
                  { t: "Pedirle a Junco agua de la presa para enfriarla", go: "presa", cNeed: "damOpen" },
                  { t: "Medir el calor con una caña, como hacían los viejos", go: "cana" },
                  { t: "Bañar a tus criaturas en el borde", go: "banar" }] },
      mano: { say: [[null, "Duele. No como el agua caliente: como cuando tocas a alguien con fiebre y no te suelta."],
                    [null, "En el fondo, entre las piedras, hay burbujas que no son de aire. Suben despacio y revientan sin ruido, con un olor dulce."]], back: "a" },
      cuando: { say: [["ascua", "Desde que el Gremio empezó a hacer los tubos largos. Primero subió un poco. Después más. Ahora, en el centro, cocina un huevo en lo que dura un padrenuestro."],
                      ["ascua", "Mi abuela decía que la tierra tenía fiebre cuando le sacaban algo que no quería dar. Mi abuela decía muchas cosas. Algunas eran verdad."]], back: "a" },
      presa: { say: [["junco", "¿Agua de la presa? La abrimos el año pasado, gracias a ti. Ahora baja fresca."],
                     [null, "Junco abre una zanja con la pala. El agua fría entra en las termas con un ruido de plancha. Una nube de vapor lo tapa todo."],
                     [null, "Cuando se aclara, el agua está tibia otra vez, la buena. La gente aplaude. Ascua mete las piernas hasta las rodillas y suspira."],
                     ["junco", "Esto dura una semana, Cuidador. La presa enfría el agua. Lo que la calienta sigue ahí abajo."]], end: { xp: 14, heal: 0.3, flag: "e2_termasFrias" } },
      cana: { say: [[null, "Ascua te da una caña larga, hueca, con marcas de carbón cada palmo. La hundes en el centro de la terma."],
                    [null, "Las marcas viejas, de la época de su abuela, llegaban a la tercera. El agua de hoy quema la caña hasta la séptima. Por dentro, la caña sale manchada de negro."],
                    ["ascua", "Ay. Bueno. Eso no se lo cuentes a los de los huevos. Que disfruten mientras puedan."]], end: { xp: 12, flag: "e2_fiebre" } },
      banar: { say: [[null, "Tus criaturas se meten en el borde, donde está menos caliente. Salen rojas, contentas y con mucho sueño."],
                     [null, "Una de ellas se lame la pata y hace una mueca. Sabe dulce."]], end: { xp: 6, heal: 0.35, hurt: 0.05 } },
    } },

    "e2-fogarin": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { fogarin: "Fogarín" }, start: "a", nodes: {
      a: { say: [[null, "Es tarde. La forja grande está apagada, menos un rincón. Ahí, con un fuelle chico y un horno del tamaño de una olla, el aprendiz sopla un tubo de cristal fino como un dedo."],
                 ["fogarin", "No le digas al maestro. Uso el carbón que sobra. No le robo nada. Bueno, el carbón."],
                 [null, "Saca el tubo del fuego y lo mete en un balde de agua fría. El vidrio hace un sonido: una nota limpia, larga, como una campana chiquita."]],
           opts: [{ t: "«¿Qué es eso?»", go: "que", once: true },
                  { t: "«Eso es lo que te dijo la chica del Agua.»", go: "agua", once: true },
                  { t: "Darle el cristal con la veta negra", go: "veta", cNeed: "e2_cristalNegro" },
                  { t: "«Te ayudo. ¿Qué necesitas?»", go: "ayudar" },
                  { t: "«Enséñaselo a Tizón.»", go: "tizon" },
                  { t: "«Ten cuidado. Si te descubren, te echan.»", go: "cuidado" }] },
      que: { say: [["fogarin", "Un tubo que canta. Los de la matriarca no cantan, tragan. Este canta cuando lo enfrías."],
                   ["fogarin", "Se me ocurrió una cosa. Si un tubo que traga sabe dónde hay savia, uno que canta tiene que saber dónde está la Raíz. Porque la Raíz también canta, ¿no? Eso dicen. Si lo bajas a un pozo y cambia la nota, es que estás cerca."]], back: "a" },
      agua: { say: [["fogarin", "Sí. Junco. Bueno, una amiga de Junco, de las Mareas. Trabajó aquí dos meses y se fue sin despedirse. Me dejó eso dicho y nada más."],
                    ["fogarin", "Yo no hablo mucho. El maestro dice que el que sopla no opina. Pero pienso. Mucho. Y esto es lo que pensé."]], back: "a" },
      veta: { say: [[null, "Fogarín coge el trozo de cristal negro. Lo mira contra el fuego. Lo acerca a su tubo que canta."],
                    [null, "La nota del tubo cambia. Baja. Se vuelve ronca, como una garganta enferma."],
                    ["fogarin", "¿Oíste? ¡Lo oyó! El vidrio sabe. Ahora tengo con qué compararlo."],
                    [null, "Se pone a trabajar como si tú no estuvieras ahí. Al amanecer tiene tres tubos, y cada uno canta distinto según lo cerca que esté del cristal negro."]], end: { xp: 22, flag: ["e2_tuboCanta", "e2_tuboAfinado"] } },
      ayudar: { say: [["fogarin", "Que soples tú el fuelle. Yo no puedo soplar y mirar el vidrio a la vez."],
                      [null, "Soplas toda la noche. Te arden los brazos. Al amanecer, Fogarín tiene un tubo que canta una nota limpia y otra, más grave, cuando lo apuntas hacia el suelo."],
                      ["fogarin", "Hacia abajo canta distinto. Hacia el Corazón. Guárdalo tú, que yo no tengo dónde esconderlo."]], end: { xp: 16, flag: "e2_tuboCanta" } },
      tizon: { say: [["fogarin", "¿Al maestro? Si se lo enseño, lo va a ver como un juguete. O peor: lo va a querer vender."],
                     ["fogarin", "Bueno. A lo mejor tienes razón. El maestro no es malo. Solo está cansado de ser pobre."],
                     [null, "Al día siguiente Tizón lo ve. No dice nada. Esa noche, en el rincón de Fogarín, aparece un saco de carbón bueno que nadie ha robado."]], end: { xp: 14, flag: ["e2_tuboCanta", "e2_tizonTubo"] } },
      cuidado: { say: [["fogarin", "Ya lo sé. Pero si no lo hago yo, no lo hace nadie. Nadie le pregunta nada al que sopla."],
                       [null, "Mete otro tubo en el fuego. No te pide que te vayas, y tampoco que te quedes."]], end: { xp: 6 } },
    } },

    "e2-miga": { kind: "encuentro", need: { era: 2, layer: 1 }, who: { miga: "Miga, panadera" }, start: "a", nodes: {
      a: { say: [[null, "En la calle de las panaderas hay una cola que da la vuelta a la manzana. Miga, la panadera que horneaba en el suelo, ahora no enciende fuego: pone la masa sobre las losas de la calle y se hornea sola."],
                 ["miga", "¡Pan de la tierra! ¡Gratis para quien traiga su masa! Ya no pago leña, Cuidador. ¡La tierra hornea por mí!"],
                 [null, "El pan sale dorado y huele a gloria. La gente lo come en la cola, caliente, con los ojos cerrados."]],
           opts: [{ t: "Probar un pan", go: "probar", once: true },
                  { t: "«¿Cuánto calienta la losa?»", go: "losa", once: true },
                  { t: "«Miga, la harina de Albor… ¿sigue llegando?»", go: "harina", cNeed: "harinaAlbor", once: true },
                  { t: "Comprar una canasta para el Vado", go: "canasta", fx: { cost: 10 } },
                  { t: "Decirle a la cola que el calor viene de la savia", go: "avisar" }] },
      probar: { say: [[null, "Es el mejor pan que has comido. Esponjoso, tibio. Demasiado dulce, quizá. Como si tuviera miel, pero Miga no le pone miel."],
                      [null, "Al rato tienes mucha sed. Y un poco de sueño."]], back: "a" },
      losa: { say: [["miga", "En invierno, nada. Ahora, como un horno de leña bien cargado. Y nunca se enfría. Ni de noche."],
                    ["miga", "Al principio me daba miedo. Luego hice cuentas. Este mes ahorré lo de seis meses de leña. Mi hija va a ir a la escuela del Prado. ¿Tú sabes lo que es eso?"]], back: "a" },
      harina: { say: [["miga", "No, gracias a ti. Ya no dependo de Albor. Ahora compro harina del Bosque, que sale barata porque hay fruta y grano por todos lados."],
                      ["miga", "Todo sale bien este año, Cuidador. A veces me pellizco."]], back: "a" },
      canasta: { say: [[null, "Miga llena una canasta con doce panes y no te cobra más que la masa."],
                       [null, "En el Vado, tus vecinos se los comen en un rato. Esa noche todos duermen muy profundo. A la mañana siguiente, nadie se acuerda de lo que soñó."]], end: { xp: 6, heal: 0.3, flag: "e2_panDulce" } },
      avisar: { say: [[null, "Te subes a un banco y lo dices. La cola te escucha. Algunos dejan de masticar."],
                      ["miga", "¿Y qué quieres que haga? ¿Que vuelva a pagar leña? ¿Que mi hija no vaya a la escuela?"],
                      [null, "Nadie se va de la cola. Una señora te ofrece un pedazo de su pan, para que te calmes."],
                      ["miga", "No te enojes, Cuidador. Si es verdad, ya veremos. Pero hoy hay pan."]], end: { xp: 10, flag: "e2_panAviso" } },
    } },

    "e2-remache": { kind: "dialogo", need: { era: 2, layer: 2 }, who: { remache: "Remache, escribano", fragua: "Maese Fragua" }, start: "a", nodes: {
      a: { say: [[null, "En el almacén del Gremio, el escribano está pegado a un libro de cuentas con una lupa. Tiene tinta hasta en las orejas."],
                 ["remache", "Cuidador. Qué bueno que vienes. Tú no eres del Gremio ni de las Casas. Necesito que alguien que no sea de nadie mire esto."],
                 [null, "Te señala dos columnas. En una dice «Casa Destello: 200 tubos». En la otra, con la letra de otro escribano, «Casa Alba, Casa Orza, Casa Brasa: 600 tubos. Entrega por el túnel norte»."]],
           opts: [{ t: "«¿Seiscientos más? ¿Para las Casas viejas?»", go: "casas", once: true },
                  { t: "«¿Quién firma esos encargos?»", go: "quien", once: true },
                  { t: "«Tizón entregó ciento noventa, no doscientos.»", go: "tizon", cNeed: "e2_tizonSabe", once: true },
                  { t: "Copiar las dos páginas", go: "copiar" },
                  { t: "Quemar los encargos de las Casas viejas", go: "quemar" },
                  { t: "Vender la información a la matriarca", go: "vender" }] },
      casas: { say: [["remache", "Las Casas viejas no tienen permiso para abrir pozos desde lo de Albor. Pero si compran tubos y los entierran por el túnel norte, ¿quién lo va a ver?"],
                     ["remache", "La matriarca cree que es la única que cava. No lo es. La mitad de lo que sale de la tierra, se lo lleva gente que ni siquiera se tomó el trabajo de prometer algo."]], back: "a" },
      quien: { say: [["remache", "Maese Fragua. El maestro del Gremio. Con su sello."],
                     ["remache", "No es un ladrón, si eso piensas. Fragua no se queda con nada. Reparte lo que sobra entre los herreros. Es lo que siempre dijo: «El Fuego no elige cliente; el Fuego come de quien paga»."],
                     ["remache", "Lo malo es que ahora pagan los dos, y la Raíz no cobra a uno solo."]], back: "a" },
      tizon: { say: [["remache", "¿Ciento noventa? Entonces faltan diez… No: los diez que «se rompieron». Ya veo. Bien por Tizón."],
                     ["remache", "Pero mira aquí: los seiscientos de las Casas, nadie los rompe. Esos los hace Fragua con sus propias manos, de noche."]], back: "a" },
      copiar: { say: [[null, "Copias las dos páginas en tu libreta, letra por letra, con los sellos dibujados. Remache te corrige los números."],
                      ["remache", "Ahora hay dos copias. Si me pasa algo a mí, queda la tuya. Eso es todo lo que un escribano puede hacer: que la verdad no dependa de una sola persona."],
                      [null, "Al salir, te cruzas con un hombre grande con delantal de cuero que entra. No te mira. Remache cierra el libro de un golpe."]], end: { xp: 18, flag: "e2_libroGremio", escrito: "e2-encargos" } },
      quemar: { say: [[null, "Arrancas la página de los seiscientos y la tiras al brasero. Remache grita y luego se tapa la boca."],
                      ["fragua", "¿Qué está pasando aquí?"],
                      [null, "Un hombre grande, con un delantal de cuero lleno de quemaduras, está en la puerta. Mira el brasero. Mira tu mano. No necesita preguntar más."],
                      ["fragua", "Los papeles se queman, Cuidador. Los encargos no. Las Casas tienen memoria y el Gremio también."]], end: { xp: 12, fight: true, flag: "e2_paginaQuemada" } },
      vender: { say: [["remache", "¿A la matriarca? Bueno… sí. Ella lo pararía. O por lo menos le sacaría el negocio a las Casas viejas."],
                      [null, "Destello te paga bien por la copia. Una semana después, Maese Fragua ya no es maestro del Gremio. El nuevo maestro lo elige ella."],
                      [null, "Los seiscientos tubos se siguen haciendo. Ahora todos van a la Casa Destello."]], end: { coins: 60, xp: 8, flag: "e2_fraguaCae" } },
    } },

    "e2-guijo": { kind: "encuentro", need: { era: 2, layer: 2 }, who: { guijo: "Guijo", madre: "Madre de Guijo", brida: "Brida, capataz" }, start: "a", nodes: {
      a: { say: [[null, "En la ladera, una mujer le pone barro fresco en los brazos a un muchacho flaco. El niño del martillo ha crecido de golpe. Tiene quemaduras nuevas desde las muñecas hasta los codos."],
                 ["madre", "Trabaja en los Pozos Ciegos, abajo. Le pagan el doble que en la forja. Doble de plata, doble de quemaduras."],
                 ["guijo", "No es tanto, mamá. Allá abajo hace calor, nada más. Como de animal. Las paredes respiran."]],
           opts: [{ t: "«¿Las paredes respiran?»", go: "respiran", once: true },
                  { t: "Curarle los brazos con tus criaturas", go: "curar" },
                  { t: "Darle tu ficha de los Pozos para que tú vayas en su lugar", go: "ficha", cNeed: "e2_ficha" },
                  { t: "Pagarle a su madre lo que él gana en un mes", go: "pagar", fx: { cost: 40 } },
                  { t: "Ir a hablar con Brida", go: "brida", cNeed: "e2_bridaAvisa" }] },
      respiran: { say: [["guijo", "Sí. Pones la mano y se mueve, despacito. Arriba y abajo. Los viejos dicen que es el calor. Yo creo que hay algo durmiendo."],
                        ["guijo", "A veces, cuando picamos, se queja. Como cuando le tocas la panza a un perro dormido. Pero no se despierta. Todavía."]], back: "a" },
      curar: { say: [[null, "Tus criaturas le lamen las quemaduras. Una de ellas se acurruca en su regazo. Guijo se ríe por primera vez."],
                     ["madre", "Gracias. Pero mañana vuelve a bajar. Y pasado. Esto lo curas tú una vez y la tierra lo quema todos los días."]], end: { xp: 8, heal: 0.1, flag: "e2_guijoCurado" } },
      ficha: { say: [[null, "Le das tu ficha de madera, la del número 312. Él te da la suya. La suya tiene el número 41 y está gastada de tanto apretarla."],
                     ["guijo", "¿Y tú qué vas a hacer allá abajo?"],
                     [null, "No lo sabes todavía. Pero el 41 entra por el túnel sur mañana, y el 41 vas a ser tú."],
                     ["madre", "No sé quién eres. Pero esta noche mi hijo duerme arriba."]], end: { xp: 18, flag: ["e2_fichaGuijo", "u2_fuego"] } },
      pagar: { say: [["madre", "¿Un mes? ¿Y el mes siguiente?"],
                     [null, "Acepta. Guijo no baja a los Pozos este mes. Se pasa los días martillando clavos en la forja de Tizón, por la mitad de plata."],
                     ["guijo", "Es aburrido. Pero no me duele."]], end: { xp: 12, flag: "e2_guijoArriba" } },
      brida: { say: [[null, "Encuentras a Brida en la boca del túnel sur, apuntando nombres."],
                     ["brida", "¿Guijo? Es de los buenos. Pica rápido y no se queja."],
                     ["brida", "Te dije que si pasaba algo abajo, te avisaría. Te aviso: las paredes del túnel nueve están tibias como una piel. Ya no mando chicos ahí. Mando a los que se ofrecen."],
                     [null, "Tacha el nombre de Guijo de la lista del túnel nueve. Lo pone en la del tres, que está fría."]], end: { xp: 14, flag: "e2_bridaGuijo" } },
    } },

    "e2-fragua": { kind: "dialogo", need: { era: 2, layer: 3 }, who: { fragua: "Maese Fragua", tizon: "Maese Tizón" }, start: "a", nodes: {
      a: { say: [[null, "El maestro del Gremio te recibe en la forja más grande del Cráter. Es un hombre enorme, con un delantal de cuero que tiene más quemaduras que cuero. Habla sin dejar de martillar."],
                 ["fragua", "Me llamo Fragua. Ya sé quién eres. Todo el Cráter sabe quién eres. Eres el que le pagó a Tizón cuando nadie le pagaba. Eso te honra."],
                 ["fragua", "Ahora te voy a contar algo que no te va a gustar, y luego me vas a decir si sigo siendo el malo."]],
           opts: [{ t: "«Cuente.»", go: "cuente" },
                  { t: "Poner sobre el yunque la copia de los encargos", go: "libro", cNeed: "e2_libroGremio" },
                  { t: "«¿Por qué no hacen la Noche de Ascuas?»", go: "ascuas", cNeed: "e2_tizonSabe" },
                  { t: "«No tengo nada que hablar con usted.»", go: "irte" }] },
      cuente: { say: [["fragua", "Durante cuarenta años, el Fuego hizo los tubos de Albor y Albor nos pagó la mitad. Mi padre se murió con los pulmones negros haciendo vidrio para gente que no sabía su nombre."],
                      ["fragua", "Ahora todos quieren tubos. Destello, las Casas viejas, hasta los del Bosque preguntan. Por primera vez el Fuego pone el precio. Y tú me vienes a decir que no los venda."],
                      ["fragua", "No soy tonto. Sé lo que hacen los tubos. Pero si yo no los hago, los hace otro, más barato y peor. Y el Fuego vuelve a comer sobras."]],
                opts: [{ t: "«Entonces hágalos peor, a propósito.»", go: "peor" },
                       { t: "«Asóciese conmigo. Que la ganancia sirva para algo.»", go: "socio" },
                       { t: "«Sigue siendo el malo.»", go: "malo" }] },
      peor: { say: [["fragua", "¿Peor? ¿Que se rompan? ¿Como los diez de Tizón?"],
                    [null, "Deja el martillo. Se ríe, una risa grande que hace temblar los vidrios."],
                    ["fragua", "Tizón cree que nadie se dio cuenta. Yo cuento los vidrios rotos, Cuidador. Es mi trabajo. Y no dije nada."],
                    ["fragua", "Bueno. Si Tizón rompe diez, yo puedo romper cien. Un tubo roto no traga nada. Y las Casas viejas no saben de vidrio."]], end: { xp: 20, flag: ["e2_tubosRotos", "u2_fuego"] } },
      socio: { say: [["fragua", "¿Socio? ¿El Cuidador con el Gremio? Eso no lo vi venir."],
                     ["fragua", "Trato hecho. Una parte de lo que sale va a tu Vado. Tú decides en qué se gasta. Así por lo menos algo bueno sale de este horno."],
                     [null, "Te da la mano. Tiene la palma tan dura que parece de cuero. Los tubos se siguen haciendo."]], end: { coins: 80, xp: 6, flag: "e2_socioGremio" } },
      malo: { say: [["fragua", "Puede ser. Pero el malo da de comer a doscientas familias. ¿Cuántas alimentas tú?"],
                    [null, "No espera respuesta. Vuelve al yunque. La conversación terminó cuando él lo decidió."]], end: { xp: 8 } },
      libro: { say: [[null, "Fragua ve la copia. Reconoce su propio sello dibujado con tu mano torpe. Deja de martillar."],
                     ["fragua", "Remache. Siempre fue honrado, el condenado. Por eso lo puse ahí."],
                     ["fragua", "¿Qué quieres? ¿Llevarlo a la matriarca? Ella me saca del Gremio y se queda con todo. ¿A las Casas? Ellas me pagan para que nadie lo vea."],
                     ["fragua", "O lo rompes, y te pido algo a cambio."]],
             opts: [{ t: "«Pare los seiscientos de las Casas viejas, y lo rompo.»", go: "parar" },
                    { t: "«No lo rompo. Pero no lo enseño mientras no haga uno más.»", go: "guardar" }] },
      parar: { say: [["fragua", "Seiscientos tubos. La comida de un invierno para el Gremio."],
                     [null, "Mucho rato callado. Luego coge tu copia, la mira y te la devuelve sin romper."],
                     ["fragua", "No. Guárdala. Paro los seiscientos. Pero quiero que alguien tenga la prueba de que un día el Fuego eligió perder plata. Porque nadie se lo va a creer."]], end: { xp: 24, flag: ["e2_encargoParado", "u2_fuego"] } },
      guardar: { say: [["fragua", "Un chantaje honrado. Eso es nuevo."],
                       ["fragua", "Está bien. Ni uno más para las Casas viejas. Lo que ya hice, ya está hecho. Eso no lo arregla ni tu libreta."]], end: { xp: 16, flag: "e2_encargoParado" } },
      ascuas: { say: [["fragua", "¿La Noche de Ascuas? ¿La de los abuelos? Apagar el Cráter una noche, con encargos para tres meses."],
                      [null, "Tizón, que estaba en la puerta escuchando, entra."],
                      ["tizon", "Mi padre la hacía. Tu padre también, Fragua. Nos reíamos de los dos."],
                      ["fragua", "Y los dos se murieron con los pulmones negros, Tizón. ¿Eso es lo que quieres?"],
                      ["tizon", "Quiero que el suelo deje de estar caliente. Mi nieto juega en ese suelo."]],
              opts: [{ t: "«Una noche. Solo una. Si no pasa nada, no la pido más.»", go: "una" },
                     { t: "Dejar que lo discutan entre ellos", go: "discuten" }] },
      una: { say: [[null, "Fragua mira el fuego mucho rato, como se mira a un perro viejo que hay que sacrificar."],
                   ["fragua", "Una noche. La del primer frío. Si las Casas preguntan, dije que era para limpiar los hornos."],
                   ["tizon", "Gracias, Fragua."],
                   ["fragua", "No me agradezcas. Si no pasa nada, te vas a reír de ti mismo toda la vida, como nos reímos de nuestros padres."]], end: { xp: 22, flag: "e2_nocheAscuas" } },
      discuten: { say: [[null, "Discuten hasta que se apaga el horno. Al final no deciden nada. Pero Tizón se va con la cara de alguien que ya decidió solo."]], end: { xp: 10, flag: "e2_nocheAscuas" } },
      irte: { say: [["fragua", "Como quieras. La puerta del Fuego está abierta. Eso no lo podía decir mi padre."]], end: { xp: 3 } },
    } },

    "e2-ascuas": { kind: "encuentro", need: { era: 2, layer: 3, anyFlag: ["e2_nocheAscuas", "e2_tizonSabe"] }, who: { tizon: "Maese Tizón", fogarin: "Fogarín", guarda: "Guarda de la matriarca" }, start: "a", nodes: {
      a: { say: [[null, "Es la noche del primer frío. Uno por uno, los hornos del Cráter se apagan. Las chimeneas dejan de humear. Por primera vez en años, se ven las estrellas sobre el Cráter."],
                 ["tizon", "Mi padre decía que había que escuchar. Que en la Noche de Ascuas la tierra hablaba. Yo nunca oí nada. Era chico y me aburría."],
                 [null, "En el centro de la plaza de la forja queda un solo fuego encendido, chiquito, en un brasero de hierro. Alrededor, unos pocos herreros, en silencio, con mantas."]],
           opts: [{ t: "Sentarte junto al brasero y escuchar", go: "escuchar" },
                  { t: "Bajar el tubo que canta hacia el suelo", go: "tubo", cNeed: "e2_tuboCanta" },
                  { t: "Preguntar quién no vino", go: "quien", once: true }] },
      quien: { say: [["tizon", "La mitad. Los que tienen encargos de las Casas. Los que no creen. Los que tienen miedo de que la matriarca se entere."],
                     ["tizon", "Pero vino Fogarín. Y vino la panadera. Y vino la vieja Ascua, que no se pierde nada."]], back: "a" },
      escuchar: { say: [[null, "Al principio solo se oye el viento. Luego, muy abajo, algo. No es un ruido: es la falta de un ruido que siempre estuvo ahí, como cuando se para un reloj."],
                        [null, "El suelo se enfría bajo tus manos. Despacio. Muy despacio. Y en el silencio, de muy lejos, como del fondo de un pozo, una respiración larga. Alguien que estaba conteniendo el aire y por fin lo suelta."],
                        ["tizon", "¿Oíste eso?"],
                        [null, "Tizón llora sin hacer ruido. Tiene sesenta años y llora como un chico que entiende algo tarde."]],
                  opts: [{ t: "Quedarte hasta el amanecer", go: "quedarse" },
                         { t: "Salir a vigilar el camino", go: "guardas" }] },
      tubo: { say: [[null, "Fogarín te pasa el tubo. Lo apuntas hacia el suelo. Canta una nota grave, ronca. Luego, a medida que la noche avanza y el suelo se enfría, la nota sube. Se limpia."],
                    ["fogarin", "¿Oyes? Está mejorando. Solo con una noche. ¡Una noche y ya canta distinto!"],
                    ["fogarin", "Imagínate una noche por semana. O por mes."]], end: { xp: 24, flag: ["e2_ascuasHecha", "u2_fuego", "e2_tuboAfinado"] } },
      quedarse: { say: [[null, "Pasan la noche alrededor del brasero, sin hablar. Al amanecer, el primer herrero en encender su horno lo hace despacio, como pidiendo perdón."],
                        ["tizon", "El año que viene la hacemos otra vez. Aunque me echen del Consejo."],
                        ["tizon", "Y si un día hay que estar en el Corazón, el Fuego va a estar. Ya no por ti. Por eso que oímos."]], end: { xp: 20, flag: ["e2_ascuasHecha", "u2_fuego"], heal: 0.3 } },
      guardas: { say: [[null, "En el camino de bajada hay antorchas. Un grupo de guardas de la matriarca sube hacia el Cráter."],
                       ["guarda", "La matriarca pregunta por qué no salen tubos esta noche. Hay un encargo atrasado."],
                       [null, "Detrás de ti, el silencio del Cráter. Delante, las antorchas."]],
                 opts: [{ t: "No dejarlos pasar", go: "pelea" },
                        { t: "Inventar una avería en los hornos", go: "mentira" }] },
      pelea: { say: [[null, "Te plantas en medio del camino. Tus criaturas se ponen a tu lado. Los guardas dudan, y luego no."],
                     [null, "Cuando terminan, las antorchas están en el suelo. Arriba, el Cráter sigue callado. Nadie se enteró de que hubo pelea."]], end: { xp: 22, fight: true, flag: ["e2_ascuasHecha", "u2_fuego"] } },
      mentira: { say: [["guarda", "¿Una avería? ¿En todos los hornos a la vez?"],
                       [null, "Te mira. Sabe que mientes. Pero tiene frío y la cuesta es larga."],
                       ["guarda", "Le digo a la matriarca que mañana. Que mañana sin falta."]], end: { xp: 16, flag: "e2_ascuasHecha" } },
    } },
  });

  /* ---------- Bosque Hondo: la fruta prestada, el Concejo, la Cripta y el Seto que bebe ---------- */
  add("forest", {
    "e2-agalla": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { agalla: "Doña Agalla" }, start: "a", nodes: {
      a: { say: [[null, "El roble viejo del claro está tan cargado de bellotas que tiene dos ramas rotas. En el suelo, una alfombra marrón. Algunas bellotas se han abierto y están negras por dentro."],
                 ["agalla", "No pises las negras, que salpican. Ya lo sé. No hace falta que me lo digas."],
                 [null, "La voz sale del tronco, despacio, como si cada palabra tuviera que subir desde muy abajo."]],
           opts: [{ t: "«¿Le duele?»", go: "duele", once: true },
                  { t: "«¿Por qué tanta fruta?»", go: "fruta", once: true },
                  { t: "«Usted tenía un hueco en el tronco.»", go: "hueco", cNeed: "robleHueco", once: true },
                  { t: "Cortar una rama sana para injertarla lejos", go: "injerto" },
                  { t: "«Voy a contárselo al Concejo.»", go: "concejo" },
                  { t: "Juntar las bellotas negras y enterrarlas lejos", go: "enterrar" }] },
      duele: { say: [["agalla", "Duele como duele dar de más. Como cuando una madre tiene poco y da todo, y al otro día no puede levantarse."],
                     ["agalla", "No es la savia lo que duele. Es lo que la savia le pide al suelo. Este año el Bosque está comiendo el año que viene."]], back: "a" },
      fruta: { say: [["agalla", "Porque la tierra está llena de algo dulce que no es nuestro. Y los árboles somos tontos: si hay de comer, comemos. Si hay mucho, damos mucho."],
                     ["agalla", "Los jóvenes están felices. Yo tengo cuatrocientos años, Cuidador. Ya vi un año así. Al siguiente no quedó un roble en pie en todo el norte."]], back: "a" },
      hueco: { say: [["agalla", "Lo tenía. Se cerró solo, después de que pasaste. Pensé que era una buena señal."],
                     ["agalla", "No lo era. Se cerró porque la madera creció de golpe, como crece todo este año. Ahora tengo una cicatriz donde antes tenía una puerta."]], back: "a" },
      injerto: { say: [["agalla", "Busca la rama del norte. La que da poca fruta. Esa todavía es mía."],
                       [null, "La cortas con cuidado. Por dentro es blanca, limpia. La envuelves en musgo húmedo."],
                       ["agalla", "Llévala al Vado. Plántala donde no llegue nada dulce. Si me pasa algo, que quede algo de mí que no haya comido de esto."]], end: { xp: 16, flag: "e2_injerto" } },
      concejo: { say: [["agalla", "El Concejo. Bien. Diles que lo dice la vieja Agalla. A lo mejor todavía me escuchan."],
                       ["agalla", "Aunque no creo. Este año la fruta les habla más fuerte que yo."]], end: { xp: 8, flag: "e2_agallaAvisa" } },
      enterrar: { say: [[null, "Juntas bellotas negras toda la tarde, con una pala y una bolsa. Las entierras lejos del roble, en un pozo hondo, en roca."],
                        [null, "Al otro día, en el lugar donde las enterraste, ha crecido un brote negro de un palmo."],
                        ["agalla", "No se puede enterrar lo que crece, Cuidador. Pero gracias. Las intenciones también abonan algo."]], end: { xp: 10, hurt: 0.05 } },
    } },

    "e2-yedra": { kind: "encuentro", need: { era: 2, layer: 1 }, who: { yedra: "Yedra", comprador: "Comprador del Prado" }, start: "a", nodes: {
      a: { say: [[null, "En el camino del Bosque hay un mercado nuevo. Puestos de madera, carros del Prado, gente regateando. En el centro, en una hamaca colgada entre dos postes, la mujer que nunca guardaba el Largo Silencio dirige todo sin levantarse."],
                 ["yedra", "¡Manzanas a dos el saco! ¡Bellotas para los cerdos de las Casas! Cuidador, ven, que tengo un precio para ti."],
                 [null, "Un comprador del Prado carga sacos en un carro. Paga con monedas nuevas, las del sello de Destello."]],
           opts: [{ t: "«Le va bien, por lo que veo.»", go: "bien", once: true },
                  { t: "Comprar fruta barata", go: "comprar", fx: { cost: 5 } },
                  { t: "«Las ramas tienen venas negras por dentro.»", go: "venas", cNeed: "e2_venas" },
                  { t: "Ayudar a cargar los carros", go: "cargar" },
                  { t: "Preguntar al comprador para qué quieren tanta", go: "comprador", once: true }] },
      bien: { say: [["yedra", "¿Bien? Por primera vez en la historia el Bosque no le pide nada a nadie. Al revés: el Prado viene a comprarnos. ¿Sabes lo que es eso?"],
                    ["yedra", "Mi abuela iba al Prado a vender cestas y la hacían esperar en la puerta de atrás. Ahora sus nietos esperan en mi puerta."]], back: "a" },
      comprar: { say: [[null, "Yedra te llena un saco hasta arriba. Las manzanas son enormes. Tus criaturas comen hasta quedarse dormidas en el carro."]], end: { xp: 4, heal: 0.3 } },
      venas: { say: [["yedra", "¿Y qué? Las manzanas saben bien. Los cerdos engordan. Los del Prado pagan."],
                     ["yedra", "Mira, Cuidador. Si la fruta está mala, el año que viene no habrá. Lo sé. Por eso vendo todo ahora, al precio de ahora. Cuando venga el invierno, voy a tener plata. Los del Concejo van a tener manzanas podridas en el granero."],
                     [null, "No lo dice con maldad. Lo dice como quien ya hizo las cuentas."]],
             opts: [{ t: "«Guarde un poco de la plata para los que no van a tener.»", go: "guardar" },
                    { t: "«Está vendiendo veneno.»", go: "veneno" }] },
      guardar: { say: [["yedra", "¿Para los que no van a tener? ¿Los del Concejo, que me miraban mal por no callarme en el Silencio?"],
                       [null, "Se balancea en la hamaca mucho rato."],
                       ["yedra", "Bueno. Una moneda de cada diez. En una caja. Que nadie diga que Yedra no pensó en el invierno."]], end: { xp: 14, flag: "e2_cajaYedra" } },
      veneno: { say: [["yedra", "¿Veneno? La comen todos y nadie se murió."],
                      ["comprador", "¿Qué dice? ¿Veneno? ¿Me están vendiendo veneno?"],
                      [null, "El comprador descarga los sacos. Otros compradores miran. En diez minutos, la mitad del mercado está devolviendo fruta. Yedra te mira desde la hamaca como se mira a una tormenta."],
                      ["yedra", "Gracias, Cuidador. Este invierno, cuando el Bosque pase hambre, acuérdate de que también me quitaste a mí."]], end: { xp: 12, fight: true, flag: "e2_mercadoRoto" } },
      cargar: { say: [[null, "Cargas sacos toda la tarde. Yedra te paga con dos monedas nuevas y una manzana perfecta."],
                      ["yedra", "Trabajas bien. Si te cansas de cuidar bichos, aquí hay lugar."]], end: { coins: 22, xp: 4, flag: "e2_mercadoFruta" } },
      comprador: { say: [["comprador", "¿Para qué? Para todo. Las Casas hacen mermelada, vino, engordan cerdos. La matriarca quiere repartir fruta en el Barrio. Un año así no se ve nunca."],
                       ["comprador", "Y es barata. El Bosque siempre fue barato. Por eso venimos."]], back: "a" },
    } },

    "e2-bruma": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { bruma: "Bruma", abrojo: "Abrojo, guarda del Seto" }, start: "a", nodes: {
      a: { say: [[null, "En el borde del Bosque, donde empieza el Seto seco, hay una casita de troncos con humo en la chimenea. En la puerta, el padre de la Sombra que vivía afuera del Bosque parte leña. Tiene una cinta gris cosida en el abrigo."],
                 ["bruma", "Mira lo que me dieron. «Hondonada, casa del molino.» Mi molino se lo comió la niebla cuando yo tenía doce años."],
                 [null, "Dentro de la casita, dos niños juegan con piñas. Hablan con el acento del Bosque, no con el de la Corte."]],
           opts: [{ t: "«¿Cuándo tienen que irse?»", go: "cuando", once: true },
                  { t: "«Usted me ayudó a mí, el año pasado.»", go: "ayuda", cNeed: "ayudasteFuera", once: true },
                  { t: "«Escóndanse en el Bosque. Yo hablo con el Concejo.»", go: "esconder" },
                  { t: "«Vengan al Vado.»", go: "vado", fx: { cost: 25 } },
                  { t: "Acompañarlos por el hueco del Seto", go: "seto", cNeed: "m2_setoAbierto" },
                  { t: "«Puede que la Hondonada esté mejor de lo que cree.»", go: "mejor" }] },
      cuando: { say: [["bruma", "Antes de la primera helada. Faltan dos semanas. Abrojo me dijo que el Concejo no se va a oponer. El Concejo nunca se opone a las Casas: le venden fruta."],
                      ["bruma", "Mis hijos nacieron aquí. Para ellos el Bosque es su casa. La Hondonada es un lugar del que habla su padre cuando está triste."]], back: "a" },
      ayuda: { say: [["bruma", "Te ayudé y me ayudaste. Estamos a mano. No me debes nada."],
                     ["bruma", "Aunque, si me vas a deber algo, que sea esto: que alguien sepa que aquí vivió una familia de la Sombra veinte años y nadie del Bosque se quejó. Que eso quede en algún lado."]], back: "a" },
      esconder: { say: [[null, "Vas a ver a Abrojo. Lo encuentras cortando ramas secas del Seto."],
                        ["abrojo", "¿Esconderlos? El Concejo me pidió una lista de los de la Sombra que viven en el Bosque. Ya la entregué."],
                        ["abrojo", "Pero la casita de Bruma… se me olvidó. Es tan chica que no se ve desde el camino."],
                        [null, "No te mira. Sigue cortando."]], end: { xp: 16, flag: ["e2_brumaQueda", "u2_sombra"] } },
      vado: { say: [["bruma", "¿Al Vado? ¿Con los de la Corte, los del Prado, los del Agua, todos juntos?"],
                    ["bruma", "Bueno. Mis hijos ya hablan como el Bosque. Si viven en el Vado van a hablar como todos. A lo mejor eso es lo mejor que les puede pasar."],
                    [null, "Cargan un carro con la leña y los niños. En el Vado, tus vecinos les hacen lugar sin preguntar mucho. Es lo que tiene el Vado."]], end: { xp: 14, flag: ["e2_brumaVado", "u2_sombra"] } },
      seto: { say: [[null, "Los acompañas hasta el hueco que abriste en el Seto. Del otro lado, el camino al Envés es largo y gris."],
                    ["bruma", "Ya está. Si hay que ir, mejor ir con alguien que no esté obligado."],
                    [null, "Los niños cruzan primero. El más chico se da vuelta y saluda al Bosque con la mano. Bruma no se da vuelta."]], end: { xp: 10, flag: "e2_brumaVuelve" } },
      mejor: { say: [["bruma", "Puede. Todos dicen que está curada. Que la niebla ya no come."],
                     ["bruma", "Pero yo me acuerdo de cómo sonaba el molino antes de que se lo comiera la niebla. Si cuando llegue suena así, me quedo. Si no suena, vuelvo. Con permiso o sin permiso."]], end: { xp: 6, flag: "e2_brumaVuelve" } },
    } },

    "e2-concejo": { kind: "encuentro", need: { era: 2, layer: 2 }, who: { liquen: "Abuelo Liquen", yedra: "Yedra", concejal: "Concejala del Bosque" }, start: "a", nodes: {
      a: { say: [[null, "El Concejo del Bosque se reúne alrededor de un tocón enorme. Hay más gente que nunca: este año todos tienen algo que decir, porque todos tienen algo que vender."],
                 ["concejal", "Las Casas ofrecen comprar toda la cosecha que sobre. A cambio, el Bosque queda fuera de la Ley del Regreso: los de la Sombra que viven aquí pueden quedarse. Votemos."],
                 ["liquen", "Yo digo que guardemos. El granero lleno. El invierno que viene va a ser largo."],
                 ["yedra", "Y yo digo que el abuelo tiene miedo de un invierno que no vio nadie más que él. ¡Vendamos!"]],
           opts: [{ t: "Votar por guardar la cosecha", go: "guardar" },
                  { t: "Votar por vender a las Casas", go: "vender" },
                  { t: "Proponer mandar la fruta a Los Altos, que bajan con hambre", go: "altos" },
                  { t: "«La fruta tiene venas negras. ¿Alguien la ha abierto?»", go: "venas", cNeed: "e2_venas", once: true }] },
      venas: { say: [[null, "Abres una manzana delante de todos. El corazón está negro, brillante. Un murmullo recorre el tocón."],
                     ["concejal", "Pues que la coman los cerdos de las Casas. Mejor ellos que nosotros."],
                     [null, "Algunos se ríen. Liquen no. Yedra tampoco."]], back: "a" },
      guardar: { say: [[null, "El voto está muy parejo. Al final gana guardar, por tres votos. Las Casas no compran. La Ley del Regreso sigue para el Bosque."],
                       ["liquen", "Gracias. El granero va a estar lleno de fruta mala, y a lo mejor no sirve para nada. Pero el que llega al invierno con algo guardado, por lo menos elige qué tirar."],
                       [null, "Yedra se va antes de que termine la reunión. Varios de la Sombra que vivían en el Bosque empiezan a juntar sus cosas."]], end: { xp: 16, flag: ["e2_granero", "u2_planta"] } },
      vender: { say: [[null, "Gana vender, por mucho. Las Casas mandan carros esa misma semana. El Bosque queda fuera de la Ley del Regreso. Los de la Sombra pueden quedarse."],
                      ["yedra", "¿Ves? Todos ganan. Hasta los de la Sombra."],
                      ["liquen", "Todos ganan este año. Pregúntame el que viene."]], end: { coins: 30, xp: 10, flag: ["e2_frutaVendida", "e2_bosqueAsilo"] } },
      altos: { say: [["concejal", "¿A Los Altos? ¿Regalada? Ellos nunca nos dieron nada."],
                     ["liquen", "Nos dieron el viento que trae la lluvia, todos los años, sin cobrar. Que yo sepa."],
                     [null, "La discusión dura hasta la noche. Al final se decide una cosa rara: la mitad para el granero, la mitad para Los Altos. A las Casas, nada."],
                     ["yedra", "Ahora sí que me van a mirar mal en el Prado. Bueno. Ya me miraban."]], end: { xp: 22, flag: ["e2_frutaAltos", "e2_granero", "u2_planta"] } },
    } },

    "e2-cripta": { kind: "encuentro", need: { era: 2, layer: 2 }, who: { llovizna: "Llovizna" }, start: "a", nodes: {
      a: { say: [[null, "Las raíces del Bosque han crecido tanto este año que han empujado la puerta de piedra de la Cripta. Ahora está entreabierta, un palmo. Sale un aire tibio que huele a fruta pasada."],
                 ["llovizna", "El Concejo dice que nadie entre. Por eso vine. ¿Entramos?"],
                 [null, "Llovizna tiene una vela y la cuchara de siempre en el bolsillo. Está muerta de miedo y no se va a ir."]],
           opts: [{ t: "Entrar con ella", go: "entrar" },
                  { t: "Entrar con tus criaturas y que ella espere afuera", go: "esperar" },
                  { t: "Cerrar la puerta otra vez", go: "cerrar" }] },
      entrar: { say: [[null, "Adentro hay una sala redonda. Las raíces cubren las paredes como venas. Entre ellas, tablillas de madera dura, clavadas en la piedra, una al lado de la otra. Cientos."],
                      [null, "En cada tablilla hay un dibujo hecho con cuchillo: un árbol cargado de fruta. Debajo del árbol, rayas. Y al lado de algunas, una marca distinta: un árbol pelado."],
                      ["llovizna", "Son años. Cada tablilla es un año. Los abuelos del Bosque los contaban."]],
              opts: [{ t: "Contar las tablillas", go: "contar" },
                     { t: "Copiar las tablillas en tu libreta", go: "copiar" },
                     { t: "Tocar las raíces de las paredes", go: "raices" }] },
      esperar: { say: [["llovizna", "¿Que espere afuera? ¿Yo? Yo encontré la puerta abierta."],
                       [null, "Pero espera. Entras con tus criaturas. Adentro hay cientos de tablillas clavadas en las raíces. Las miras rápido, sin entender, y sales con una en la mano."],
                       ["llovizna", "¿Qué es? A ver… es un árbol con fruta. Y al lado, un árbol pelado. ¿Qué quiere decir?"]], end: { xp: 10, flag: "e2_tablillaSuelta" } },
      contar: { say: [[null, "Llovizna cuenta con la cuchara. Tú anotas. Tardan horas. Cada vez que hay un árbol muy cargado, la tablilla siguiente tiene un árbol pelado. Siempre."],
                      [null, "Y cada vez que hay un árbol pelado, debajo, en la misma tablilla, hay un dibujo chiquito: una figura con las manos abiertas, frente a un círculo."],
                      ["llovizna", "Alguien que canta. Cada vez que el Bosque se murió, alguien cantó. ¿Y después?"],
                      [null, "Después, la tablilla siguiente tiene un árbol normal. Ni cargado ni pelado. Y cuarenta, cincuenta tablillas más tarde, otra vez un árbol cargado."]], end: { xp: 20, flag: "e2_tablillas", escrito: "e2-tablillas" } },
      copiar: { say: [[null, "Copias veinte tablillas, las más claras. Un árbol cargado, un árbol pelado, alguien que canta. Una y otra vez."],
                      ["llovizna", "Se repite. Como la nana. Como todo."],
                      [null, "Al salir, la puerta de piedra se cierra sola detrás de ustedes, empujada por las raíces. Un palmo menos que antes."]], end: { xp: 18, flag: "e2_tablillas", escrito: "e2-tablillas" } },
      raices: { say: [[null, "Las raíces están tibias. Laten. Despacio, una vez cada mucho rato, como un corazón muy grande y muy dormido."],
                      [null, "Llovizna pone la mano al lado de la tuya. Se queda quieta mucho rato."],
                      ["llovizna", "Tiene hambre. Lo sé porque cuando yo tengo hambre late igual."]], end: { xp: 12, flag: "e2_respira" } },
      cerrar: { say: [[null, "Empujas la puerta de piedra. Llovizna te ayuda, enojada. Se cierra con un golpe sordo."],
                      ["llovizna", "Siempre hacen eso los grandes. Cierran lo que da miedo y se van a dormir."],
                      [null, "Esa noche, las raíces vuelven a empujar. Al amanecer, la puerta está abierta otra vez."]], end: { xp: 4 } },
    } },

    "e2-llovizna": { kind: "dialogo", need: { era: 2, layer: 3 }, who: { llovizna: "Llovizna", liquen: "Abuelo Liquen" }, start: "a", nodes: {
      a: { say: [[null, "Llovizna te espera en el camino con una mochila hecha. Tiene la cuchara colgada del cuello con un cordón."],
                 ["llovizna", "Me voy al Prado. Al coro del Barrio. Pagan media ración por cantar, y yo canto bonito. Todos lo dicen."],
                 ["llovizna", "El abuelo Liquen dice que no. Dice que el coro es una trampa. Pero el abuelo dice que todo es una trampa."]],
           opts: [{ t: "«¿Por qué quieres ir?»", go: "porque", once: true },
                  { t: "«El coro ya no existe. Lo saboteamos.»", go: "sabotaje", cNeed: "m2_coroSabotea", once: true },
                  { t: "«Te acompaño. Que vayas, pero no sola.»", go: "acompanar" },
                  { t: "«Quédate. El Bosque te necesita aquí.»", go: "quedarse" },
                  { t: "«Ven al Vado. Allá se canta sin que te paguen.»", go: "vado" }] },
      porque: { say: [["llovizna", "Porque en el Bosque todos me tratan como a la niña de la cuchara. Y yo encontré las tablillas, y le puse la oreja a la raíz, y nadie me cree."],
                      ["llovizna", "En el coro, por lo menos, me van a oír."]], back: "a" },
      sabotaje: { say: [["llovizna", "¿Lo saboteaste? Me dijeron que hicieron otro. Más grande. En la plaza de la Torre. Con dos maestras en vez de una."],
                        [null, "Lo dice sin malicia. Sacarlo de una tarima solo lo puso en otra más alta."]], back: "a" },
      acompanar: { say: [[null, "Caminan hasta el Prado. En la puerta del coro nuevo, la maestra la mira de arriba abajo."],
                         [null, "Llovizna canta. Canta la canción del Bosque, la que se canta en el Largo Silencio. No es una nana. La maestra frunce el ceño. El farol de la tarima no brilla más. Pero tres chicos del Barrio dejan de cantar para escucharla."],
                         ["llovizna", "No me quisieron. Dicen que mi canción no da luz."],
                         [null, "Lo dice contenta."]], end: { xp: 18, flag: "e2_lloviznaCanta" } },
      quedarse: { say: [["llovizna", "¿Me necesita? ¿Para qué? ¿Para juntar fruta mala?"],
                        ["liquen", "Para acordarse, niña."],
                        [null, "El abuelo Liquen está detrás de un árbol. Escuchó todo."],
                        ["liquen", "Yo me estoy olvidando de cosas. Del Bosque de donde vine, de cómo era la nana antes. Si te vas, ¿quién se acuerda después de mí?"],
                        [null, "Llovizna deja la mochila en el suelo. No dice nada. Se sienta al lado del abuelo."]], end: { xp: 16, flag: ["e2_lloviznaQueda", "u2_planta"] } },
      vado: { say: [["llovizna", "¿Al Vado? ¿Contigo? ¿A cuidar criaturas?"],
                    ["llovizna", "¡Sí! Bueno. Pero los domingos vuelvo a ver al abuelo. Y llevo la cuchara."],
                    [null, "En el Vado, Unísona la escucha cantar la canción del Bosque. Al final, canta con ella una nota más alta. La primera vez que la oyes cantar en semanas."]], end: { xp: 20, flag: ["e2_lloviznaVado", "e2_unisonaCanta"] } },
    } },

    "e2-raices": { kind: "encuentro", need: { era: 2, layer: 3, anyFlag: ["m2_setoAbierto", "m2_setoCerrado", "e2_setoBebe"] }, who: { abrojo: "Abrojo, guarda del Seto", liquen: "Abuelo Liquen" }, start: "a", nodes: {
      a: { say: [[null, "Abrojo y el abuelo Liquen han cavado un pozo al pie del Seto seco, hasta la altura de un hombre. Te llaman para que veas el fondo."],
                 [null, "Abajo, las raíces del Seto son gruesas como brazos y están hinchadas. Por fuera, marrones. Por dentro, cuando Abrojo corta una, sale savia negra, espesa. Mucha."],
                 ["liquen", "Planté un muro y me creció una madre. El Seto no se está muriendo de nada. Se está muriendo de tragar."],
                 ["abrojo", "Está bebiendo la savia antes de que llegue al Bosque. Por eso se seca. Lo de arriba se muere para que lo de abajo aguante."]],
           opts: [{ t: "«¿Cuánto le queda?»", go: "cuanto", once: true },
                  { t: "«Déjenlo hacer. Que siga bebiendo.»", go: "dejar" },
                  { t: "«Corten las raíces. Que no muera por nosotros.»", go: "cortar" },
                  { t: "Pedirle a Unísona que le cante", go: "cantar" },
                  { t: "Plantar el injerto de Agalla junto al Seto", go: "injerto", cNeed: "e2_injerto" }] },
      cuanto: { say: [["abrojo", "Un invierno. Puede que dos. Después se seca entero y la savia sigue de largo."],
                      ["liquen", "Y entonces la fruta de este año va a parecer un chiste. El Bosque entero va a ser como esas bellotas."]], back: "a" },
      dejar: { say: [["liquen", "Que siga. Está haciendo lo que hace una madre. No es justo, pero es lo que hace."],
                     [null, "Vuelven a tapar el pozo. Arriba, el Seto deja caer otra rama seca."],
                     ["abrojo", "Le voy a decir al Concejo que no corten más. Que lo dejen morirse tranquilo."]], end: { xp: 14, flag: "e2_setoMuere" } },
      cortar: { say: [[null, "Abrojo duda. Luego corta. Una raíz, dos, cinco. La savia negra brota y se escurre hacia el Bosque, buscando camino entre las piedras."],
                      [null, "Al otro día, el Seto echa hojas verdes. Muy verdes. Y en el Bosque, al lado del camino, los manzanos amanecen con la fruta podrida en la rama."],
                      ["liquen", "Le salvaste la vida al Seto. Y le pasaste la cuenta al Bosque. Así es siempre, Cuidador: la cuenta la paga alguien."]], end: { xp: 12, flag: "e2_setoCorta", hurt: 0.1 } },
      cantar: { say: [[null, "Unísona se acerca al borde del pozo. Mira las raíces negras. Luego canta. No es la nana: es algo más bajo, más lento, como el ronroneo de un animal grande."],
                      [null, "Las raíces dejan de latir tan rápido. La savia que sale de los cortes se vuelve más clara, más lenta. No se cura. Duerme."],
                      ["abrojo", "Nunca oí a una criatura cantarle a un árbol."],
                      ["liquen", "Yo sí. Una vez. Hace mucho, en otro Bosque. Antes de que se muriera."]], end: { xp: 20, flag: ["e2_setoDuerme", "u2_planta"] } },
      injerto: { say: [[null, "Plantas la rama blanca de Doña Agalla al lado del Seto, donde las raíces todavía no están hinchadas."],
                       [null, "La rama se queda quieta. No echa raíces hacia abajo. Las echa hacia los costados, hacia las raíces del Seto, y se enreda con ellas."],
                       ["liquen", "Lo está ayudando. Una le pasa a la otra lo que le sobra. Así se aguantan los árboles viejos, abajo, donde no se ve."]], end: { xp: 24, flag: ["e2_setoDuerme", "e2_agallaSeto", "u2_planta"] } },
    } },
  });
  /* ==================== Entrega 3: la Noche (Hondonada Umbría, Lago Espejo, Cuevas del Eco) ==================== */

  /* ---------- Hondonada Umbría: casas sin sombra, cartas partidas, el trono vacío y la niebla que vuelve ---------- */
  add("hollow", {
    "e2-cuna": { kind: "encuentro", need: { era: 2, layer: 1 }, who: { orvallo: "Orvallo" }, start: "a", nodes: {
      a: { say: [[null, "En la puerta de una casa de la Corte, un hombre mece una cuna de madera. Es la misma cuna que bajó hace un año por el camino del Prado, cargada a la espalda."],
                 ["orvallo", "No duerme. Tres semanas sin dormir más de una hora seguida. En el Barrio dormía como una piedra."],
                 [null, "La casa no hace sombra. El sol de la tarde la atraviesa como si fuera de vidrio. Dentro de la cuna, la bebé tiene los ojos muy abiertos y mira la luz."]],
           opts: [{ t: "«¿Por qué no duerme?»", go: "porque", once: true },
                  { t: "«Usted llevó la cuna al Barrio. ¿Por qué volvió?»", go: "volvio", cNeed: "cunaBarrio", once: true },
                  { t: "Hacerle sombra con tu capa", go: "capa" },
                  { t: "Pedirle a Unísona que cante la nana de la Sombra", go: "nana" },
                  { t: "«Llévela al Vado. Allá hay sombra de verdad.»", go: "vado", fx: { cost: 10 } }] },
      porque: { say: [["orvallo", "Porque los niños de la Corte duermen en la sombra de la casa. No en la oscuridad: en la sombra. Es distinto. La sombra de una casa es como un brazo."],
                      ["orvallo", "Aquí las casas ya no hacen. La niebla se fue y se llevó la sombra con ella. Mi hija nunca vio la Hondonada de antes, y aun así la extraña."]], back: "a" },
      volvio: { say: [["orvallo", "Porque la Ley lo dice, y porque el cuarto del Barrio era prestado. Nos dieron un carro, una manta y una cinta gris."],
                      ["orvallo", "En el Barrio por lo menos los vecinos cantaban. Aquí estamos veinte familias y nadie canta. Da vergüenza cantar en una casa que no hace sombra, como si uno cantara en la casa de un muerto."]], back: "a" },
      capa: { say: [[null, "Tiendes tu capa sobre la cuna. Debajo se hace una sombra chiquita, del tamaño de la bebé."],
                    [null, "La bebé parpadea. Bosteza. A los pocos minutos se duerme con el puño en la boca."],
                    ["orvallo", "Una capa. Tres semanas, y era una capa. Quédate un rato, por favor. Si te vas, se la lleva el sol."]], end: { xp: 10, heal: 0.15, flag: "e2_capaCuna" } },
      nana: { say: [[null, "Unísona se sienta junto a la cuna y canta la mitad oscura de la nana, la de la Sombra. Muy bajito."],
                    [null, "No pasa nada con la luz. Pero de las casas vecinas sale gente. Una mujer se pone a cantar con Unísona desde su ventana. Después otra. Después un viejo, desafinado."],
                    ["orvallo", "Primera vez que se canta aquí desde que volvimos. Mírala: ya duerme."]], end: { xp: 16, flag: ["e2_hondonadaCanta", "u2_sombra"] } },
      vado: { say: [["orvallo", "¿Al Vado? ¿Sin permiso? Si me encuentran sin la cinta en su sitio, me quitan el permiso del Umbral para siempre."],
                    ["orvallo", "Pero ella duerme. Allá duerme. Lo demás ya veremos."],
                    [null, "Carga la cuna a la espalda otra vez. Es la tercera vez en un año que esa cuna cruza el Claro."]], end: { xp: 12, flag: "e2_cunaVado" } },
    } },

    "e2-tordo": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { tordo: "Tordo, cartero de la Corte" }, start: "a", nodes: {
      a: { say: [[null, "El cartero viejo de la Corte sube la cuesta con una bolsa tan llena que tiene que llevarla abrazada. Se sienta en una piedra a recuperar el aire."],
                 ["tordo", "Nunca hubo tantas cartas. La Ley partió a las familias por la mitad: unos volvieron, otros se quedaron arriba con permiso de trabajo. Y se escriben. Todos los días."],
                 ["tordo", "Yo las llevo. No sé leer bien, pero sé de quién es cada letra. Me llamo Tordo, por si no te acuerdas. Nadie se acuerda del cartero."]],
           opts: [{ t: "Ofrecerte a llevar la mitad de la bolsa", go: "llevar" },
                  { t: "«¿Hay alguna carta que no pueda entregar?»", go: "noentrega", once: true },
                  { t: "«¿Le llegó por fin la carta de Penumbra?»", go: "penumbra", cNeed: "cartaPenumbra", once: true },
                  { t: "Leer una carta abierta que se cayó de la bolsa", go: "leer" }] },
      llevar: { say: [[null, "Cargas cartas toda la tarde, puerta por puerta. Algunas personas lloran al recibirlas. Una mujer rompe la suya sin abrirla."],
                      ["tordo", "Esa es la del marido que se quedó arriba. Le escribe todos los días. Ella las rompe todos los días. Las dos cosas son amor, Cuidador. Te lo digo yo, que llevo cuarenta años en esto."]], end: { xp: 10, coins: 15 } },
      noentrega: { say: [["tordo", "Hay unas. Cartas de los que se fueron en los carros de la Casa Alba. No son del Prado ni de aquí. Las mandan sin dirección, con un sello raro."],
                         [null, "Te da una. El sello es una pala cruzada con una lámpara. Por dentro, la letra es de alguien que apenas sabe escribir."]],
                   opts: [{ t: "Abrirla", go: "abrir" },
                          { t: "Devolvérsela sin abrir", go: "devolver" }] },
      abrir: { say: [[null, "«Mamá: no estoy en la Hondonada. Los carros de la Casa Alba no fueron a la casa del puente. Nos bajaron por un túnel. Picamos de noche. Las paredes están tibias. Me pagan, no te preocupes. No digas a nadie dónde estoy, porque no sé dónde estoy. Tu hijo, Grieto.»"],
                     ["tordo", "Grieto. El hijo de la familia Ceniza, la de la casa del puente. La madre lo espera allá abajo, mirando el camino todos los días."],
                     ["tordo", "Si le llevo esto, ¿le hago bien o le hago mal? Eso no me lo enseñaron en cuarenta años."]],
             opts: [{ t: "«Llévesela. Tiene derecho a saberlo.»", go: "entregar" },
                    { t: "«Quédesela. Yo voy a buscar ese túnel.»", go: "buscar" }] },
      entregar: { say: [[null, "Tordo baja a la casa del puente. Tarda mucho. Cuando vuelve, no trae la bolsa abrazada: la trae colgando, como si pesara menos."],
                        ["tordo", "Lloró. Y después se puso el abrigo y se fue a la plaza a preguntarle a todo el mundo por los carros de la Casa Alba. Ya van seis madres con ella."]], end: { xp: 16, flag: ["e2_cartaGrieto", "e2_madresPreguntan"], escrito: "e2-carta-grieto" } },
      buscar: { say: [["tordo", "¿Buscarlo tú? Bien. Toma la carta. Si lo encuentras, dile que su madre le guarda la cama hecha."],
                      [null, "Te guardas la carta. La pala cruzada con la lámpara te mira desde el sello."]], end: { xp: 14, flag: ["e2_cartaGrieto", "e2_buscaGrieto"], escrito: "e2-carta-grieto" } },
      devolver: { say: [["tordo", "Gracias. A veces no abrir una carta es lo único que le queda a uno de decente."],
                        [null, "La mete al fondo de la bolsa, debajo de todas las otras."]], end: { xp: 6 } },
      penumbra: { say: [["tordo", "La entregué. Tardé, pero la entregué. Ella volvió a bajar a buscar su calle, ¿sabías? Con su cinta bordada."],
                        ["tordo", "Le dije que la calle del telar ya no existe. Me dijo: «Entonces voy a bordarla». No sé qué quiso decir."]], back: "a" },
      leer: { say: [[null, "«Pablito: aquí arriba hay luz toda la noche y no puedo dormir. Dicen que allá abajo ya no hay niebla. ¿Es verdad que la casa no hace sombra? Guárdame la mía, aunque sea en un frasco. Te quiero. Mamá.»"],
                    ["tordo", "Esa no se cayó. Esa la dejé caer yo, para que alguien más la leyera. Me pesa llevarla solo."]], end: { xp: 8 } },
    } },

    "e2-cierzo": { kind: "dialogo", need: { era: 2, layer: 2 }, who: { cierzo: "Cierzo, guarda del Trono", ceniza: "Ceniza" }, start: "a", nodes: {
      a: { say: [[null, "En la sala del Trono no hay rey. Lóbrego se mudó a una tienda en la plaza después de confesar. Pero el guarda del Trono sigue en su puesto, con la lanza, cuidando una silla vacía."],
                 ["cierzo", "Me llamo Cierzo. Cuarenta años cuidando esta silla. El rey se fue, pero la silla sigue siendo la silla. Alguien tiene que cuidarla."],
                 ["cierzo", "Cuidador, tú le diste al rey el valor para confesar. Y mira lo que pasó. Tres nombres gritados en el Prado. Familias en carros. La niebla se fue. Dime que valió la pena."]],
           opts: [{ t: "«Valió. La verdad no tiene la culpa de lo que hicieron con ella.»", go: "valio" },
                  { t: "«No sé si valió.»", go: "nosabe" },
                  { t: "«Usted quemó el acta, el año pasado.»", go: "acta", cNeed: "quemasteActa", once: true },
                  { t: "«¿Qué propone?»", go: "propone" }] },
      valio: { say: [["cierzo", "Eso dicen los que no perdieron nada."],
                     [null, "Pero baja un poco la lanza."],
                     ["cierzo", "Mi madre decía lo mismo que tú. Que la verdad no muerde. Mi madre nunca vio a una sombra con el nombre gritado."]], back: "a" },
      nosabe: { say: [["cierzo", "Por lo menos dices la verdad. Eso es más de lo que dicen los del Prado."]], back: "a" },
      acta: { say: [["cierzo", "Me la quemaste tú, si mal no recuerdo. O la quemé yo para que no la quemaras tú. Ya no me acuerdo bien, y eso me preocupa."],
                    ["cierzo", "El rey confesó igual. Sin papel. Con la boca. Las palabras dichas no se queman."]], back: "a" },
      propone: { say: [["cierzo", "Que volvamos al velo. Todos. Que ninguna sombra diga su nombre de verdad nunca más, ni a su madre. Que nos llamemos todos por lo que hacemos, como en los Pozos."],
                       ["cierzo", "Así nadie puede gritar un nombre. Porque no habrá nombres."],
                       [null, "Detrás de una columna, alguien escucha. Una muchacha con la capucha calada."],
                       ["ceniza", "Eso es lo que hacía Albor con nosotros. Llamarnos por lo que hacíamos. ¿Ahora nos lo hacemos solos?"]],
                 opts: [{ t: "Apoyar a Cierzo: el velo protege", go: "velo" },
                        { t: "Apoyar a Ceniza: el nombre es lo que se recuperó", go: "nombre" },
                        { t: "«Que cada uno elija.»", go: "elegir" }] },
      velo: { say: [["cierzo", "Gracias. Mañana lo propongo en la plaza. La gente tiene miedo. Con miedo, se vota rápido."],
                    ["ceniza", "Vas a ver qué rápido nos olvidamos de cómo nos llamamos."],
                    [null, "Ceniza se va. Cierzo vuelve a cuidar la silla, más tranquilo."]], end: { xp: 10, flag: "e2_veloVuelve" } },
      nombre: { say: [["ceniza", "Gracias. Aunque me lo griten. Aunque tenga que ir cuando me llamen."],
                      ["cierzo", "Eres joven, muchacha. Ya vas a aprender."],
                      ["ceniza", "Usted también era joven cuando le enseñaron a tener miedo. No lo olvide."],
                      [null, "Cierzo no contesta. Pero esa noche, por primera vez en cuarenta años, deja la lanza apoyada en la silla y se va a dormir a su casa."]], end: { xp: 16, flag: ["e2_cenizaNombre", "u2_sombra"] } },
      elegir: { say: [["cierzo", "¿Elegir? La Corte nunca eligió nada. Por eso aguantó seiscientos años."],
                      ["ceniza", "Por eso la echaron de dos tierras, también."],
                      [null, "Discuten toda la tarde. Al final, en la plaza, se decide eso: que cada uno elija. La mitad se pone el velo. La otra mitad no. Por primera vez se distingue quién es quién."]], end: { xp: 14, flag: "e2_veloElegido" } },
    } },

    "e2-telar": { kind: "encuentro", need: { era: 2, layer: 2 }, who: { penumbra: "Penumbra", calina: "Calina, tejedora de niebla" }, start: "a", nodes: {
      a: { say: [[null, "Al fondo de la Hondonada, donde la niebla se comió una calle hace veinte años, hay ahora un campo de piedras. Encima, sentada en un banco de telar sin telar, la costurera de la Sombra borda en el aire."],
                 ["penumbra", "La calle del telar. Mi cinta dice que vuelvo aquí. Entonces aquí estoy. No hay calle, pero estoy."],
                 [null, "A su lado, la tejedora de niebla le pasa hilos grises que se deshacen al tocarlos. Juntas intentan algo que no sale."]],
           opts: [{ t: "«¿Qué están haciendo?»", go: "que", once: true },
                  { t: "«Usted bordó “Vado” en vez de “Envés”. ¿Por qué vino?»", go: "vado", cNeed: "e2_cintasVado", once: true },
                  { t: "Ayudarlas con los hilos", go: "ayudar" },
                  { t: "Cantar la nana de la Sombra sobre las piedras", go: "cantar" },
                  { t: "Buscar algo entre las piedras", go: "buscar" }] },
      que: { say: [["calina", "Coser la calle. Si la niebla no sale del suelo, que salga de nosotras. Ella borda, yo tejo. Llevamos tres días."],
                   ["penumbra", "No sale. Pero es lo primero que hago en años que no sea un nombre ajeno en una cinta."]], back: "a" },
      vado: { say: [["penumbra", "Porque las ciento doce personas que bordamos tenían adónde ir. Yo no. El Vado no me conoce y yo no conozco al Vado."],
                    ["penumbra", "Y porque alguien tiene que volver para contar si se puede vivir aquí. Mejor una vieja que una familia con niños."]], back: "a" },
      ayudar: { say: [[null, "Sostienes los hilos mientras ellas trabajan. Se deshacen igual. Pero cuando cae la noche, entre tus dedos, uno aguanta. Uno solo. Gris, tibio, fino como un pelo."],
                      ["calina", "Ese salió de tus manos, no de las nuestras. Las de arriba todavía tienen algo de niebla guardada, de tanto bajar."],
                      [null, "Penumbra lo cose en el borde de su cinta, al lado de su nombre."]], end: { xp: 12, flag: "e2_hiloNiebla" } },
      cantar: { say: [[null, "Cantas sobre las piedras. Unísona canta contigo. Al principio, nada."],
                      [null, "Luego, entre dos piedras, sale una niebla baja, a la altura de los tobillos. Se queda ahí. No sube. Pero dibuja, por un momento, el contorno de una calle: puertas, escalones, un telar."],
                      ["penumbra", "Ahí estaba. La casa del medio era la mía."],
                      ["calina", "La Raíz no duerme tan hondo como dicen. Se acuerda."]], end: { xp: 18, flag: ["e2_calleVista", "e2_hebra"] } },
      buscar: { say: [[null, "Entre las piedras encuentras una lanzadera de telar, gastada, con iniciales talladas. Penumbra la reconoce antes de que se la des."],
                      ["penumbra", "La de mi madre. Veinte años bajo la tierra y la madera está tibia."],
                      [null, "No llora. La sostiene como se sostiene una mano."]], end: { xp: 10, flag: "e2_lanzadera" } },
    } },

    "e2-carros": { kind: "encuentro", need: { era: 2, layer: 2 }, who: { agente: "Agente de la Casa Alba", orvallo: "Orvallo" }, start: "a", nodes: {
      a: { say: [[null, "Llegan tres carros de la Ley del Regreso a la plaza de la Hondonada. Bajan las familias, con sus cintas. Un hombre con una libreta y el escudo de la Casa Alba las espera."],
                 ["agente", "Hombres de entre quince y cuarenta, a la izquierda. Hay trabajo pagado. Muy bien pagado. Los demás, a sus casas."],
                 [null, "Algunos van a la izquierda contentos. Otros miran a sus mujeres. Un carro sin ventanas espera detrás, con los caballos inquietos."]],
           opts: [{ t: "«¿Qué trabajo?»", go: "trabajo", once: true },
                  { t: "Enseñar la carta de Grieto delante de todos", go: "carta", cNeed: "e2_cartaGrieto" },
                  { t: "Ponerte delante del carro sin ventanas", go: "carro" },
                  { t: "Seguir al carro de lejos", go: "seguir" },
                  { t: "Apuntarte tú también, a la izquierda", go: "apuntarte" }] },
      trabajo: { say: [["agente", "Obras de la Casa. Lejos de aquí. Comida, techo y paga doble. ¿Algún problema?"],
                       ["orvallo", "Doble. Con doble se compra una casa que haga sombra."],
                       [null, "Orvallo deja la cuna en el suelo. Da un paso hacia la izquierda."]], back: "a" },
      carta: { say: [[null, "Lees la carta en voz alta. «Nos bajaron por un túnel. Picamos de noche. Las paredes están tibias.»"],
                     [null, "La plaza se queda en silencio. Los de la izquierda se miran. Uno vuelve con su familia. Después otro. Orvallo levanta la cuna."],
                     ["agente", "Eso es una falsificación. Las Casas pagan."],
                     [null, "Pero el carro sin ventanas se va vacío. Las madres que preguntaban por Grieto rodean al agente."]], end: { xp: 22, flag: ["e2_carroVacio", "u2_sombra"] } },
      carro: { say: [[null, "Te plantas delante de los caballos. El cochero tira de las riendas. El agente cierra la libreta."],
                     ["agente", "Apártate, Cuidador. Esto es un contrato de la Casa Alba."],
                     [null, "No te apartas. El agente hace una seña. Dos guardas bajan del pescante."]], end: { xp: 16, fight: true, flag: "e2_carroParado" } },
      seguir: { say: [[null, "Sigues al carro de lejos. No va a ninguna casa de la Hondonada. Va al fondo del valle, donde una boca de túnel nueva, tapada con lonas, se abre en la roca."],
                      [null, "Los hombres bajan. Entran. Del túnel sale un aire tibio que huele a fruta pasada. Encima de la boca, pintado en la roca, el mismo sello: una pala cruzada con una lámpara."]], end: { xp: 14, flag: "e2_tunelHondo" } },
      apuntarte: { say: [["agente", "¿Tú? Bueno, tienes brazos. Al carro."],
                         [null, "Te subes. Adentro está oscuro y huele a miedo. Un muchacho a tu lado aprieta una cinta gris entre los dedos."],
                         [null, "El carro baja mucho tiempo. Cuando se abre la puerta, estás en una galería bajo el Prado, frente a un tubo de cristal que late. Te dan una pala y un número."]], end: { xp: 18, flag: ["e2_tunelHondo", "e2_bajaste"], hurt: 0.1 } },
    } },

    "e2-llamada": { kind: "dialogo", need: { era: 2, layer: 3, anyFlag: ["m2_cenizaVado", "e2_cenizaNombre", "e2_lobregoViene", "e2_culpaRey"] }, who: { ceniza: "Ceniza", lobrego: "Rey Lóbrego" }, start: "a", nodes: {
      a: { say: [[null, "Es de noche. Desde la plaza, alguien grita un nombre. No es «Ceniza». Es el otro, el de verdad, el que leyó la matriarca de la caja de Albor."],
                 [null, "Ceniza se levanta. Tiene los ojos abiertos pero no mira nada. Camina hacia la puerta como camina alguien dormido."],
                 ["ceniza", "Me llaman. Tengo que ir. No es ley. Es lo que somos."]],
           opts: [{ t: "Ponerte en la puerta", go: "puerta" },
                  { t: "Pedirle a Unísona que cante más fuerte que el grito", go: "cantar" },
                  { t: "Ir tú a ver quién llama", go: "quien" },
                  { t: "Llamarla tú por su nombre de verdad, para que venga contigo", go: "llamar" }] },
      puerta: { say: [[null, "Te pones en la puerta. Ceniza choca contigo y sigue empujando, despacio, sin fuerza y sin parar, como el agua contra una piedra."],
                      ["ceniza", "Déjame. Me duele no ir. Me duele como una quemadura."],
                      [null, "No puedes sostenerla toda la noche. Ella lo sabe. Tú también."]],
              opts: [{ t: "Dejarla ir y seguirla", go: "quien" },
                     { t: "Aguantar hasta que se calle el grito", go: "aguantar" }] },
      aguantar: { say: [[null, "Aguantas. Ceniza empuja. El grito sigue, cada vez más ronco. A la hora, se calla."],
                        [null, "Ceniza cae al suelo, temblando, como después de una fiebre. Tiene las palmas quemadas de tanto apretarte la ropa."],
                        ["ceniza", "Gracias. No sé si me salvaste o me robaste algo. Las dos cosas, creo."]], end: { xp: 14, hurt: 0.1, flag: "e2_cenizaAguanta" } },
      cantar: { say: [[null, "Unísona canta. No la nana: un sonido largo, alto, que llena el cuarto. Ceniza se para."],
                      [null, "El grito de la plaza sigue, pero ahora hay algo más fuerte encima. Ceniza parpadea. Te mira, por fin."],
                      ["ceniza", "Lo oigo. Pero ya no me llama a mí. Llama a alguien que se parece a mí."],
                      [null, "Unísona no para de cantar hasta el amanecer. Al día siguiente no tiene voz. Pero Ceniza sigue en el cuarto."]], end: { xp: 20, flag: ["e2_cenizaLibre", "u2_sombra"] } },
      quien: { say: [[null, "En la plaza, debajo de la ventana, hay un chico de unos doce años con una hoja de papel en la mano. Lee el nombre en voz alta, letra por letra, porque no sabe leer de corrido."],
                     [null, "Ceniza llega detrás de ti y se para frente a él, como quien espera una orden."],
                     ["lobrego", "¿Quién te dio ese papel, muchacho?"],
                     [null, "El rey ha bajado de su tienda, sin velo. El chico tiembla."],
                     [null, "«Un señor de la Casa Alba. Me dio una moneda por gritarlo cada noche. Dijo que era un juego.»"]],
             opts: [{ t: "Quitarle el papel y romperlo", go: "romper" },
                    { t: "Darle tú dos monedas para que no vuelva", go: "pagar", fx: { cost: 10 } }] },
      romper: { say: [[null, "Rompes el papel. El chico sale corriendo. Ceniza se queda quieta, todavía esperando la orden que no llega."],
                      ["lobrego", "Van a hacer otro papel. Y otro. Mientras ese nombre esté escrito en alguna caja de la Casa Alba, ella no es libre."],
                      ["lobrego", "Si vas al Corazón, Cuidador, la Corte va contigo. Ya no por mí. Por ella."]], end: { xp: 18, flag: ["e2_cajaAlba", "e2_lobregoViene", "u2_sombra"] } },
      pagar: { say: [[null, "El chico agarra las monedas y se va. Mañana la Casa Alba encontrará a otro chico, pero esta noche la plaza calla."],
                     ["ceniza", "Me salvaste por dos monedas. Así de barato es un nombre aquí."]], end: { xp: 10, flag: "e2_cenizaNoche" } },
      llamar: { say: [[null, "Dices su nombre de verdad. Bajito. Ella se da vuelta hacia ti, como se da vuelta hacia el sol una planta."],
                      [null, "Viene contigo. Te sigue adentro. Se sienta donde le dices. El grito de la plaza ya no la mueve: ahora la llama otro."],
                      ["ceniza", "¿Ves? Ya no soy de nadie. Soy tuya. Eso tampoco es libre, Cuidador."],
                      [null, "Lo dice sin enojo. Lo dice para que no se te olvide."]], end: { xp: 12, flag: "e2_cenizaTuya" } },
    } },

    "e2-niebla": { kind: "encuentro", need: { era: 2, layer: 3 }, who: { calina: "Calina, tejedora de niebla", cierzo: "Cierzo, guarda del Trono" }, start: "a", nodes: {
      a: { say: [[null, "Esta mañana la Hondonada amaneció con niebla. No mucha: un velo blanco que sube del suelo hasta las rodillas, que respira despacio, sube y baja."],
                 [null, "La gente sale a la calle descalza. Algunos lloran. Los niños que nacieron arriba no saben qué es y se esconden."],
                 ["calina", "Volvió. No toda, pero volvió. La Raíz se mueve en sueños. Algo la molesta abajo, en el Prado, y se da vuelta en la cama."]],
           opts: [{ t: "«Entonces no es una buena noticia.»", go: "mala", once: true },
                  { t: "Juntar niebla en un frasco", go: "frasco" },
                  { t: "Pedirle a Calina que la teja sobre las casas", go: "tejer" },
                  { t: "Avisar a todos que la Raíz se está despertando", go: "avisar" }] },
      mala: { say: [["calina", "No. Pero es la única que tenemos."],
                    ["cierzo", "Mi madre decía que la niebla era el aliento de una madre dormida. Si respira más fuerte, se está despertando. Y las madres que se despiertan con hambre…"],
                    [null, "No termina. No hace falta."]], back: "a" },
      frasco: { say: [[null, "Hundes un frasco en la niebla y lo tapas. Adentro, el blanco se mueve, despacio, como un pez en una pecera."],
                      ["calina", "Llévalo contigo. Si un día cantas en el Corazón, que la Raíz huela su propio aliento. A lo mejor se acuerda de que antes respiraba tranquila."]], end: { xp: 14, flag: "e2_frascoNiebla" } },
      tejer: { say: [[null, "Calina teje toda la tarde. Peina la niebla con los dedos y la sube, hilo por hilo, hasta los tejados. Al anochecer, tres casas tienen sombra otra vez."],
                     [null, "Una de ellas es la de Orvallo. Desde la ventana se oye una cuna que se mece, y luego nada: una bebé que duerme."],
                     ["calina", "Tres casas. Es una calle, casi. Si la Corte va al Corazón algún día, va a ir con sombra propia."]], end: { xp: 18, flag: ["e2_sombraTejida", "u2_sombra"] } },
      avisar: { say: [[null, "Vas de puerta en puerta. Algunos te escuchan. La mayoría está demasiado contenta para oír."],
                      ["cierzo", "No les quites esto, Cuidador. Una mañana. Déjales una mañana."],
                      [null, "Al mediodía, la niebla se va. La gente vuelve a sus casas sin sombra. Pero ahora saben que puede volver, y que eso no es una buena noticia."]], end: { xp: 10, flag: "e2_hondonadaSabe" } },
    } },

    "e2-pablito": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { nino: "Niño de la Hondonada" }, start: "a", nodes: {
      a: { say: [[null, "Un niño de unos ocho años está sentado en el escalón de una casa vacía, con un frasco de vidrio en las rodillas. El frasco está vacío. Lo tapa y lo destapa, una y otra vez."],
                 ["nino", "Mi mamá me pidió que le guarde la sombra de la casa en un frasco. Me lo escribió. Pero la casa no hace sombra. ¿Cómo se guarda algo que no hay?"]],
           opts: [{ t: "«¿Dónde está tu mamá?»", go: "mama", once: true },
                  { t: "Hacer sombra con la mano sobre el frasco y taparlo rápido", go: "mano" },
                  { t: "«Vamos a guardar otra cosa: tu voz. Cántale algo.»", go: "voz" },
                  { t: "«No se puede. Lo siento.»", go: "nopuede" }] },
      mama: { say: [["nino", "Arriba, en el Prado. Tiene permiso de trabajo. Limpia la Torre. Yo vine con la abuela porque la cinta de la abuela decía que yo era de aquí."],
                    ["nino", "Me escribe todos los días. El cartero me las lee porque yo no sé leer bien todavía."]], back: "a" },
      mano: { say: [[null, "Pones la mano sobre el frasco. Debajo se hace una sombra chiquita. El niño tapa el frasco de golpe."],
                    [null, "Lo levanta contra el sol. Adentro no hay nada. Pero él lo mira como si hubiera algo."],
                    ["nino", "Es tu sombra, no la de la casa. Pero es una sombra. Mamá no se va a dar cuenta."]], end: { xp: 10, flag: "e2_frascoSombra" } },
      voz: { say: [[null, "El niño piensa mucho. Luego destapa el frasco, se lo acerca a la boca y canta, muy bajito, la nana de la Sombra. Se equivoca en la mitad. La termina igual."],
                   [null, "Tapa el frasco. Lo aprieta contra el pecho."],
                   ["nino", "Si mamá lo abre, me va a oír. Eso es mejor que una sombra, ¿no?"]], end: { xp: 14, flag: ["e2_frascoVoz", "e2_hondonadaCanta"] } },
      nopuede: { say: [["nino", "Ya sé. Le voy a mandar el frasco vacío igual. Así sabe que lo intenté."]], end: { xp: 4 } },
    } },
  });

  /* ---------- Lago Espejo: el agua que no refleja, el agua que se vende, el vidrio que canta ---------- */
  add("lake", {
    "e2-anea": { kind: "encuentro", need: { era: 2, layer: 1 }, who: { anea: "Anea" }, start: "a", nodes: {
      a: { say: [[null, "En el muelle, la niña de las barcas está sentada con los remos cruzados. Delante, el lago gris, liso, sin un reflejo."],
                 ["anea", "No puedo salir. Antes me guiaba por el cielo del agua: miraba abajo y veía las nubes y sabía para dónde ir. Ahora el agua no tiene cielo. Remo en círculos."],
                 ["anea", "Ayer tres barcas se perdieron. Volvieron de noche, por el ruido de las campanas del muelle."]],
           opts: [{ t: "Subir a su barca y guiar mirando el cielo de verdad", go: "cielo" },
                  { t: "Atar una cuerda del muelle a la barca", go: "cuerda" },
                  { t: "Pedirle a una criatura que nade delante", go: "nadar" },
                  { t: "«Mejor no salgas hasta que el lago vea.»", go: "quedarse" }] },
      cielo: { say: [[null, "Te sientas en la proa con la cabeza para atrás, mirando el cielo. Anea rema. Le dices «izquierda», «derecha»."],
                     ["anea", "Qué raro mirar arriba. Nosotros nunca miramos arriba. El cielo de verdad está muy lejos. El del agua estaba cerca."],
                     [null, "Llegan a la otra orilla. Anea aprende rápido. A la vuelta ya guía ella."]], end: { xp: 14, flag: "e2_aneaCielo" } },
      cuerda: { say: [[null, "Atan una cuerda larga, muy larga, del muelle a la barca. Anea rema hasta donde llega la cuerda y vuelve."],
                      ["anea", "Es como salir con la mano de alguien agarrada. No llegas lejos, pero vuelves."],
                      [null, "Al día siguiente, todas las barcas del muelle tienen cuerdas. El lago parece una telaraña."]], end: { xp: 10, flag: "e2_cuerdasLago" } },
      nadar: { say: [[null, "Una de tus criaturas se tira al agua y nada delante de la barca. Donde nada, el agua se mueve, y donde se mueve, por un instante, aparece un pedacito de reflejo."],
                     ["anea", "¡Ahí! ¡Ahí hay cielo! Cuando algo se mueve, el lago se acuerda."],
                     [null, "Tu criatura sale tiritando. Pero Anea ya sabe algo que nadie sabía."]], end: { xp: 16, flag: "e2_lagoMueve", hurt: 0.05 } },
      quedarse: { say: [["anea", "¿Y comer qué? Las Mareas viven del lago. Si el lago no ve, igual tenemos que comer."],
                        [null, "Vuelve a cruzar los remos. Mira el agua. El agua no la mira."]], end: { xp: 4 } },
    } },

    "e2-cardo": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { cardo: "Cardo, aguador" }, start: "a", nodes: {
      a: { say: [[null, "En la orilla, el aguador del Prado llena barriles con un cucharón. Tiene un carro con un letrero nuevo, pintado con letras doradas: AGUA DEL LAGO CURADO. LIMPIA COMO EL OLVIDO."],
                 ["cardo", "¡Cuidador! ¿Quieres un vaso? Las Casas me la compran por barriles. Dicen que es lo más puro del Claro. No sabe a nada. Literalmente a nada."],
                 [null, "Tiene más barriles que nunca, y un muchacho de las Mareas que le ayuda por la mitad de lo que vale."]],
           opts: [{ t: "Probar un vaso", go: "probar", once: true },
                  { t: "«¿Por qué “limpia como el olvido”?»", go: "olvido", once: true },
                  { t: "«¿Le pagan algo a las Mareas por el agua?»", go: "pagan" },
                  { t: "Comprarle un barril para el Vado", go: "barril", fx: { cost: 15 } },
                  { t: "Volcarle los barriles al lago", go: "volcar" }] },
      probar: { say: [[null, "No sabe a nada. Ni a agua. Es como beber aire frío."],
                      [null, "Al rato, intentas acordarte de lo que soñaste anoche y no puedes. Nada. Como si alguien hubiera limpiado esa parte."]], back: "a" },
      olvido: { say: [["cardo", "Es lo que dicen los que la toman. Duermen como bebés y no sueñan nada. Las Casas la quieren para eso: la gente del Prado tiene pesadillas desde la Velada. Con esto, nada."],
                      ["cardo", "Yo no le veo el problema. ¿Tú quieres soñar con savia negra todas las noches?"]], back: "a" },
      pagan: { say: [["cardo", "¿Pagar? ¿Por el agua? El agua es de todos."],
                     ["cardo", "Bueno. Del lago. Que es de las Mareas. Que no me lo cobran porque no se les ocurrió."],
                     [null, "Se rasca la cabeza. Por primera vez parece incómodo."]],
             opts: [{ t: "«Pague. La mitad, a Madre Marejada.»", go: "mitad" },
                    { t: "«No es asunto mío.»", back: "a" }] },
      mitad: { say: [["cardo", "¿La mitad? Me arruinas."],
                     [null, "Pero hace cuentas con los dedos. Muchas cuentas."],
                     ["cardo", "Un tercio. Y que me dejen poner el letrero. Si las Mareas cobran, que las Mareas también vendan. Así por lo menos lo que se llevan les deja algo."]], end: { xp: 16, flag: ["e2_aguaPagada", "u2_agua"] } },
      barril: { say: [[null, "Llevas un barril al Vado. Tus vecinos lo beben. Esa noche, por primera vez en semanas, nadie se despierta gritando."],
                      [null, "A la mañana, Unísona no reconoce a la vecina de al lado. La mira como a una extraña, y la vecina a ella también. Se les pasa al mediodía."]], end: { xp: 6, heal: 0.25, flag: "e2_aguaOlvido" } },
      volcar: { say: [[null, "Tiras los barriles al lago. El agua vuelve al agua sin hacer ruido. Cardo grita. El muchacho de las Mareas se ríe sin querer."],
                      ["cardo", "¡Eso era el pedido de la Casa Orza! ¿Sabes cuánto…?"],
                      [null, "Te mira. Mira el lago. Está tan quieto como antes. No le importó nada."],
                      ["cardo", "Ni el lago lo quiere de vuelta. Fíjate."]], end: { xp: 12, fight: true, flag: "e2_barrilesVolcados" } },
    } },

    "e2-sargazo": { kind: "dialogo", need: { era: 2, layer: 2 }, who: { sargazo: "Sargazo, el que reza", orilla: "Orilla" }, start: "a", nodes: {
      a: { say: [[null, "En la punta del muelle, el anciano que reza está de rodillas desde hace días. No come. Le han traído pan y lo ha tirado al agua."],
                 ["sargazo", "Orilla lo leyó en el cuaderno viejo. «El lago no reflejó en tres generaciones, hasta que la Cantora lloró en él.» Entonces alguien tiene que llorar."],
                 ["sargazo", "Llevo seis días intentando. No me sale. Soy viejo y lloré todo lo que tenía cuando se murió mi mujer."]],
           opts: [{ t: "«Coma algo. Llorar no se fuerza.»", go: "comer" },
                  { t: "«¿Quién era la Cantora?»", go: "cantora", once: true },
                  { t: "Pedirle a Unísona que se acerque al agua", go: "unisona" },
                  { t: "Sentarte con él, sin decir nada", go: "sentar" }] },
      comer: { say: [["sargazo", "Si como, me duermo. Si me duermo, no lloro. Y el lago sigue ciego."],
                     ["orilla", "Abuelo, el cuaderno no dice que llorar sirva. Dice que pasó. No es lo mismo."],
                     ["sargazo", "Para los que rezamos, sí es lo mismo, niña."]], back: "a" },
      cantora: { say: [["orilla", "La estatua del medio en el Corazón, dicen. La que cantó primero. No sé más. Las páginas viejas están mojadas."],
                     ["sargazo", "Era una de nosotras. Una Marea. Eso lo sé sin cuaderno. Solo una Marea llora en un lago para que vea."]], back: "a" },
      unisona: { say: [[null, "Unísona se asoma al borde del muelle. Mira el agua gris mucho rato."],
                       [null, "Luego hace algo que nunca le viste hacer: se le cae una gota de luz de un ojo. Una sola. Cae al lago."],
                       [null, "Donde cae, el agua se abre en un círculo. Y en el círculo, por un instante, hay un reflejo: no del cielo, no de ustedes. De una mujer de piedra con la boca abierta, llorando."],
                       ["sargazo", "Ahí está. Ahí está."],
                       [null, "Sargazo llora, por fin. Como un niño. El reflejo ya se fue, pero él llora igual."]], end: { xp: 22, flag: ["e2_lagoLlora", "u2_agua"] } },
      sentar: { say: [[null, "Te sientas a su lado. Pasa una hora. Dos. El lago no cambia."],
                      [null, "Al anochecer, Sargazo te ofrece la mitad de un pan que tenía escondido en el bolsillo. Come él la otra mitad."],
                      ["sargazo", "Por lo menos no rezo solo. Eso ya es algo."]], end: { xp: 10, heal: 0.2, flag: "e2_sargazoCome" } },
    } },

    "e2-ola": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { ola: "Ola", fogarin: "Fogarín" }, start: "a", nodes: {
      a: { say: [[null, "En un taller de la orilla, una joven de las Mareas enfría vidrio en el agua del lago. Cada pieza hace un sonido distinto al tocar el agua."],
                 ["ola", "Me llamo Ola. Trabajé dos meses en las forjas del Cráter, cargando carbón. Me fui sin despedirme porque me daba vergüenza que me vieran llorar."],
                 ["ola", "Allá aprendí una cosa: el vidrio largo, cuando lo enfrías, canta. Aquí descubrí otra: si lo enfrías en agua del lago, canta lo que el lago no puede ver."]],
           opts: [{ t: "«¿Qué canta?»", go: "canta", once: true },
                  { t: "«Fogarín hace tubos que cantan. Por lo que usted le dijo.»", go: "fogarin", cNeed: "e2_tuboCanta" },
                  { t: "«Usted escribió una carta que nunca envió.»", go: "carta", cNeed: "olaLetter", once: true },
                  { t: "Ayudarla a enfriar una pieza", go: "ayudar" }] },
      canta: { say: [[null, "Ola mete un tubo en el agua. Suena una nota grave, temblorosa, que sube y baja como una respiración."],
                     ["ola", "Esa es la Raíz durmiendo. Sueña. Cuando sueña feo, la nota se rompe. Ayer se rompió tres veces. La semana pasada, ninguna."],
                     ["ola", "Algo la está molestando más cada día. Y no es aquí. Es más arriba."]], back: "a" },
      fogarin: { say: [["ola", "¿Fogarín? ¿El del fuelle? ¿Hace tubos?"],
                       [null, "Se sonroja hasta las orejas."],
                       ["ola", "No me lo creo. Nunca hablaba. Yo pensaba que no me escuchaba."],
                       ["ola", "Si sus tubos cantan con fuego y los míos con agua… juntos podríamos saber dónde le duele. Dile que venga. No: dile que voy yo."]],
                 opts: [{ t: "«Vamos juntos al Cráter.»", go: "juntos" },
                        { t: "Llevarle tú un tubo de ella", go: "llevar" }] },
      juntos: { say: [[null, "Bajan juntos al Cráter. En el rincón de la forja, Fogarín levanta la vista del fuelle y se queda quieto, con la boca abierta."],
                      ["fogarin", "Ola."],
                      ["ola", "Hola. Me fui sin despedirme. Perdón."],
                      [null, "No dicen nada más en una hora. Juntan los tubos. Uno de fuego, uno de agua. Cuando los apuntan hacia el Prado, los dos cantan la misma nota rota."]], end: { xp: 22, flag: ["e2_olaFogarin", "e2_tuboAfinado", "u2_agua"] } },
      llevar: { say: [[null, "Llevas un tubo de Ola al Cráter. Fogarín lo mira mucho rato sin tocarlo. Luego lo pone al lado del suyo."],
                      ["fogarin", "Cantan igual. Ella tenía razón. Siempre tenía razón."],
                      [null, "No pregunta por ella. Pero esa noche apaga el horno temprano y se va caminando hacia el lago."]], end: { xp: 16, flag: ["e2_olaFogarin", "e2_tuboAfinado"] } },
      carta: { say: [["ola", "¿Cómo sabes eso? Ah. Tú la llevaste. Ya me acuerdo."],
                     ["ola", "Era para mi hermana. Le pedía perdón por irme del lago. Ahora volví y ella se fue al Prado con un permiso de trabajo. Siempre nos cruzamos."]], back: "a" },
      ayudar: { say: [[null, "Metes un tubo al agua. Suena. La nota es baja, y en el medio tiene un golpe, como un hipo."],
                      ["ola", "¿Oíste el golpe? Eso es un pozo nuevo. Cada vez que abren uno, la nota tiene un golpe más. Ya van once."]], end: { xp: 10, flag: "e2_onceGolpes" } },
    } },

    "e2-berro": { kind: "encuentro", need: { era: 2, layer: 2 }, who: { berro: "Berro", nasa: "Abuela Nasa" }, start: "a", nodes: {
      a: { say: [[null, "El niño del palo trae algo en un balde. Lo arrastra con las dos manos, orgulloso y asustado."],
                 ["berro", "¡Miren! Lo pesqué yo solo. Sin anzuelo. Se dejó agarrar."],
                 [null, "En el balde hay un pez enorme, plateado, sin ojos. Donde deberían estar los ojos, la piel es lisa. Nada en círculos, chocando con el borde, tranquilo."]],
           opts: [{ t: "Mirarlo de cerca", go: "mirar", once: true },
                  { t: "«Abuela Nasa, ¿había visto uno así?»", go: "nasa", once: true },
                  { t: "Devolverlo al lago", go: "devolver" },
                  { t: "Llevarlo a Madre Marejada", go: "marejada" },
                  { t: "Dejar que Berro se lo coma, como en el cuento", go: "comer", cNeed: "pezLago" }] },
      mirar: { say: [[null, "No tiene ojos, pero sabe dónde estás. Cuando acercas la mano, se gira hacia ella."],
                     [null, "Por dentro, a través de las escamas, se ve una línea oscura que le corre por el lomo. No es negra. Es gris. Como el lago."]], back: "a" },
      nasa: { say: [["nasa", "En mi vida, no. Pero mi abuela decía que en los años sin reflejo nacían peces ciegos, porque no hacía falta ver en un lago que no muestra nada."],
                  ["nasa", "Decía que si nacían muchos, el lago se olvidaba de que alguna vez tuvo ojos. Y entonces ya no volvía a ver nunca."]], back: "a" },
      devolver: { say: [[null, "Berro protesta, pero te ayuda. El pez cae al agua y se va, despacio, sin chocar con nada."],
                        ["berro", "Bueno. Ya sé dónde hay más. Muchos más. Allá, donde el agua está tibia."]], end: { xp: 8, flag: "e2_pecesCiegos" } },
      marejada: { say: [[null, "Madre Marejada mira el pez mucho rato. Le pone la mano encima del lomo."],
                        [null, "La Madre que antes veía el mañana en el lago cierra los ojos, como si así viera mejor."],
                        [null, "«Está soñando», dice. «Los peces sueñan lo que sueña el lago. Y el lago sueña con la Raíz. Este sueña que tiene hambre.»"]], end: { xp: 16, flag: ["e2_pecesCiegos", "e2_marejadaSabe"] } },
      comer: { say: [["berro", "¿Como el del cuento? ¿El que te hace ver mañana?"],
                     [null, "Lo cocinan en la orilla. Berro come un bocado. Se queda muy quieto. Después llora."],
                     ["berro", "No vi mañana. Vi nada. Todo gris. ¿Así va a ser mañana?"],
                     ["nasa", "No, mi niño. Así es el lago hoy. Mañana no lo sabe nadie. Ni el pez."]], end: { xp: 12, flag: "e2_berroGris" } },
    } },

    "e2-orilla": { kind: "dialogo", need: { era: 2, layer: 3 }, who: { orilla: "Orilla", marejada: "Madre Marejada" }, start: "a", nodes: {
      a: { say: [[null, "Orilla te espera en la casa de Madre Marejada con el cuaderno de hule abierto sobre la mesa. Ha secado las páginas viejas al sol, una por una, con pinzas de ropa."],
                 ["orilla", "Pude leer lo que estaba mojado. No te va a gustar. A mí no me gustó."],
                 [null, "Marejada está sentada en un rincón, en silencio. No mira el cuaderno."]],
           opts: [{ t: "Leer la página", go: "leer" },
                  { t: "«¿Qué dice, en pocas palabras?»", go: "pocas", once: true },
                  { t: "Preguntarle a Marejada qué piensa", go: "madre", once: true }] },
      pocas: { say: [["orilla", "Que la Cantora no lloró por tristeza. Lloró porque le pidieron que cantara para siempre y dijo que sí."],
                     ["orilla", "Y que cuando se volvió piedra, el lago volvió a ver. Una Marea se quedó quieta para siempre para que las demás tuvieran mañana."]], back: "a" },
      madre: { say: [["marejada", "Pienso que mis abuelas lo sabían y no lo dijeron. Igual que yo no dije lo del pozo de mi madre."],
                     ["marejada", "Las Mareas guardamos secretos como el lago guarda piedras. Abajo, donde no molestan. Y un día te das cuenta de que el fondo está lleno y no hay agua."]], back: "a" },
      leer: { say: [[null, "La letra es muy vieja, de otra mano. «Tres generaciones sin ver. Los peces nacían ciegos. Vino una de nosotras, la que mejor cantaba. Dijo: si alguien tiene que quedarse, que sea alguien que quiera.»"],
                    [null, "«Lloró en el lago, porque se despedía. Después subió al Corazón y no bajó. El lago vio esa misma noche. Le pusimos su nombre a la orilla del norte. Después lo olvidamos.»"],
                    ["orilla", "El nombre de la orilla del norte es Orilla. Como yo. Mi madre me puso el nombre de una que se volvió piedra, y no lo sabía."]],
            opts: [{ t: "«Hay que contárselo a todas las Mareas.»", go: "contar" },
                   { t: "«Eso no tiene por qué repetirse.»", go: "repetir" },
                   { t: "Guardar la página en tu libreta", go: "guardar" }] },
      contar: { say: [["orilla", "¿Para qué? ¿Para que alguna de nosotras se ofrezca? Ya hay chicas que miran el Corazón con cara rara desde que se supo lo de la estatua."],
                      ["marejada", "Cuéntalo, hija. Pero cuéntalo entero. Que se vea lo que costó. Un secreto a medias es peor que uno entero."],
                      [null, "Esa noche, en la orilla, Orilla lee la página. Las Mareas escuchan. Nadie se ofrece. Pero nadie se va."]], end: { xp: 18, flag: ["e2_paginaLeida", "u2_agua"], escrito: "e2-pagina-cantora" } },
      repetir: { say: [["orilla", "¿No? ¿Y entonces qué? ¿El lago se queda ciego para siempre?"],
                       [null, "Lo piensa. Cierra el cuaderno."],
                       ["orilla", "Tienes razón en una cosa. Ella eligió. Si alguna vez alguien elige, que sea porque quiere, no porque lo dice un cuaderno. Eso me lo guardo."]], end: { xp: 14, flag: "e2_nadieSeOfrece", escrito: "e2-pagina-cantora" } },
      guardar: { say: [[null, "Copias la página. Orilla te mira copiarla."],
                       ["orilla", "Llévatela al Corazón, si vas. Que alguien que no sea de las Mareas sepa lo que pasó. Así no depende de nosotras olvidarlo."]], end: { xp: 14, flag: "e2_paginaCopiada", escrito: "e2-pagina-cantora" } },
    } },

    "e2-espejo": { kind: "encuentro", need: { era: 2, layer: 3, anyFlag: ["e2_lagoLlora", "e2_lagoMueve", "e2_mudo", "e2_paginaLeida"] }, who: { marejada: "Madre Marejada" }, start: "a", nodes: {
      a: { say: [[null, "A medianoche, el Lago Espejo refleja. No el cielo: otra cosa. Las Mareas salen de sus casas en silencio y se juntan en la orilla."],
                 [null, "En el agua se ve un lugar oscuro y enorme, muy abajo. Algo que duerme encogido, como un animal con frío. Alrededor, cuatro figuras de piedra con las manos abiertas. Y entre las cuatro, un hueco donde debería haber una quinta."],
                 ["marejada", "Es el sueño de la Raíz. Lo está soñando ahora mismo. Y nos lo enseña."]],
           opts: [{ t: "Mirar el reflejo mucho tiempo", go: "mirar" },
                  { t: "Tirar una piedra al agua", go: "piedra" },
                  { t: "Pedirle a Unísona que mire", go: "unisona" },
                  { t: "«Que nadie mire. Vámonos.»", go: "irse" }] },
      mirar: { say: [[null, "Miras. El animal dormido se mueve. Se da vuelta. Por un costado tiene heridas finas, redondas, como de agujas. Por cada herida sube un hilo de luz hacia arriba, hacia el Prado."],
                     [null, "Cuentas. Once heridas. Doce. Mientras miras, se abre una más."],
                     [null, "Te duelen los ojos. Cuando los cierras, sigues viendo las heridas."]], end: { xp: 20, flag: ["e2_suenoRaiz", "e2_vistoFondo"], hurt: 0.1 } },
      piedra: { say: [[null, "La piedra rompe el reflejo. El agua se mueve, y por un instante el lago refleja el cielo de verdad: estrellas, nubes, la luna."],
                      [null, "Las Mareas gritan de alegría. Luego el agua se calma, y vuelve el gris. Ni sueño ni cielo."],
                      ["marejada", "Rompiste lo único que nos enseñaba. Pero vimos el cielo. No sé qué es mejor."]], end: { xp: 10, flag: "e2_cieloVisto" } },
      unisona: { say: [[null, "Unísona mira el reflejo. Mira el hueco entre las cuatro estatuas. Mucho rato."],
                       [null, "Luego da un paso hacia el agua. Otro. Tienes que agarrarla."],
                       ["marejada", "Ese hueco es para alguien que canta. Ella lo sabe. Las criaturas que cantan siempre lo saben."],
                       [null, "Unísona se deja llevar a casa, pero no deja de mirar hacia atrás hasta que el lago se apaga."]], end: { xp: 18, flag: ["e2_suenoRaiz", "e2_unisonaHueco"] } },
      irse: { say: [["marejada", "Tienes razón. Hay cosas que no hay que ver dos veces."],
                    [null, "Las Mareas vuelven a sus casas. Pero esa noche, en el muelle, alguien deja una vela encendida mirando al agua. Y a la noche siguiente, otra."]], end: { xp: 8 } },
    } },
  });

  /* ---------- Cuevas del Eco: lámparas de savia, nombres que se borran, mapas nuevos y el túnel nueve ---------- */
  add("caves", {
    "e2-sebo": { kind: "encuentro", need: { era: 2, layer: 1 }, who: { sebo: "Sebo, el lamparero" }, start: "a", nodes: {
      a: { say: [[null, "En la entrada de la Hondura, el lamparero viejo cuelga lámparas de aceite como siempre. Pero en la galería de al lado, las lámparas son nuevas: frascos de vidrio con algo que brilla solo, sin mecha."],
                 ["sebo", "Savia. Les ponen savia que se filtra de los tubos de arriba. Brilla más que mi aceite y no se acaba. La Hondura está encantada."],
                 ["sebo", "Yo no. Mis lámparas se apagan cuando les falta aire. Así sé si una galería está mala. Estas no se apagan nunca. Con estas se muere uno con luz."]],
           opts: [{ t: "«¿Alguien se ha enfermado?»", go: "enfermo", once: true },
                  { t: "Cambiar las lámparas de savia por las de aceite", go: "cambiar" },
                  { t: "Comprarle aceite para las galerías hondas", go: "aceite", fx: { cost: 15 } },
                  { t: "Llevarte una lámpara de savia para estudiarla", go: "llevar" }] },
      enfermo: { say: [["sebo", "Dos picadores de la galería siete se durmieron trabajando y no se despertaron hasta el otro día. Con la lámpara prendida al lado, brillando como si nada."],
                       ["sebo", "Con mis lámparas, la llama se habría puesto azul y chiquita, y ellos habrían salido. La llama avisa. Esta luz no avisa nada."]], back: "a" },
      cambiar: { say: [[null, "Pasan la tarde descolgando frascos y colgando lámparas de aceite. Los picadores protestan: dan menos luz."],
                       [null, "En la galería siete, la llama de aceite se pone azul en cuanto entras. Todos salen corriendo. Nadie protesta más."],
                       ["sebo", "¿Ves? La llama dice la verdad. Por eso no la quieren."]], end: { xp: 16, flag: ["e2_lamparasAceite", "u2_piedra"] } },
      aceite: { say: [[null, "Sebo te vende aceite a precio de amigo. Llenan las lámparas de las galerías más hondas."],
                      ["sebo", "No es mucho. Pero por lo menos en esas, si algo va mal, alguien se va a enterar a tiempo."]], end: { xp: 10, flag: "e2_lamparasAceite" } },
      llevar: { say: [[null, "Te llevas un frasco de savia brillante. En el Vado, de noche, ilumina el cuarto entero."],
                      [null, "Tus criaturas duermen mal. Unísona lo tapa con una manta. Al tercer día lo devuelves a la cueva."]], end: { xp: 6, flag: "e2_frascoSavia" } },
    } },

    "e2-sordina": { kind: "dialogo", need: { era: 2, layer: 1 }, who: { sordina: "Sordina, peregrina" }, start: "a", nodes: {
      a: { say: [[null, "En la Sala de los Nombres, la peregrina pasa los dedos por la pared, letra por letra, como si leyera a ciegas."],
                 ["sordina", "Se están borrando. Mira. Este nombre lo copié el año pasado entero. Ahora le faltan dos letras. Este, cuatro. La piedra se los está comiendo."],
                 ["sordina", "La Hondura dice que es la humedad. Yo digo que los muertos se están yendo. Si nadie les contesta en la Noche del Eco, se cansan de esperar."]],
           opts: [{ t: "«¿Usted copió la pared entera?»", go: "copio", cNeed: "salaCopiada", once: true },
                  { t: "Ayudarla a repasar las letras con un clavo", go: "repasar" },
                  { t: "Leer los nombres en voz alta, uno por uno", go: "leer" },
                  { t: "«A lo mejor es bueno que se vayan.»", go: "bueno" }] },
      copio: { say: [["sordina", "Contigo, ¿te acuerdas? Ese cuaderno es lo único que queda entero. Lo tengo en la mochila. Pesa como una piedra."],
                     ["sordina", "Pero un nombre en un cuaderno no es lo mismo que un nombre en la Sala. En la Sala el eco lo repite. En el cuaderno solo lo lee quien lo abre."]], back: "a" },
      repasar: { say: [[null, "Repasan letras toda la noche con clavos. La piedra está blanda, demasiado blanda, como pan húmedo."],
                       [null, "A la mañana, las letras que repasaron están marcadas otra vez. Hondas. Pero las de al lado, las que no tocaron, se borraron un poco más."],
                       ["sordina", "No da tiempo. Somos dos y son miles. Pero estos treinta se quedan un año más."]], end: { xp: 14, flag: "e2_nombresRepasados" } },
      leer: { say: [[null, "Lees los nombres en voz alta. Al principio la Sala no contesta. Después de unos cien, oyes algo: no un eco. Un suspiro, muy lejos."],
                    [null, "Sordina se para. Te pone la mano en el brazo."],
                    ["sordina", "No pares. Están escuchando. No contestan, pero escuchan."],
                    [null, "Lees hasta quedarte sin voz. Mil doscientos nombres. Cuando terminas, la Sala está igual de callada, pero ya no se siente vacía."]], end: { xp: 18, flag: ["e2_nombresLeidos", "u2_piedra"] } },
      bueno: { say: [["sordina", "¿Bueno? Puede ser. Los muertos también tienen derecho a descansar de nosotros."],
                     ["sordina", "Pero si se van todos, la Hondura se queda sin pasado. Y un pueblo sin pasado cava donde le dicen, porque no se acuerda de por qué no cavar ahí."]], end: { xp: 6 } },
    } },

    "e2-lindero": { kind: "dialogo", need: { era: 2, layer: 2 }, who: { lindero: "Lindero, agrimensor de Albor" }, start: "a", nodes: {
      a: { say: [[null, "En una galería lateral, el agrimensor de Albor mide la roca con una cuerda de nudos. Ya no lleva el escudo de Albor. Lleva el de Destello, cosido encima, torcido."],
                 ["lindero", "Me cambiaron el escudo, el sueldo y el jefe. El trabajo es el mismo: medir hasta dónde se puede cavar sin que se caiga el techo."],
                 ["lindero", "Lo que no mido es hasta dónde se puede cavar sin que se despierte lo de abajo. Eso no tiene cuerda."]],
           opts: [{ t: "«Usted vendió los mapas viejos de la Hondura.»", go: "mapas", cNeed: "mapasRobados", once: true },
                  { t: "«¿Hasta dónde llegan los Pozos Ciegos?»", go: "llegan", once: true },
                  { t: "Llevarte sus mapas nuevos mientras no mira", go: "robar" },
                  { t: "«Deje de medir. Renuncie.»", go: "renunciar" },
                  { t: "«Marque en el mapa la Línea que no se debe pasar.»", go: "linea" }] },
      mapas: { say: [["lindero", "Los vendió Basalto. Yo los compré. Para Albor. Ahora Destello usa los mismos, con otro sello. Los mapas no saben de quién son."]], back: "a" },
      llegan: { say: [["lindero", "Más hondo que los de Albor. Mucho más. Hay uno, el que llaman el doce, que baja tanto que la cuerda no llega. Tuvimos que atar tres."],
                      ["lindero", "En el fondo del doce, la roca está tibia y blanda. Se hunde cuando la tocas. Y vuelve. Como una piel."]], back: "a" },
      robar: { say: [[null, "Cuando se da vuelta, enrollas los mapas y te los guardas. Lindero tarda en darse cuenta."],
                     ["lindero", "¿Mis mapas? ¡Cuidador! Esos mapas son tres meses de trabajo."],
                     [null, "No te persigue. Se sienta en una piedra y se queda mirando la cuerda de nudos."],
                     ["lindero", "Llévatelos. Así por lo menos alguien que no cava los tiene."]], end: { xp: 14, flag: "e2_mapasNuevos", escrito: "e2-mapa-doce" } },
      renunciar: { say: [["lindero", "¿Y que mida otro, que sepa menos? El que viene después de mí no va a parar en ningún lado. Yo por lo menos paro donde se mueve la piedra."],
                         [null, "No renuncia. Pero esa semana, en el informe a Destello, el pozo doce aparece como «inestable, no seguir»."]], end: { xp: 12, flag: "e2_doceInestable" } },
      linea: { say: [[null, "Lindero mira el mapa mucho rato. Luego saca un carbón y traza una raya roja, horizontal, a cierta profundidad."],
                     ["lindero", "Aquí. Debajo de esta raya, la roca deja de ser roca. Albor nunca pasó de aquí. Destello ya pasó tres veces."],
                     ["lindero", "Llévatelo. Enséñaselo a quien quieras. Lo firmé. Un agrimensor que firma lo que no conviene se queda sin trabajo, pero se queda con el nombre."]], end: { xp: 20, flag: ["e2_lineaFirmada", "u2_piedra"], escrito: "e2-mapa-doce" } },
    } },

    "e2-pirita": { kind: "encuentro", need: { era: 2, layer: 2 }, who: { pirita: "Pirita, picadora", brida: "Brida, capataz" }, start: "a", nodes: {
      a: { say: [[null, "En la boca del túnel sur, la picadora de la Hondura y unas treinta familias se han sentado en el suelo, cerrando el paso. Tienen picos, pero los tienen apoyados en las rodillas."],
                 ["pirita", "Hoy no baja nadie. Ni de la Hondura ni de la Corte ni de ninguna parte. Hasta que nos digan qué hay abajo."],
                 [null, "Del otro lado, con su casco y su tabla, Brida y los capataces de Destello esperan. Detrás de ellos, una fila de cavadores con fichas de madera."]],
           opts: [{ t: "Sentarte con Pirita", go: "sentar" },
                  { t: "Hablar con Brida", go: "brida", once: true },
                  { t: "Enseñar los mapas del pozo doce", go: "mapas", cNeed: "e2_mapasNuevos" },
                  { t: "Convencer a Pirita de que deje pasar", go: "dejar" }] },
      brida: { say: [["brida", "Ella tiene razón y yo tengo una fila de gente que no come si no baja. Las dos cosas son verdad. Eso es lo que no entienden arriba."],
                     ["brida", "Si me das una razón que pueda llevarle a la matriarca, algo que se pueda tocar, le digo que hoy no se baja. Si no, tengo que pasar."]], back: "a" },
      sentar: { say: [[null, "Te sientas en el suelo, entre Pirita y un viejo de la Hondura. Los capataces dudan."],
                      ["brida", "¿Tú también, Cuidador?"],
                      [null, "Brida mira la fila de cavadores. Mira a Pirita. Mira el túnel."],
                      ["brida", "Hoy no se baja. Mañana, ya veremos. Mañana es otro día y otra fila."]], end: { xp: 16, flag: ["e2_tunelCerrado", "u2_piedra"] } },
      mapas: { say: [[null, "Desenrollas los mapas en el suelo, entre las dos filas. El pozo doce baja y baja. Abajo, la letra de Lindero: «la roca se hunde y vuelve»."],
                     [null, "Los cavadores de la fila se acercan a mirar. Algunos se van. Brida sostiene el mapa mucho rato."],
                     ["brida", "Esto sí se puede tocar. Se lo llevo."],
                     ["pirita", "Llévaselo. Y dile que la Hondura no baja más al doce. Ni por el doble ni por el triple."]], end: { xp: 22, flag: ["e2_doceCerrado", "e2_bridaMapa", "u2_piedra"] } },
      dejar: { say: [["pirita", "¿Que deje pasar? ¿Tú? ¿El que se llevó el verso de la Guardiana?"],
                     [null, "Te mira con más tristeza que rabia."],
                     ["pirita", "Bueno. Que pasen. Pero que pasen sobre nosotros, que se vea."],
                     [null, "Nadie pasa sobre nadie. Los cavadores se van a casa. Los capataces también. Pirita se queda sentada sola en la boca del túnel hasta la noche."]], end: { xp: 8, flag: "e2_piritaSola" } },
    } },

    "e2-tunel9": { kind: "encuentro", need: { era: 2, layer: 3, anyFlag: ["e2_ficha", "e2_fichaGuijo", "e2_bajaste"] }, who: { brida: "Brida, capataz", cavador: "Cavador de las manos negras" }, start: "a", nodes: {
      a: { say: [[null, "Con tu ficha en la mano entras por el túnel sur. Bajas mucho. El aire se vuelve tibio, después caliente, después húmedo como el aliento de alguien."],
                 [null, "En el túnel nueve, las paredes tienen venas. Venas de verdad, que laten. Un cavador está sentado contra la pared, con las manos negras hasta los codos. No se mueve."],
                 ["cavador", "No me toques. Se pega. Ya no siento los dedos. Pero sigo picando. Me pagan por día."]],
           opts: [{ t: "«¿Cuánto llevas aquí?»", go: "cuanto", once: true },
                  { t: "Sacarlo a cuestas", go: "sacar" },
                  { t: "Buscar a Grieto entre los cavadores", go: "grieto", cNeed: "e2_buscaGrieto" },
                  { t: "Poner la mano en la pared", go: "pared" }] },
      cuanto: { say: [["cavador", "Tres semanas. Bajé con los carros de la Casa Alba. Me dijeron Hondonada y me trajeron aquí."],
                      ["cavador", "Al principio era solo calor. Después las paredes empezaron a moverse. Después las manos. Brida lo sabe. Brida me cambió al tres, pero yo volví al nueve, porque el nueve paga más."]], back: "a" },
      sacar: { say: [[null, "Te lo cargas a la espalda. Pesa poco: está flaco como un palo. Las manos negras te manchan el cuello y quema, frío."],
                     [null, "En la subida te cruzas con Brida, que baja con una lámpara de aceite. La llama está azul."],
                     ["brida", "Dámelo. Yo lo saco. Tú vuelve arriba y dile a quien quieras lo que viste. Ya no me importa a quién."]], end: { xp: 20, flag: ["e2_cavadorSalvado", "e2_bridaRompe"], hurt: 0.15 } },
      grieto: { say: [[null, "Preguntas por Grieto. Un muchacho flaco, con la cinta gris todavía cosida en el abrigo, levanta la cabeza al fondo de la galería."],
                      ["cavador", "Es ese. El de la casa del puente. Llora de noche. Todos lloramos de noche, pero él se nota."],
                      [null, "Le das la carta. La lee. La vuelve a leer. Suelta el pico."],
                      [null, "«Mi mamá me guarda la cama hecha», dice. Y sube contigo, sin pedirle permiso a nadie."]], end: { xp: 22, flag: ["e2_grietoSube", "u2_sombra"] } },
      pared: { say: [[null, "Pones la mano. La pared es blanda y tibia y se mueve, arriba y abajo, despacio. Respira."],
                     [null, "Y por un momento, en la palma, sientes otra cosa: un temblor, como de alguien que tiene frío. O miedo."],
                     [null, "Retiras la mano. Te queda marcada una huella negra que tarda tres días en irse."]], end: { xp: 14, flag: "e2_paredViva", hurt: 0.1 } },
    } },

    "e2-derrumbe": { kind: "dialogo", need: { era: 2, layer: 3 }, who: { basalto: "Primer Picador Basalto", pirita: "Pirita, picadora" }, start: "a", nodes: {
      a: { say: [[null, "El Primer Picador te lleva a una galería vieja, de las de antes de los mapas. Tiene en la mano un pico que nadie usa desde hace cincuenta años: el pico de los derrumbes."],
                 ["basalto", "Desde aquí se llega por abajo a los túneles nuevos. Si pico en el lugar justo, se viene todo abajo. Los Pozos Ciegos, los tubos, todo."],
                 ["basalto", "Y también la mitad de la Hondura vieja, con la Sala de los Nombres. La piedra no elige qué tumba."]],
           opts: [{ t: "«¿Y la gente que trabaja abajo?»", go: "gente", once: true },
                  { t: "«Hágalo.»", go: "hacer" },
                  { t: "«No. Hay otra forma.»", go: "no" },
                  { t: "Cantar el verso de Grava antes de decidir", go: "grava", cNeed: "e2_ecoGrava" }] },
      gente: { say: [["basalto", "Avisaríamos. Una noche. Con las lámparas de Sebo, que se ponen azules. Los que quieran salir, salen."],
                     ["basalto", "Los que no quieran… Cuidador, yo vendí los mapas. Cada derrumbe que no hago es otro día que alguien baja por mis mapas. Ya no sé cuál de las dos cosas me mata más."]], back: "a" },
      hacer: { say: [["pirita", "¡Espera! La Sala. Mi padre está en esa pared."],
                     [null, "Basalto se para con el pico en alto."],
                     ["basalto", "Tu padre está en un cuaderno de Sordina también, picadora. Los muertos pueden vivir en papel. Los vivos de abajo no."],
                     [null, "Pirita llora. Pero no lo detiene. Esa noche, las lámparas de aceite de la Hondura se ponen azules una por una, y la gente sale. Al amanecer, Basalto pica."],
                     [null, "El ruido se oye hasta el Prado. Media Hondura se viene abajo. Los túneles nuevos también. En el Barrio Apagado, dos calles se quedan a oscuras."]], end: { xp: 26, flag: ["e2_derrumbe", "m2_pozoTapa", "u2_piedra"], hurt: 0.15 } },
      no: { say: [["basalto", "¿Otra forma? Dímela. Llevo un año buscándola."],
                  [null, "No tienes una entera. Tienes pedazos: un mapa, una carta, un tubo que canta, una vieja que se acuerda de un verso."],
                  ["basalto", "Pedazos. Bueno. Mi pueblo hizo la Sala de pedazos de nombres. Probemos tus pedazos. Si fallan, el pico sigue aquí."]], end: { xp: 14, flag: "e2_basaltoEspera" } },
      grava: { say: [[null, "Cantas lo que Grava cantó contigo. La galería vieja contesta. No una palabra: el verso entero, débil, como desde muy lejos."],
                     [null, "«Dormiré mientras nadie beba por debajo de mis sueños.»"],
                     ["basalto", "Ella lo sabía. La Guardiana. Cien años repitiendo lo único que importaba, y nosotros creíamos que estaba loca."],
                     ["basalto", "No voy a derrumbar nada. Si la Raíz pide que nadie beba, lo que hay que hacer es que nadie beba. No enterrar a los que beben."],
                     [null, "Deja el pico en la roca. Esa noche, la Hondura entera va con él al túnel sur, con dos piedras cada uno, a golpear las paredes de los Pozos Ciegos hasta que los cavadores salgan a ver qué pasa."]], end: { xp: 24, flag: ["e2_hondaGolpea", "e2_basaltoViene", "u2_piedra"] } },
    } },

    "e2-eco": { kind: "encuentro", need: { era: 2, layer: 3, anyFlag: ["m2_pozoTapa", "e2_nombresLeidos", "e2_hondaGolpea", "e2_doceCerrado"] }, who: { pirita: "Pirita, picadora", sordina: "Sordina, peregrina" }, start: "a", nodes: {
      a: { say: [[null, "Es otra vez la Noche del Eco. Las familias de la Hondura golpean dos piedras en la Sala y dicen los nombres de sus muertos. Esta vez con menos esperanza que el año pasado."],
                 ["pirita", "Papá."],
                 [null, "Un segundo de silencio. Luego, desde el fondo de la Sala, débil, ronco: «...Papá...». No es la voz de nadie. Es la piedra repitiendo. Pero repite."]],
           opts: [{ t: "Golpear tú también y decir un nombre", go: "golpear" },
                  { t: "Mirar a Pirita", go: "pirita", once: true },
                  { t: "Preguntarle a Sordina qué cambió", go: "cambio", once: true }] },
      pirita: { say: [[null, "Pirita tiene las dos piedras en las manos, apretadas, y no puede seguir. Llora y se ríe a la vez."],
                      ["pirita", "Me contestó. Bueno, contestó la Sala. Pero es lo mismo. Mi papá decía que la Sala y los muertos eran lo mismo."]], back: "a" },
      cambio: { say: [["sordina", "Algo de arriba dejó de beber, aunque sea un poco. La piedra está menos blanda. Cuando la piedra está dura, el eco vuelve."],
                      ["sordina", "No es que los muertos hayan vuelto. Es que la piedra se acuerda otra vez de cómo repetir. Para nosotros es lo mismo."]], back: "a" },
      golpear: { say: [[null, "Golpeas dos piedras. Dices un nombre. El de alguien que perdiste, o el de alguien que te enseñó algo. No importa cuál."],
                       [null, "La Sala tarda. Luego lo repite, bajito, deformado, pero entero."],
                       [null, "Las familias de la Hondura se dan vuelta a mirarte. Alguien te pasa dos piedras más. Te quedas toda la noche, golpeando con ellos."]],
                 opts: [{ t: "Quedarte hasta el final", go: "final" },
                        { t: "Llevar el eco al Corazón, en tu memoria", go: "llevar" }] },
      final: { say: [[null, "A la madrugada, Pirita dice el último nombre. La Sala lo repite. Después, por primera vez en dos años, la Sala dice algo que nadie dijo: «...gracias...»."],
                     [null, "Nadie sabe quién lo dijo primero. A lo mejor nadie. A lo mejor la piedra."],
                     ["pirita", "Si hay que ir al Corazón, la Hondura va. Con todos nuestros muertos detrás."]], end: { xp: 22, flag: ["e2_ecoVuelve", "u2_piedra"] } },
      llevar: { say: [["sordina", "Llévatelo. Y si un día cantas en el Corazón, golpea dos piedras antes. La Raíz se acuerda de nosotros por ese ruido."],
                      [null, "Te da dos piedras planas de la Sala, gastadas de tantos años de golpes."]], end: { xp: 16, flag: ["e2_ecoVuelve", "e2_piedrasSala"], card: true } },
    } },

    "e2-sebo2": { kind: "dialogo", need: { era: 2, layer: 2, anyFlag: ["e2_lamparasAceite", "e2_tunelCerrado", "e2_cavadorSalvado"] }, who: { sebo: "Sebo, el lamparero", brida: "Brida, capataz" }, start: "a", nodes: {
      a: { say: [[null, "El lamparero viejo y la capataz de casco están sentados en la entrada de la Hondura, compartiendo una lámpara de aceite y una botella. Parecen dos personas que se pelearon mucho tiempo y ya no tienen ganas."],
                 ["brida", "Me contó lo de la llama azul. Le pedí lámparas para los Pozos Ciegos. Me dijo que no."],
                 ["sebo", "Le dije que no se las vendo. Que se las regalo. Si la matriarca quiere lámparas que avisen, que no pague. Así no le debe nada a nadie cuando le digan la verdad."]],
           opts: [{ t: "«¿La matriarca va a dejar que las usen?»", go: "dejar", once: true },
                  { t: "Ayudar a cargar las lámparas a los Pozos", go: "cargar" },
                  { t: "«Brida, ¿qué vas a hacer si la llama se pone azul?»", go: "azul" }] },
      dejar: { say: [["brida", "No le voy a preguntar. Las cuelgo y listo. Si me pregunta, le digo que el aceite es más barato."],
                     ["brida", "Es la segunda vez que le miento. La primera me costó una noche sin dormir. Esta, ninguna. Eso me asusta más."]], back: "a" },
      cargar: { say: [[null, "Cargan cuarenta lámparas por el túnel sur. Las cuelgan en cada galería de los Pozos Ciegos."],
                      [null, "En la galería doce, todas las llamas se ponen azules a la vez. Los cavadores se miran. Uno suelta el pico y sube. Otro. Después todos."],
                      ["sebo", "La llama no miente. Por eso la quiero tanto."]], end: { xp: 20, flag: ["e2_llamaAzul", "e2_doceCerrado"] } },
      azul: { say: [["brida", "Sacarlos. A todos. Aunque me cueste el nombre."],
                    ["brida", "La matriarca me preguntó cómo me llamaba. Fue la primera. Pero un nombre que se gana mandando gente a morir no es un nombre, Cuidador. Es una ficha con letras."],
                    [null, "Sebo le pasa la botella. Ella bebe. Después le pone una mano en el hombro al viejo, torpe, como alguien que no lo hace nunca."]], end: { xp: 18, flag: ["e2_bridaRompe", "u2_barrio"] } },
    } },
  });
})(window.EVEVENTS);
